import spidev

MIN_CHANNEL = 0
MAX_CHANNEL = 7
SPI_BUS = 0
SPI_DEVICE = 0
SPI_MAX_SPEED_HZ = 1_000_000


def read_mcp3208_channel(channel, normalized=False):
    """Read a single-ended channel from an MCP3208 12-bit ADC.

    Returns a normalized float (0.0–1.0) or the raw integer count (0–4095)
    on success, or -1 on error.  The SPI connection is always closed.
    """
    if not isinstance(channel, int) or not (MIN_CHANNEL <= channel <= MAX_CHANNEL):
        print(f"Error: channel must be an integer in {MIN_CHANNEL}..{MAX_CHANNEL}, got {channel!r}")
        return -1

    spi = spidev.SpiDev()
    try:
        spi.open(SPI_BUS, SPI_DEVICE)
        spi.max_speed_hz = SPI_MAX_SPEED_HZ
        spi.mode = 0
        spi.lsbfirst = False

        # MCP3208 single-ended read: start bit, config byte, padding
        tx = [0x01, (0x08 | channel) << 4, 0x00]
        rx = spi.xfer2(tx)

        if rx is None or len(rx) < 3:
            print("Error: SPI transfer returned insufficient data.")
            return -1

        value = ((rx[1] & 0x0F) << 8) | rx[2]
        if not normalized:
            return value

        return value / 4095.0

    except FileNotFoundError:
        print("Error: SPI device not found. Enable SPI with 'sudo raspi-config'.")
    except PermissionError:
        print("Error: permission denied opening SPI device. Run as root or add user to 'spi' group.")
    except OSError as exc:
        print(f"Error: SPI I/O failure on channel {channel}: {exc}")
    except Exception as exc:
        print(f"Error: unexpected failure on channel {channel}: {exc}")
    finally:
        try:
            spi.close()
        except Exception:
            pass

    return -1


def read_mcp3208_normalized(channel):
    """Read and return a normalized float (0.0–1.0) from the given channel."""
    return read_mcp3208_channel(channel, normalized=True)


def read_mcp3208_raw(channel):
    """Read and return the raw integer count (0–4095) from the given channel."""
    return read_mcp3208_channel(channel, normalized=False)


if __name__ == "__main__":
    try:
        n = read_mcp3208_normalized(0)
        print(f"Channel 0 normalized: {n if n != -1 else 'ERROR'}")

        r = read_mcp3208_raw(0)
        print(f"Channel 0 raw: {r if r != -1 else 'ERROR'}")

        r = read_mcp3208_raw(8)
        print(f"Channel 8 raw: {r if r != -1 else 'ERROR'}")
    except KeyboardInterrupt:
        print("\nInterrupted by user.")

