import socket
import threading
import time
import signal
import sys
import logging

try:
    import RPi.GPIO as GPIO
    from gpiozero import PWMOutputDevice, DigitalOutputDevice
    from adafruit_circuitpython_mcp3008 import MCP3008
    from digitalio import DigitalInOut, Direction
    from board import SCL, SDA
    _HW_AVAILABLE = True
except ImportError:
    _HW_AVAILABLE = False

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

HOST = '0.0.0.0'
PORT = 12345

MOTOR_A_FORWARD_PIN = 27
MOTOR_A_BACKWARD_PIN = 22
MOTOR_A_ENABLE_PIN = 17
MOTOR_B_CLOCKWISE_PIN = 24
MOTOR_B_COUNTERCLOCKWISE_PIN = 25
MOTOR_B_ENABLE_PIN = 23

SPI_CLK_PIN = 11
SPI_MOSI_PIN = 10
SPI_MISO_PIN = 9
SPI_CS_1_PIN = 8
SPI_CS_2_PIN = 7

MCP3008_CHANNEL_1 = 0
MCP3008_CHANNEL_2 = 1

WATERING_THRESHOLD = 30.0
WATERING_DURATION = 5.0

shutdown_event = threading.Event()


class HardwareInitializationError(Exception):
    pass


class MotorController:
    def __init__(self):
        self.motor_a_forward = None
        self.motor_a_backward = None
        self.motor_a_enable = None
        self.motor_b_clockwise = None
        self.motor_b_counterclockwise = None
        self.motor_b_enable = None

        if not _HW_AVAILABLE:
            logging.warning("RPi.GPIO/gpiozero not available; motor control disabled.")
            return

        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setwarnings(False)

            self.motor_a_forward = DigitalOutputDevice(MOTOR_A_FORWARD_PIN)
            self.motor_a_backward = DigitalOutputDevice(MOTOR_A_BACKWARD_PIN)
            self.motor_a_enable = PWMOutputDevice(MOTOR_A_ENABLE_PIN, frequency=1000)
            self.motor_b_clockwise = DigitalOutputDevice(MOTOR_B_CLOCKWISE_PIN)
            self.motor_b_counterclockwise = DigitalOutputDevice(MOTOR_B_COUNTERCLOCKWISE_PIN)
            self.motor_b_enable = PWMOutputDevice(MOTOR_B_ENABLE_PIN, frequency=1000)

            self.motor_a_forward.off()
            self.motor_a_backward.off()
            self.motor_a_enable.value = 0.0
            self.motor_b_clockwise.off()
            self.motor_b_counterclockwise.off()
            self.motor_b_enable.value = 0.0

            logging.info("Motor controller initialized.")
        except Exception as e:
            logging.error(f"Error initializing motor controller: {e}")
            raise HardwareInitializationError(f"Failed to initialize motor controller: {e}")

    def cleanup(self):
        for dev in (self.motor_a_forward, self.motor_a_backward, self.motor_a_enable,
                    self.motor_b_clockwise, self.motor_b_counterclockwise, self.motor_b_enable):
            if dev is not None:
                try:
                    dev.close()
                except Exception:
                    pass
        if _HW_AVAILABLE:
            try:
                GPIO.cleanup()
            except Exception:
                pass


class SensorReader:
    def __init__(self):
        self.mcp1 = None
        self.mcp2 = None

        if not _HW_AVAILABLE:
            logging.warning("RPi.GPIO/gpiozero not available; sensor reading disabled.")
            return

        try:
            import busio
            import digitalio
            i2c = busio.I2C(SCL, SDA)
            self.mcp1 = MCP3008(i2c, MCP3008_CHANNEL_1)
            self.mcp2 = MCP3008(i2c, MCP3008_CHANNEL_2)
            logging.info("Sensor reader initialized.")
        except Exception as e:
            logging.error(f"Error initializing sensor reader: {e}")
            raise HardwareInitializationError(f"Failed to initialize sensor reader: {e}")

    def read_sensor(self, sensor_number):
        if sensor_number == 1:
            mcp = self.mcp1
        elif sensor_number == 2:
            mcp = self.mcp2
        else:
            logging.error(f"Invalid sensor number: {sensor_number}")
            return -1

        if mcp is None:
            logging.error(f"Sensor {sensor_number} not initialized.")
            return -1

        for _ in range(5):
            try:
                value = mcp.value
                if 0 <= value <= 100:
                    return value
            except Exception as e:
                logging.error(f"Error reading sensor {sensor_number}: {e}")
            time.sleep(0.02)

        logging.error(f"Failed to read sensor {sensor_number} after multiple attempts.")
        return -1

    def cleanup(self):
        if self.mcp1 is not None:
            try:
                self.mcp1.close()
            except Exception:
                pass
        if self.mcp2 is not None:
            try:
                self.mcp2.close()
            except Exception:
                pass


class WateringSystem:
    def __init__(self, motor_controller, sensor_reader):
        self.motor_controller = motor_controller
        self.sensor_reader = sensor_reader
        self.threshold = WATERING_THRESHOLD
        self.watering_duration = WATERING_DURATION
        self.watering_in_progress = False
        self.watering_plant = None
        self.last_health_check = time.time()

    def set_threshold(self, threshold):
        self.threshold = threshold
        logging.info(f"Watering threshold set to: {self.threshold}")

    def set_watering_duration(self, duration):
        self.watering_duration = duration
        logging.info(f"Watering duration set to: {self.watering_duration}")

    def water_plant(self, plant_number):
        if self.watering_in_progress:
            logging.warning("Watering already in progress.")
            return

        if plant_number not in (1, 2):
            logging.error(f"Invalid plant number: {plant_number}")
            return

        sensor_reading = self.sensor_reader.read_sensor(plant_number)
        if sensor_reading == -1:
            logging.error(f"Failed to read sensor {plant_number}.")
            return

        logging.info(f"Sensor {plant_number} reading: {sensor_reading}%")

        if sensor_reading < self.threshold:
            self.watering_in_progress = True
            self.watering_plant = plant_number
            logging.info(f"Starting watering for plant {plant_number}...")
            self._start_watering()
        else:
            logging.info(f"Sensor {plant_number} reading is above threshold. No watering needed.")

    def _start_watering(self):
        try:
            if self.watering_plant == 1:
                self.motor_controller.motor_a_enable.value = 0.5
                self.motor_controller.motor_a_forward.on()
                self.motor_controller.motor_a_backward.off()
                self.motor_controller.motor_b_clockwise.on()
                self.motor_controller.motor_b_counterclockwise.off()
                self.motor_controller.motor_b_enable.value = 0.5
            elif self.watering_plant == 2:
                self.motor_controller.motor_a_enable.value = 0.5
                self.motor_controller.motor_a_forward.off()
                self.motor_controller.motor_a_backward.on()
                self.motor_controller.motor_b_clockwise.off()
                self.motor_controller.motor_b_counterclockwise.on()
                self.motor_controller.motor_b_enable.value = 0.5
            else:
                logging.error(f"Invalid plant number for watering: {self.watering_plant}")
                self.stop_watering()
                return

            time.sleep(self.watering_duration)
            self.stop_watering()
        except Exception as e:
            logging.error(f"Error during watering: {e}")
            self.stop_watering()

    def stop_watering(self):
        try:
            if self.motor_controller.motor_a_enable is not None:
                self.motor_controller.motor_a_enable.value = 0.0
            if self.motor_controller.motor_b_enable is not None:
                self.motor_controller.motor_b_enable.value = 0.0
            if self.motor_controller.motor_a_forward is not None:
                self.motor_controller.motor_a_forward.off()
            if self.motor_controller.motor_a_backward is not None:
                self.motor_controller.motor_a_backward.off()
            if self.motor_controller.motor_b_clockwise is not None:
                self.motor_controller.motor_b_clockwise.off()
            if self.motor_controller.motor_b_counterclockwise is not None:
                self.motor_controller.motor_b_counterclockwise.off()
            self.watering_in_progress = False
            self.watering_plant = None
            logging.info("Watering stopped.")
        except Exception as e:
            logging.error(f"Error stopping watering: {e}")

    def get_sensor_data(self):
        data = {}
        for plant in (1, 2):
            reading = self.sensor_reader.read_sensor(plant)
            data[plant] = reading if reading != -1 else "Error"
        return data

    def health_check(self):
        if time.time() - self.last_health_check >= 60:
            logging.info("Performing health check...")
            self.last_health_check = time.time()


def handle_client(conn, addr, watering_system):
    with conn:
        logging.info(f"Connected by {addr}")
        try:
            while not shutdown_event.is_set():
                data = conn.recv(1024)
                if not data:
                    break
                message = data.decode().strip()
                logging.info(f"Received: {message}")

                if message.startswith("WATER_PLANT_1"):
                    watering_system.water_plant(1)
                elif message.startswith("WATER_PLANT_2"):
                    watering_system.water_plant(2)
                elif message.startswith("GET_SENSOR_DATA"):
                    sensor_data = watering_system.get_sensor_data()
                    response = f"Sensor Data: {sensor_data}\n"
                    conn.sendall(response.encode())
                elif message.startswith("SET_THRESHOLD"):
                    try:
                        value = float(message.split()[1])
                        watering_system.set_threshold(value)
                    except (IndexError, ValueError):
                        conn.sendall(b"Invalid threshold value\n")
                elif message.startswith("SET_WATERING_DURATION"):
                    try:
                        value = float(message.split()[1])
                        watering_system.set_watering_duration(value)
                    except (IndexError, ValueError):
                        conn.sendall(b"Invalid watering duration value\n")
                else:
                    conn.sendall(b"Invalid command\n")
        except Exception as e:
            logging.error(f"Error handling client {addr}: {e}")
        finally:
            logging.info(f"Closing connection with {addr}")


def signal_handler(sig, frame):
    logging.info("Shutdown signal received.")
    shutdown_event.set()


def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    motor_controller = None
    sensor_reader = None
    watering_system = None
    server_socket = None

    try:
        motor_controller = MotorController()
        sensor_reader = SensorReader()
        watering_system = WateringSystem(motor_controller, sensor_reader)

        server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        server_socket.bind((HOST, PORT))
        server_socket.listen(5)
        server_socket.settimeout(1.0)
        logging.info(f"Listening on {HOST}:{PORT}")

        while not shutdown_event.is_set():
            try:
                conn, addr = server_socket.accept()
                client_thread = threading.Thread(target=handle_client, args=(conn, addr, watering_system))
                client_thread.daemon = True
                client_thread.start()
            except socket.timeout:
                watering_system.health_check()
            except Exception as e:
                if not shutdown_event.is_set():
                    logging.error(f"Accept error: {e}")

    except HardwareInitializationError as e:
        logging.error(f"Hardware initialization failed: {e}")
    except Exception as e:
        logging.error(f"Fatal error: {e}")
    finally:
        if server_socket is not None:
            try:
                server_socket.close()
            except Exception:
                pass
        if motor_controller is not None:
            motor_controller.cleanup()
        if sensor_reader is not None:
            sensor_reader.cleanup()
        logging.info("Cleanup complete. Exiting.")


if __name__ == "__main__":
    main()

