                return raw
            else:
                return None
        except Exception as e:
            logging.error(f"Error getting comparator status: {e}")
            return None

    def close(self):
        if self.bus:
            try:
                self.bus.close()
            except Exception as e:
                logging.error(f"Error closing I2C bus: {e}")
            finally:
