            config = self._build_config(mux, pga_settings[pga], sps_settings[sps], CONFIG_MODE_CONTIN)
            self._write_register(REG_POINTER_CONFIG, config)
            if self.debug:
                logging.debug(f"Started continuous conversion on channel {channel}, PGA {pga}, SPS {sps}")
        except Exception as e:
            logging.error(f"Error starting continuous conversion: {e}")

    def get_last_conversion_results(self):
        try:
            if self.conversion_mode == 'continuous':
                raw = self._read_register(REG_POINTER_CONVERT)
                if self.ic_type == ADS1015_IC:
                    raw >>= 4
                self.last_conversion = raw
                if self.debug:
                    logging.debug(f"Continuous mode: raw={raw}")
                return raw
            elif self.conversion_mode == 'single':
                return self.last_conversion
            else:
                return None
        except Exception as e:
            logging.error(f"Error getting last conversion results: {e}")
            return None

    def start_single_ended_comparator(self, channel=0, threshold_high=2047, threshold_low=0, pga=6144, sps=250, active_low=True, traditional_mode=True, latching=False, num_readings=1):
        try:
            self.comparator_mode = True
            self.comparator_active_low = active_low
            self.comparator_latching = latching
            self.comparator_threshold_high = threshold_high
            self.comparator_threshold_low = threshold_low
            self.comparator_readings = num_readings
            self.comparator_readings_taken = 0

            mux = {
                0: CONFIG_MUX_SINGLE_0,
                1: CONFIG_MUX_SINGLE_1,
                2: CONFIG_MUX_SINGLE_2,
                3: CONFIG_MUX_SINGLE_3,
            }.get(channel)

            pga_settings = {
                6144: CONFIG_PGA_6_144V,
                4096: CONFIG_PGA_4_096V,
                2048: CONFIG_PGA_2_048V,
                1024: CONFIG_PGA_1_024V,
                512: CONFIG_PGA_0_512V,
                256: CONFIG_PGA_0_256V,
            }

            if pga not in pga_settings:
                raise ValueError("Invalid PGA value. Must be one of 6144, 4096, 2048, 1024, 512, 256.")

            sps_settings = {
                128: CONFIG_DR_128SPS,
                250: CONFIG_DR_250SPS,
                490: CONFIG_DR_490SPS,
                920: CONFIG_DR_920SPS,
                1600: CONFIG_DR_1600SPS,
                2400: CONFIG_DR_2400SPS,
                3300: CONFIG_DR_3300SPS,
            }

            if sps not in sps_settings:
                raise ValueError("Invalid SPS value. Must be one of 128, 250, 490, 920, 1600, 2400, 3300.")

            if self.comparator_latching:
                self.comparator_queue = CONFIG_CQUE_NONE
            else:
                self.comparator_queue = CONFIG_CQUE_1CONV

            config = self._build_config(mux, pga_settings[pga], sps_settings[sps], CONFIG_MODE_SINGLE, active_low, traditional_mode, latching, num_readings)
            self._write_register(REG_POINTER_CONFIG, config)
            self._write_register(REG_POINTER_HITHRESH, self.comparator_threshold_high)
            self._write_register(REG_POINTER_LOWTHRESH, self.comparator_threshold_low)
            if self.debug:
                logging.debug(f"Started comparator on channel {channel}, PGA {pga}, SPS {sps}, thresholds high={threshold_high}, low={threshold_low}")
        except Exception as e:
            logging.error(f"Error starting comparator: {e}")

