        try:
            config = self._read_register(REG_POINTER_CONFIG)
            if (config & CONFIG_OS_SINGLE) == CONFIG_OS_NOTBUSY:
                raw = self._read_register(REG_POINTER_CONVERT)
                if self.ic_type == ADS1015_IC:
                    raw >>= 4
                self.last_conversion = raw
                if self.debug:
                    logging.debug(f"Comparator mode: raw={raw}")
                return raw
            else:
                return None
        except Exception as e:
            logging.error(f"Error getting comparator status: {e}")
            return None

    def close(self):
        if self.bus:
            try:
                self.bus.close()
            except Exception as e:
                logging.error(f"Error closing I2C bus: {e}")
            finally:
                self.bus = None


