import atexit
import threading
from datetime import datetime

# Constants
MOTION_SENSOR_1_PIN = 17
MOTION_SENSOR_2_PIN = 27
LED_PIN = 22
ILLUMINATION_THRESHOLD = 60
ON_TIME = 60
OFF_DELAY = 300
DEBOUNCE_TIME = 200
SAMPLING_PERIOD = 1.0
DEFAULT_MOTION_THRESHOLD = 2
DEFAULT_SAMPLING_PERIOD = 1.0

# Logging setup
log_level = logging.DEBUG if "DEBUG_MODE" in os.environ else logging.INFO
logging.basicConfig(
    level=log_level,
    format="%(asctime)s - %(levelname)s - %(message)s",
    handlers=[
        logging.FileHandler("occupancy_lights.log"),
        logging.StreamHandler(),
    ],
)


class MotionSensor:
    """Represents a motion sensor using two GPIO pins with rising-edge detection."""

    def __init__(self, pin1, pin2, motion_threshold=DEFAULT_MOTION_THRESHOLD, sampling_period=DEFAULT_SAMPLING_PERIOD):
        self.pin1 = pin1
        self.pin2 = pin2
        self.motion_threshold = motion_threshold
        self.sampling_period = sampling_period
        self.motion_count = 0
        self.lock = threading.Lock()
        self._setup_gpio()
        self._setup_event_detectors()

    def _setup_gpio(self):
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.pin1, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
            GPIO.setup(self.pin2, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
            logging.debug(f"GPIO pins {self.pin1} and {self.pin2} configured as inputs with pull-down.")
        except Exception as e:
            logging.error(f"Error setting up GPIO pins {self.pin1} and {self.pin2}: {e}")
            raise

    def _setup_event_detectors(self):
        try:
            GPIO.add_event_detect(self.pin1, GPIO.RISING, callback=self._motion_detected_callback, bouncetime=DEBOUNCE_TIME)
            GPIO.add_event_detect(self.pin2, GPIO.RISING, callback=self._motion_detected_callback, bouncetime=DEBOUNCE_TIME)
            logging.debug("Event detection added for pins 17 and 27.")
        except Exception as e:
            logging.error(f"Error setting up event detection: {e}")
            raise

    def _motion_detected_callback(self, channel):
        try:
            with self.lock:
                self.motion_count += 1
                logging.debug(f"Motion detected on channel {channel}. Total count: {self.motion_count}")
        except Exception as e:
            logging.error(f"Error in motion detected callback: {e}")

    def check_motion(self):
        try:
            with self.lock:
                if self.motion_count >= self.motion_threshold:
                    self.motion_count = 0
                    return True
                return False
        except Exception as e:
            logging.error(f"Error checking motion: {e}")
            return False

    def reset_motion_count(self):
        try:
            with self.lock:
                self.motion_count = 0
        except Exception as e:
            logging.error(f"Error resetting motion count: {e}")

    def cleanup(self):
        try:
            GPIO.remove_event_detect(self.pin1)
            GPIO.remove_event_detect(self.pin2)
            logging.debug("Event detection removed.")
        except Exception as e:
            logging.error(f"Error cleaning up event detection: {e}")


class LightingController:
    """Controls the lighting system based on motion and illumination levels."""

    def __init__(self, led_pin, motion_sensor, illumination_threshold=ILLUMINATION_THRESHOLD, on_time=ON_TIME, off_delay=OFF_DELAY):
        self.led_pin = led_pin
        self.motion_sensor = motion_sensor
        self.illumination_threshold = illumination_threshold
        self.on_time = on_time
        self.off_delay = off_delay
        self.led_is_on = False
        self.timer = None
        self._setup_gpio()

    def _setup_gpio(self):
        try:
            GPIO.setup(self.led_pin, GPIO.OUT, initial=GPIO.LOW)
            logging.debug(f"LED pin {self.led_pin} configured as output, initial state LOW.")
        except Exception as e:
            logging.error(f"Error setting up LED pin {self.led_pin}: {e}")
            raise

    def turn_on_lights(self):
        try:
            GPIO.output(self.led_pin, GPIO.HIGH)
            self.led_is_on = True
            logging.info("Lights turned ON.")
        except Exception as e:
            logging.error(f"Error turning on lights: {e}")

    def turn_off_lights(self):
        try:
            GPIO.output(self.led_pin, GPIO.LOW)
            self.led_is_on = False
            logging.info("Lights turned OFF.")
        except Exception as e:
            logging.error(f"Error turning off lights: {e}")

    def check_illumination(self):
        try:
            # Simulated LDR reading (replace with actual ADC read if needed)
            ldr_value = 50  # Example: read from ADC or sensor
            logging.debug(f"Simulated LDR value: {ldr_value}")
            return ldr_value > self.illumination_threshold
        except Exception as e:
            logging.error(f"Error checking illumination: {e}")
            return False

    def handle_motion(self):
        try:
            if self.motion_sensor.check_motion():
                if self.check_illumination():
                    self.turn_on_lights()
                    self.schedule_off_time()
                else:
                    logging.debug("Motion detected but illumination below threshold. Lights remain OFF.")
            else:
                logging.debug("No motion detected.")
        except Exception as e:
            logging.error(f"Error handling motion: {e}")

    def schedule_off_time(self):
        try:
            if self.timer is not None and self.timer.is_alive():
                self.timer.cancel()
            self.timer = threading.Timer(self.on_time, self.turn_off_lights_after_delay)
            self.timer.daemon = True
            self.timer.start()
            logging.debug(f"Timer scheduled to turn off lights after {self.on_time} seconds.")
        except Exception as e:
            logging.error(f"Error scheduling off time: {e}")

    def turn_off_lights_after_delay(self):
        try:
            self.turn_off_lights()
            self.schedule_off_delay()
        except Exception as e:
            logging.error(f"Error turning off lights after delay: {e}")

    def schedule_off_delay(self):
        try:
            if self.timer is not None and self.timer.is_alive():
                self.timer.cancel()
            self.timer = threading.Timer(self.off_delay, self.reset_motion_sensor)
            self.timer.daemon = True
            self.timer.start()
            logging.debug(f"Timer scheduled to reset motion sensor after {self.off_delay} seconds.")
        except Exception as e:
            logging.error(f"Error scheduling off delay: {e}")

    def reset_motion_sensor(self):
        try:
            self.motion_sensor.reset_motion_count()
            logging.debug("Motion sensor reset.")
        except Exception as e:
            logging.error(f"Error resetting motion sensor: {e}")

    def cleanup(self):
        try:
            if self.timer is not None and self.timer.is_alive():
                self.timer.cancel()
            self.turn_off_lights()
            self.motion_sensor.cleanup()
            logging.debug("GPIO cleanup completed.")
        except Exception as e:
            logging.error(f"Error during cleanup: {e}")


def main():
    try:
        motion_sensor = MotionSensor(MOTION_SENSOR_1_PIN, MOTION_SENSOR_2_PIN)
        lighting_controller = LightingController(LED_PIN, motion_sensor)

        def motion_callback():
            try:
                lighting_controller.handle_motion()
            except Exception as e:
                logging.error(f"Error in motion callback: {e}")

        motion_sensor.motion_detected_callback = motion_callback

        atexit.register(lighting_controller.cleanup)

        logging.info("Occupancy lighting system started.")

        while True:
            time.sleep(SAMPLING_PERIOD)

    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        GPIO.cleanup()
        logging.info("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

