import time
import datetime
import csv
import json
import socket
import signal
import sys
import spidev
from gpiozero import OutputDevice

# Configuration
MQ4_CHANNEL = 0
MQ7_CHANNEL = 1
MQ135_CHANNEL = 2
BUZZER_PIN = 17
SERVER_IP = "127.0.0.1"
SERVER_PORT = 12345
CH4_THRESHOLD = 50.0
CO_THRESHOLD = 25.0
VOC_THRESHOLD = 100.0
LOG_INTERVAL = 60
CALIBRATION_READINGS = 10
CALIBRATION_DELAY = 3

# Global state
running = True
spi = None
buzzer = None

def signal_handler(sig, frame):
    global running
    running = False

def read_mcp3008(channel):
    if not 0 <= channel <= 7:
        raise ValueError("Channel must be 0-7")
    try:
        # SPI command: start bit, single-ended mode, channel selection
        r = spi.xfer2([1, (8 + channel) << 4, 0])
        adc = ((r[1] & 3) << 8) + r[2]
        return adc
    except Exception as e:
        print(f"SPI read error on channel {channel}: {e}")
        return None

def calculate_resistance(adc_value, adc_max=1023, r_dry_air=10000.0):
    if adc_value is None:
        return None
    try:
        # Inverse of the voltage divider: (adc_max * r_dry_air) / adc_value
        return (adc_max * r_dry_air) / float(adc_value)
    except Exception as e:
        print(f"Calculation error: {e}")
        return None

def calculate_ppm(resistance, r0, a, b):
    if resistance is None or r0 is None:
        return None
    try:
        # ppm = a * (resistance / r0)^b
        return a * (resistance / r0) ** b
    except Exception as e:
        print(f"Calculation error: {e}")
        return None

def log_data(filename, timestamp, ch4, co, voc):
    try:
        with open(filename, 'a', newline='') as f:
            writer = csv.writer(f)
            writer.writerow([timestamp, ch4, co, voc])
    except Exception as e:
        print(f"Logging error: {e}")

def send_data(timestamp, ch4, co, voc):
    try:
        data = {
            "timestamp": timestamp,
            "ch4": ch4,
            "co": co,
            "voc": voc
        }
        json_data = json.dumps(data)
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
            s.settimeout(5.0)
            s.connect((SERVER_IP, SERVER_PORT))
            s.sendall(json_data.encode('utf-8'))
    except Exception as e:
        print(f"Network error: {e}")

def activate_buzzer():
    if buzzer:
        buzzer.on()
        time.sleep(1)
        buzzer.off()

def cleanup():
    global spi, buzzer
    if buzzer:
        buzzer.close()
    if spi:
        spi.close()
    print("Resources cleaned up.")

def main():
    global spi, buzzer
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        spi = spidev.SpiDev()
        spi.open(0, 0)
        spi.max_speed_hz = 1000000
        spi.mode = 0
    except Exception as e:
        print(f"SPI initialization error: {e}")
        sys.exit(1)

    try:
        buzzer = OutputDevice(BUZZER_PIN, active_high=True, initial_value=False)
    except Exception as e:
        print(f"Buzzer initialization error: {e}")
        sys.exit(1)

    r0_mq4 = r0_mq7 = r0_mq135 = None

    try:
        while running:
            now = datetime.datetime.now()
            timestamp = now.strftime("%Y-%m-%d %H:%M:%S")

            # Calibration
            if r0_mq4 is None:
                print("Calibrating MQ-4...")
                readings = []
                for _ in range(CALIBRATION_READINGS):
                    if not running:
                        break
                    val = read_mcp3008(MQ4_CHANNEL)
                    if val is not None:
                        readings.append(val)
                    time.sleep(CALIBRATION_DELAY)
                if readings:
                    r0_mq4 = sum(readings) / len(readings)
                    print(f"MQ-4 R0: {r0_mq4:.2f}")
                else:
                    print("MQ-4 calibration failed.")

            if r0_mq7 is None:
                print("Calibrating MQ-7...")
                readings = []
                for _ in range(CALIBRATION_READINGS):
