import sys
import logging

import board
import busio
import adafruit_lsm303_accel
import adafruit_lsm303dlh_mag
import adafruit_ads1x15.ads1015 as ADS
from adafruit_ads1x15.analog_in import AnalogIn
import digitalio
from pwmio import PWMOut

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class MotorController:
    def __init__(self, dir_pin, step_pin, ms0_pin, ms1_pin):
        self.dir_pin = dir_pin
        self.step_pin = step_pin
        self.ms0_pin = ms0_pin
        self.ms1_pin = ms1_pin
        self.pwm = None
        self._init_gpio()

    def _init_gpio(self):
        try:
            self.dir_pin.direction = digitalio.Direction.OUTPUT
            self.step_pin.direction = digitalio.Direction.OUTPUT
            self.ms0_pin.direction = digitalio.Direction.OUTPUT
            self.ms1_pin.direction = digitalio.Direction.OUTPUT
            self.dir_pin.value = True
            self.ms0_pin.value = False
            self.ms1_pin.value = False
        except Exception as e:
            logging.error(f"GPIO initialization failed: {e}")
            raise

    def set_resolution(self, resolution):
        if resolution == 1:
            self.ms0_pin.value = False
            self.ms1_pin.value = False
        elif resolution == 2:
            self.ms0_pin.value = True
            self.ms1_pin.value = False
        elif resolution == 4:
            self.ms0_pin.value = False
            self.ms1_pin.value = True
        elif resolution == 8:
            self.ms0_pin.value = True
            self.ms1_pin.value = True
        else:
            raise ValueError("Resolution must be 1, 2, 4, or 8")

    def set_direction(self, clockwise):
        self.dir_pin.value = clockwise

    def set_pwm_frequency(self, frequency):
        if self.pwm is None:
            self.pwm = PWMOut(self.step_pin, frequency=frequency, duty_cycle=0)
        else:
            self.pwm.frequency = frequency

    def set_duty_cycle(self, duty_cycle):
        if self.pwm is None:
            raise RuntimeError("PWM not initialized")
        self.pwm.duty_cycle = duty_cycle

    def stop(self):
        if self.pwm is not None:
            self.pwm.duty_cycle = 0
            self.pwm.deinit()
            self.pwm = None

class ADCManager:
    def __init__(self, i2c):
        self.i2c = i2c
        self.adc = None
        self.channel = None

    def initialize(self, gain=1):
        try:
            self.adc = ADS.ADS1015(self.i2c, address=0x48)
            self.adc.gain = gain
            self.channel = AnalogIn(self.adc, ADS.P0)
        except Exception as e:
            logging.error(f"ADC initialization failed: {e}")
            raise

    def read_voltage(self):
        try:
            return self.channel.voltage
        except Exception as e:
            logging.error(f"ADC read failed: {e}")
            return 0.0

class CompassManager:
    def __init__(self, i2c):
        self.mag = None
        try:
            self.mag = adafruit_lsm303dlh_mag.LSM303DLH_Mag(i2c)
        except Exception as e:
            logging.error(f"Magnetometer initialization failed: {e}")

    def read_magnetic(self):
        if self.mag is None:
            return 0.0, 0.0, 0.0
        try:
            return self.mag.magnetic
        except Exception as e:
            logging.error(f"Magnetometer read failed: {e}")
            return 0.0, 0.0, 0.0

    def calculate_heading(self, mag_x, mag_y):
        try:
            heading = 360 - (180 / 3.141592653589793 * (mag_x * 0.1))
            if heading < 0:
                heading += 360
            return heading
        except Exception as e:
            logging.error(f"Heading calculation failed: {e}")
            return 0.0

    def calculate_inclination(self, acc_x, acc_y, acc_z):
        try:
            xz = 180 / 3.141592653589793 * (acc_x * 0.1)
            yz = 180 / 3.141592653589793 * (acc_y * 0.1)
            return xz, yz
        except Exception as e:
            logging.error(f"Inclination calculation failed: {e}")
            return 0.0, 0.0

class AccelerometerManager:
    def __init__(self, i2c):
        self.accel = None
        try:
            self.accel = adafruit_lsm303_accel.LSM303_Accel(i2c)
        except Exception as e:
            logging.error(f"Accelerometer initialization failed: {e}")

    def read_acceleration(self):
        if self.accel is None:
            return 0.0, 0.0, 0.0
        try:
            return self.accel.acceleration
        except Exception as e:
            logging.error(f"Accelerometer read failed: {e}")
            return 0.0, 0.0, 0.0

class DataLogger:
    def __init__(self):
        self.running = True

    def stop(self):
        self.running = False

    def log_data(self, adc_voltage, adc_duty_cycle, acc_x, acc_y, acc_z, mag_x, mag_y, mag_z, heading, xz, yz):
        print(f"ADC Voltage: {adc_voltage:.3f} V, Duty Cycle: {adc_duty_cycle}")
        print(f"Acceleration: x={acc_x:.3f}, y={acc_y:.3f}, z={acc_z:.3f} m/s^2")
        print(f"Magnetic Field: x={mag_x:.3f}, y={mag_y:.3f}, z={mag_z:.3f} gauss")
        print(f"Heading: {heading:.2f} degrees, Inclination: XZ={xz:.2f}, YZ={yz:.2f} degrees")

def main():
    i2c = None
    motor = None
    adc = None
    compass = None
    accelerometer = None
    logger = None

    def signal_handler(sig, frame):
        logging.info("Shutting down...")
        if logger:
            logger.stop()
        if motor:
            motor.stop()
        if i2c:
            i2c.deinit()
        sys.exit(0)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        motor = MotorController(board.D20, board.D21, board.D14, board.D15)
        adc = ADCManager(i2c)
        adc.initialize()
        compass = CompassManager(i2c)
        accelerometer = AccelerometerManager(i2c)
        logger = DataLogger()

        motor.set_resolution(1)
        motor.set_direction(False)
        motor.set_pwm_frequency(500)

        while logger.running:
            adc_voltage = adc.read_voltage()
            adc_duty_cycle = int((adc_voltage / 3.3) * 255)
            adc_duty_cycle = max(0, min(255, adc_duty_cycle))
            motor.set_duty_cycle(adc_duty_cycle)

            acc_x, acc_y, acc_z = accelerometer.read_acceleration()
            mag_x, mag_y, mag_z = compass.read_magnetic()
            heading = compass.calculate_heading(mag_x, mag_y)
            xz, yz = compass.calculate_inclination(acc_x, acc_y, acc_z)

            logger.log_data(adc_voltage, adc_duty_cycle, acc_x, acc_y, acc_z, mag_x, mag_y, mag_z, heading, xz, yz)
            time.sleep(1)

    except Exception as e:
        logging.error(f"An error occurred: {e}")
    finally:
        if motor:
            motor.stop()
        if i2c:
            i2c.deinit()

if __name__ == "__main__":
    main()

