import smbus
import time
import signal
import sys

# ADS1115 constants
ADS1115_ADDRESS = 0x48
ADS1115_REG_CONVERSION = 0x00
ADS1115_REG_CONFIG = 0x01

# Config-register bit fields
CONFIG_OS_SINGLE = 0x8000
CONFIG_MUX_OFFSET = 12
CONFIG_PGA_4_096V = 0x02
CONFIG_MODE_SINGLE = 0x01
CONFIG_DR_128SPS = 0x0080
CONFIG_CQUE_NONE = 0x0003

I2C_BUS = 1
ADC_CHANNELS = 4
READ_TIMEOUT = 0.1
LOOP_DELAY = 0.05

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def _build_config(channel):
    if not 0 <= channel < ADC_CHANNELS:
        raise ValueError(f"Invalid channel {channel}; must be 0–3")
    return (
        CONFIG_OS_SINGLE
        | (channel << CONFIG_MUX_OFFSET)
        | CONFIG_PGA_4_096V
        | CONFIG_MODE_SINGLE
        | CONFIG_DR_128SPS
        | CONFIG_CQUE_NONE
    )


def _swap_bytes(word):
    return ((word & 0xFF00) >> 8) | ((word & 0x00FF) << 8)


def read_adc_channel(bus, channel):
    config = _build_config(channel)
    try:
        bus.write_word_data(ADS1115_ADDRESS, ADS1115_REG_CONFIG, _swap_bytes(config))
    except OSError as exc:
        print(f"[ch{channel}] I2C write error: {exc}")
        return None

    deadline = time.monotonic() + READ_TIMEOUT
    while True:
        try:
            raw = bus.read_word_data(ADS1115_ADDRESS, ADS1115_REG_CONFIG)
        except OSError as exc:
            print(f"[ch{channel}] I2C read error: {exc}")
            return None
        if raw & CONFIG_OS_SINGLE:
            break
        if time.monotonic() > deadline:
            print(f"[ch{channel}] conversion timeout")
            return None
        time.sleep(0.001)

    try:
        raw = bus.read_word_data(ADS1115_ADDRESS, ADS1115_REG_CONVERSION)
    except OSError as exc:
        print(f"[ch{channel}] I2C read error: {exc}")
        return None
    return _swap_bytes(raw)


def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        bus = smbus.SMBus(I2C_BUS)
    except OSError as exc:
        print(f"Failed to open I2C bus {I2C_BUS}: {exc}")
        sys.exit(1)

    try:
        while _running:
            print("| {:>5} | {:>5} | {:>5} | {:>5} |".format(*(
                f"{read_adc_channel(bus, ch):05d}"
                for ch in range(ADC_CHANNELS)
            )))
            time.sleep(LOOP_DELAY)
    finally:
        bus.close()
        print("\nI2C bus released. Exiting.")


if __name__ == "__main__":
    main()

