import signal
import sys
import time
import board
import busio
import adafruit_lsm303_accel
import adafruit_lsm303dlh_mag
import adafruit_ads1x15
from adafruit_ads1x15.analog_in import AnalogIn
from adafruit_extended_bus import ExtendedI2C as I2C
import RPi.GPIO as GPIO

# --- Constants ---
MOTOR_DIR_PIN = 20
MOTOR_STEP_PIN = 21
MOTOR_MS0_PIN = 14
MOTOR_MS1_PIN = 15
PWM_FREQUENCY = 500
ADC_GAIN = 1
ADC_CHANNEL = 0
ADC_I2C_ADDRESS = 0x48

# --- Globals for cleanup ---
pwm = None
running = True


def cleanup():
    global pwm
    if pwm is not None:
        try:
            pwm.stop()
        except Exception:
            pass
    try:
        GPIO.cleanup()
    except Exception:
        pass


def signal_handler(signum, frame):
    global running
    running = False


def init_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    for pin in (MOTOR_DIR_PIN, MOTOR_STEP_PIN, MOTOR_MS0_PIN, MOTOR_MS1_PIN):
        GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)


def init_i2c():
    try:
        i2c = I2C(board.SCL, board.SDA)
        while not i2c.try_lock():
            time.sleep(0.01)
        i2c.unlock()
        return i2c
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None


def init_accelerometer(i2c):
    try:
        return adafruit_lsm303_accel.LSM303_Accel(i2c)
    except Exception as e:
        print(f"Error initializing accelerometer: {e}")
        return None


def init_magnetometer(i2c):
    try:
        return adafruit_lsm303dlh_mag.LSM303DLH_Mag(i2c)
    except Exception as e:
        print(f"Error initializing magnetometer: {e}")
        return None


def init_ads1015(i2c):
    try:
        return adafruit_ads1x15.ADS1015(i2c, address=ADC_I2C_ADDRESS)
    except Exception as e:
        print(f"Error initializing ADS1015: {e}")
        return None


def init_adc_channel(ads, gain):
    try:
        return AnalogIn(ads, ADC_CHANNEL, gain=gain)
    except Exception as e:
        print(f"Error initializing ADC channel {ADC_CHANNEL}: {e}")
        return None


def set_motor_direction(clockwise):
    GPIO.output(MOTOR_DIR_PIN, GPIO.LOW if clockwise else GPIO.HIGH)


def set_motor_microstep(ms0, ms1):
    GPIO.output(MOTOR_MS0_PIN, GPIO.LOW if ms0 else GPIO.HIGH)
    GPIO.output(MOTOR_MS1_PIN, GPIO.LOW if ms1 else GPIO.HIGH)


def calculate_duty_cycle(adc_value):
    if adc_value is None:
        return 0
    return int((adc_value / 2047.0) * 255)


def read_accelerometer(accel):
    try:
        return accel.acceleration
    except Exception as e:
        print(f"Error reading accelerometer: {e}")
        return None


def read_magnetometer(mag):
    try:
        return mag.heading
    except Exception as e:
        print(f"Error reading magnetometer: {e}")
        return None


def read_adc(adc, channel):
    try:
        return channel.value
    except Exception as e:
        print(f"Error reading ADC channel {ADC_CHANNEL}: {e}")
        return None


def main():
    global pwm

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    init_gpio()
    i2c = init_i2c()
    if i2c is None:
        cleanup()
        sys.exit(1)

    accel = init_accelerometer(i2c)
    mag = init_magnetometer(i2c)
    ads = init_ads1015(i2c)
    adc_channel = init_adc_channel(ads, ADC_GAIN) if ads is not None else None

    if accel is None or mag is None or ads is None or adc_channel is None:
        cleanup()
        sys.exit(1)

    try:
        pwm = GPIO.PWM(MOTOR_STEP_PIN, PWM_FREQUENCY)
        pwm.start(0)
    except Exception as e:
        print(f"Error initializing PWM on GPIO {MOTOR_STEP_PIN}: {e}")
        cleanup()
        sys.exit(1)

    set_motor_direction(False)
    set_motor_microstep(False, False)

    try:
        while running:
            accel_data = read_accelerometer(accel)
            if accel_data is not None:
                print(f"Acceleration: x={accel_data[0]:.2f}, y={accel_data[1]:.2f}, z={accel_data[2]:.2f}")

            heading = read_magnetometer(mag)
            if heading is not None:
                print(f"Heading: {heading:.2f}")

            adc_value = read_adc(ads, adc_channel)
            if adc_value is not None:
                voltage = adc_value * (4.096 / 32768.0)
                print(f"ADC Raw Value: {adc_value}, Voltage: {voltage:.4f} V")

                duty_cycle = calculate_duty_cycle(adc_value)
                pwm.ChangeDutyCycle(duty_cycle)
                print(f"PWM Duty Cycle: {duty_cycle}")
            else:
                pwm.ChangeDutyCycle(0)

            time.sleep(1)
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

