import time
import argparse
import threading
import queue
import spidev
import RPi.GPIO as GPIO


class SoundSensor:
    """
    A class to encapsulate the functionality of a sound sensor,
    including debouncing, event detection, and logging.
    """

    def __init__(self, sensor_id, sensor_type, threshold, sample_rate,
                 gpio_pins=None, channels=None, spi_speed=1000000,
                 log_queue=None):
        self.sensor_id = sensor_id
        self.sensor_type = sensor_type
        self.threshold = threshold
        self.sample_rate = sample_rate
        self.gpio_pins = gpio_pins
        self.channels = channels
        self.spi_speed = spi_speed
        self.log_queue = log_queue
        self.spi = None
        self.stop_event = threading.Event()
        self.is_digital = gpio_pins is not None
        self.is_analog = channels is not None

        if self.is_digital:
            self._setup_digital_gpio()
        elif self.is_analog:
            self._setup_analog_spi()
        else:
            raise ValueError("Either gpio_pins or channels must be provided.")

    def _setup_digital_gpio(self):
        """Sets up the GPIO pins for digital input."""
        try:
            GPIO.setmode(GPIO.BCM)
            for pin in self.gpio_pins:
                GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
        except Exception as e:
            self._log_error(f"Error setting up GPIO: {e}")
            raise

    def _setup_analog_spi(self):
        """Sets up the SPI interface for analog input."""
        try:
            self.spi = spidev.SpiDev()
            self.spi.open(0, 0)
            self.spi.max_speed_hz = self.spi_speed
            self.spi.mode = 0
        except Exception as e:
            self._log_error(f"Error setting up SPI: {e}")
            raise

    def _read_digital(self):
        """Reads the digital state of the sound sensor."""
        try:
            return [GPIO.input(pin) for pin in self.gpio_pins]
        except Exception as e:
            self._log_error(f"Error reading digital sensor: {e}")
            return None

    def _read_analog(self):
        """Reads the analog value from the MCP3008 ADC."""
        try:
            adc = self.spi.xfer2([1, (8 + self.channels[0]) << 4, 0])
            data = ((adc[1] & 3) << 8) + adc[2]
            return data
        except Exception as e:
            self._log_error(f"Error reading analog sensor: {e}")
            return None

    def _log_error(self, message):
        """Logs an error message to the log queue."""
        if self.log_queue:
            self.log_queue.put(f"{self.sensor_id}: {message}")

    def _detect_event(self, value):
        """Detects an event based on the sensor type and threshold."""
        if value is None:
            return False

        if self.sensor_type == "digital":
            return bool(value)
        elif self.sensor_type == "analog":
            return value >= self.threshold
        else:
            self._log_error(f"Invalid sensor type: {self.sensor_type}")
            return False

    def run(self):
        """Main loop for reading and processing sensor data."""
        if self.is_digital:
            read_func = self._read_digital
        elif self.is_analog:
            read_func = self._read_analog

        sample_interval = 1.0 / self.sample_rate
        last_event_time = 0.0

        while not self.stop_event.is_set():
            try:
                value = read_func()

                if value is not None:
                    if self._detect_event(value):
                        current_time = time.time()
                        if current_time - last_event_time >= 0.1:
                            log_message = (f"{self.sensor_id}: "
                                           f"Event detected (value={value})")
                            if self.log_queue:
                                self.log_queue.put(log_message)
                            last_event_time = current_time

                time.sleep(sample_interval)

            except Exception as e:
                self._log_error(f"Error in sensor loop: {e}")
                time.sleep(sample_interval)

    def stop(self):
        """Stops the sensor reading loop."""
        self.stop_event.set()

    def cleanup(self):
        """Cleans up GPIO resources."""
        if self.is_digital:
            try:
                GPIO.cleanup()
            except Exception as e:
                print(f"Error cleaning up GPIO: {e}")
        elif self.is_analog and self.spi:
            try:
                self.spi.close()
            except Exception as e:
                print(f"Error closing SPI: {e}")


def main():
    parser = argparse.ArgumentParser(description="Sound Sensor Monitor")
    parser.add_argument("--sensor_type", required=True,
                        choices=["digital", "analog"],
                        help="Type of sound sensor (digital or analog)")
    parser.add_argument("--threshold", type=int, required=True,
                        help="Threshold value for event detection")
    parser.add_argument("--sample_rate", type=int, required=True,
                        help="Sampling rate in Hz")
    parser.add_argument("--log_file", type=str, required=True,
                        help="Path to the log file")
    parser.add_argument("--gpio_pins", nargs="+", type=int,
                        help="GPIO pins for digital sensors (BCM numbering)")
    parser.add_argument("--channels", nargs="+", type=int,
                        help="MCP3008 channels for analog sensors")
    parser.add_argument("--spi_speed", type=int, default=1000000,
                        help="SPI speed in Hz")
    parser.add_argument("--sensor_ids", nargs="+", required=True,
                        help="Unique IDs for each sound sensor")

    args = parser.parse_args()

    log_queue = queue.Queue()
    threads = []

    for sensor_id in args.sensor_ids:
        try:
            sensor = SoundSensor(
                sensor_id=sensor_id,
                sensor_type=args.sensor_type,
                threshold=args.threshold,
                sample_rate=args.sample_rate,
                gpio_pins=args.gpio_pins,
                channels=args.channels,
                spi_speed=args.spi_speed,
                log_queue=log_queue
            )
            thread = threading.Thread(target=sensor.run, daemon=True)
            threads.append(thread)
            thread.start()
        except Exception as e:
            print(f"Error creating sensor {sensor_id}: {e}")

    try:
        while True:
            try:
                message = log_queue.get(timeout=1)
                print(message)
            except queue.Empty:
                continue
    except KeyboardInterrupt:
        print("Shutting down...")
    finally:
        for thread in threads:
            thread.stop()
            thread.join(timeout=2)
        for sensor in threads:
            sensor.cleanup()


if __name__ == "__main__":
    main()

