import spidev
import time
import signal
import sys

# Constants for gas sensor and alert levels
GAS_SENSOR_CHANNEL = 0
SPI_BUS = 0
SPI_DEVICE = 0
SPI_SPEED_HZ = 1350000

# Concentration thresholds (ppm)
ALERT_LEVEL_SAFE = 150
ALERT_LEVEL_WARNING = 400

# Global SPI device handle for signal handler cleanup
_spi_device = None


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM to ensure SPI device is closed."""
    global _spi_device
    print(f"\nReceived signal {signum}, cleaning up...")
    if _spi_device is not None:
        try:
            _spi_device.close()
            print("SPI device closed.")
        except Exception as e:
            print(f"Error closing SPI device: {e}")
    sys.exit(0)


class MCP3008:
    """Interface for MCP3008 ADC using spidev."""

    def __init__(self, bus=SPI_BUS, device=SPI_DEVICE, speed_hz=SPI_SPEED_HZ):
        self.spi = spidev.SpiDev()
        try:
            self.spi.open(bus, device)
            self.spi.max_speed_hz = speed_hz
            self.spi.mode = 0
        except OSError as e:
            print(f"Error initializing SPI (bus {bus}, device {device}): {e}")
            raise

    def read_channel(self, channel):
        """Reads the raw 10-bit value from the specified channel (0-7)."""
        if not 0 <= channel <= 7:
            raise ValueError("Channel must be between 0 and 7")
        try:
            # MCP3008 command format: start bit, single-ended mode, channel
            # Byte 1: 0x01 (start bit)
            # Byte 2: (0x08 | channel) << 4  (single-ended + channel)
            # Byte 3: 0x00 (dummy byte for clocking data out)
            adc = self.spi.xfer2([0x01, (0x08 | channel) << 4, 0x00])
            # Extract 10-bit value: bits 1-2 of byte 1, all of byte 2
            data = ((adc[1] & 0x03) << 8) | adc[2]
            return data
        except OSError as e:
            print(f"SPI bus error reading channel {channel}: {e}")
            raise

    def close(self):
        """Closes the SPI connection."""
        try:
            self.spi.close()
        except Exception as e:
            print(f"Error closing SPI connection: {e}")


def read_gas_sensor(adc, channel):
    """Reads the raw ADC value from the gas sensor channel."""
    return adc.read_channel(channel)


def convert_to_ppm(adc_value):
    """Converts the raw ADC value to an estimated ppm concentration."""
    # MQ-2: raw 0-1023 maps to ~0-1000 ppm (calibration dependent)
    # This is a simplified linear mapping; real implementation uses calibration
    return adc_value * 10.0


def check_gas_level(ppm_value):
    """Checks the ppm value and returns an alert level string."""
    if ppm_value < ALERT_LEVEL_SAFE:
        return "safe"
    elif ppm_value < ALERT_LEVEL_WARNING:
        return "warning"
    else:
        return "danger"


def main():
    """Main function to read gas sensor and display alert level."""
    global _spi_device

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        adc = MCP3008()
        _spi_device = adc

        for i in range(12):
            try:
                raw_value = read_gas_sensor(adc, GAS_SENSOR_CHANNEL)
                ppm_value = convert_to_ppm(raw_value)
                alert_level = check_gas_level(ppm_value)
                print(f"Reading {i + 1}: Gas level = {ppm_value:.1f} ppm, Alert = {alert_level}")
            except OSError as e:
                print(f"Error reading gas sensor on sample {i + 1}: {e}")
                break
            time.sleep(0.5)

    except OSError as e:
        print(f"Fatal SPI error: {e}")
    except ValueError as e:
        print(f"Configuration error: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        if _spi_device is not None:
            _spi_device.close()
            print("SPI device closed.")


if __name__ == "__main__":
    main()

