import time
import datetime
import os
import json
import spidev
import RPi.GPIO as GPIO

CONFIG_FILE = os.path.expanduser("~/config.json")
LOG_FILE = os.path.expanduser("~/logs/industrial_air_quality.log")

def load_config(config_file):
    try:
        with open(config_file, "r") as f:
            return json.load(f)
    except FileNotFoundError:
        print(f"Error: Configuration file not found: {config_file}")
        return None
    except json.JSONDecodeError as e:
        print(f"Error: Invalid JSON format in configuration file: {e}")
        return None
    except IOError as e:
        print(f"Error: Could not read configuration file: {e}")
        return None

def read_mcp3008(spi, channel):
    if not 0 <= channel <= 7:
        raise ValueError("MCP3008 channel must be 0-7")
    try:
        # MCP3008 single-ended read: start bit, config byte, padding
        r = spi.xfer2([1, (8 + channel) << 4, 0])
        return ((r[1] & 3) << 8) + r[2]
    except IOError as e:
        print(f"Error: SPI communication failed on channel {channel}: {e}")
        return None

def convert_to_voltage(adc_value, vref=3.3, load_resistance=10000):
    if adc_value is None:
        return None
    try:
        voltage = (adc_value / 1023.0) * vref
        return voltage * (load_resistance + 10000) / 10000
    except Exception as e:
        print(f"Error: Voltage conversion failed: {e}")
        return None

def log_data(log_file, timestamp, mq2_voltage, mq7_voltage, mq135_voltage):
    try:
        with open(log_file, "a") as f:
            f.write(f"{timestamp},{mq2_voltage:.3f},{mq7_voltage:.3f},{mq135_voltage:.3f}\n")
    except IOError as e:
        print(f"Error: Could not write to log file: {e}")

def check_thresholds(mq2_voltage, mq7_voltage, mq135_voltage, config):
    if mq2_voltage is not None and mq2_voltage > config["mq2_critical"]:
        print("CRITICAL: MQ-2 gas level exceeded critical threshold!")
    if mq2_voltage is not None and mq2_voltage > config["mq2_warning"]:
        print("WARNING: MQ-2 gas level exceeded warning threshold!")
    if mq7_voltage is not None and mq7_voltage > config["mq7_critical"]:
        print("CRITICAL: MQ-7 gas level exceeded critical threshold!")
    if mq7_voltage is not None and mq7_voltage > config["mq7_warning"]:
        print("WARNING: MQ-7 gas level exceeded warning threshold!")
    if mq135_voltage is not None and mq135_voltage > config["mq135_critical"]:
        print("CRITICAL: MQ-135 gas level exceeded critical threshold!")
    if mq135_voltage is not None and mq135_voltage > config["mq135_warning"]:
        print("WARNING: MQ-135 gas level exceeded warning threshold!")

def control_actuator(mq2_voltage, mq7_voltage, mq135_voltage, config):
    try:
        if mq2_voltage is not None and mq2_voltage > config["mq2_critical"]:
            GPIO.output(config["actuator_pin"], GPIO.HIGH)
        else:
            GPIO.output(config["actuator_pin"], GPIO.LOW)
    except Exception as e:
        print(f"Error: Could not control actuator: {e}")

def main():
    config = load_config(CONFIG_FILE)
    if config is None:
        return

    os.makedirs(os.path.dirname(LOG_FILE), exist_ok=True)

    spi = None
    try:
        spi = spidev.SpiDev()
        spi.open(0, 0)
        spi.max_speed_hz = 1000000
        spi.mode = 0

        GPIO.setmode(GPIO.BCM)
        GPIO.setup(config["actuator_pin"], GPIO.OUT, initial=GPIO.LOW)

        mq2_channel = config["mq2_channel"]
        mq7_channel = config["mq7_channel"]
        mq135_channel = config["mq135_channel"]

        while True:
            mq2_adc = read_mcp3008(spi, mq2_channel)
            mq7_adc = read_mcp3008(spi, mq7_channel)
            mq135_adc = read_mcp3008(spi, mq135_channel)

            if mq2_adc is not None and mq7_adc is not None and mq135_adc is not None:
                mq2_voltage = convert_to_voltage(mq2_adc)
                mq7_voltage = convert_to_voltage(mq7_adc)
                mq135_voltage = convert_to_voltage(mq135_adc)

                timestamp = datetime.datetime.now().isoformat()
                log_data(LOG_FILE, timestamp, mq2_voltage, mq7_voltage, mq135_voltage)
                check_thresholds(mq2_voltage, mq7_voltage, mq135_voltage, config)
                control_actuator(mq2_voltage, mq7_voltage, mq135_voltage, config)
            else:
                print("Error: Failed to read one or more sensor channels.")

            time.sleep(5)

    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        if spi is not None:
            try:
                spi.close()
            except Exception:
                pass
        GPIO.output(config["actuator_pin"], GPIO.LOW)
        GPIO.cleanup()
        print("Program finished.")

if __name__ == "__main__":
    main()

