import logging
from contextlib import contextmanager

import numpy as np
from PIL import Image
from picamera2 import Picamera2
from gpiozero import OutputDevice

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
log = logging.getLogger("bird_detector")

_running = True

def _signal_handler(signum, frame):
    global _running
    log.info("Signal %s received, shutting down…", signum)
    _running = False

def load_config(path):
    try:
        with open(path, "r") as f:
            return json.load(f)
    except FileNotFoundError:
        log.warning("Config file %s not found; using defaults.", path)
    except json.JSONDecodeError as e:
        log.error("Config file %s is invalid JSON: %s", path, e)
    return {}

def capture_frame(cam):
    try:
        buf = cam.capture_array()
        if buf is None:
            log.error("capture_array returned None")
            return None
        return buf
    except Exception as e:
        log.error("Error capturing frame: %s", e)
        return None

def detect_bird(frame, model):
    try:
        arr = np.asarray(frame, dtype=np.float32)
        input_data = np.expand_dims(arr, axis=0)
        return model.predict(input_data, verbose=0)[0][0] > 0.5
    except Exception as e:
        log.error("Error during inference: %s", e)
        return False

def indicate_bird(led):
    try:
        led.on()
        time.sleep(1.0)
        led.off()
    except Exception as e:
        log.error("Error controlling LED: %s", e)

def control_door(door, state):
    try:
        if state:
            door.on()
        else:
            door.off()
    except Exception as e:
        log.error("Error controlling door: %s", e)

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    config = load_config("config.json")
    led_pin = config.get("led_pin", 17)
    door_control_pin = config.get("gpio_door_control", None)

    led = None
    door = None
    cam = None

    try:
