import io
import time
import json
import signal
import sys
import threading
import queue
import logging

import numpy as np
import cv2
import RPi.GPIO as GPIO

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class MotionDetector:
    def __init__(self, config_path):
        self.config = self.load_config(config_path)
        self.camera = None
        self.motion_queue = queue.Queue(maxsize=self.config['queue_size'])
        self.running = True
        self.timer = None
        self.gpio_initialized = False

        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.config['gpio_pin'], GPIO.OUT, initial=GPIO.LOW)
            self.gpio_initialized = True
        except Exception as e:
            logging.error(f"Error initializing GPIO: {e}")
            raise

    def load_config(self, config_path):
        try:
            with open(config_path, 'r') as f:
                return json.load(f)
        except FileNotFoundError:
            logging.error(f"Configuration file not found: {config_path}")
            raise
        except json.JSONDecodeError:
            logging.error(f"Invalid JSON format in configuration file: {config_path}")
            raise

    def initialize_camera(self):
        try:
            self.camera = cv2.VideoCapture(0, cv2.CAP_V4L2)
            if not self.camera.isOpened():
                raise RuntimeError("Could not open camera.")

            self.camera.set(cv2.CAP_PROP_FRAME_WIDTH, self.config['resolution'][0])
            self.camera.set(cv2.CAP_PROP_FRAME_HEIGHT, self.config['resolution'][1])
            self.camera.set(cv2.CAP_PROP_FPS, self.config['framerate'])

            time.sleep(2)
            logging.info("Camera initialized successfully.")
        except Exception as e:
            logging.error(f"Error initializing camera: {e}")
            raise

    def capture_frames(self):
        try:
            while self.running:
                ret, frame = self.camera.read()
                if not ret:
                    logging.error("Failed to capture frame.")
                    break

                try:
                    self.motion_queue.put(frame, timeout=1)
                except queue.Full:
                    try:
                        self.motion_queue.get_nowait()
                        self.motion_queue.put(frame)
                    except queue.Empty:
                        logging.warning("Queue unexpectedly empty.")

                time.sleep(0.1)
        except Exception as e:
            logging.error(f"Error capturing frames: {e}")
        finally:
            if self.camera:
                self.camera.release()

    def detect_motion(self):
        try:
            while self.running:
                try:
                    frame = self.motion_queue.get(timeout=1)
                except queue.Empty:
                    continue

                gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
                gray = cv2.GaussianBlur(gray, (21, 21), 0)

                if self.previous_frame is None:
                    self.previous_frame = gray
                    continue

                frame_delta = cv2.absdiff(self.previous_frame, gray)
                thresh = cv2.threshold(frame_delta, 25, 255, cv2.THRESH_BINARY)[1]
                thresh = cv2.dilate(thresh, None, iterations=2)
                contours, _ = cv2.findContours(thresh.copy(), cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)

                for contour in contours:
                    if cv2.contourArea(contour) < self.config['motion_threshold']:
                        continue
                    self.trigger_alert()
                    break

                self.previous_frame = gray
        except Exception as e:
            logging.error(f"Error detecting motion: {e}")

    def trigger_alert(self):
        if self.timer and self.timer.is_alive():
            self.timer.cancel()

        self.timer = threading.Timer(self.config['led_duration'], self.deactivate_led)
        self.timer.daemon = True
        self.timer.start()

        try:
            GPIO.output(self.config['gpio_pin'], GPIO.HIGH)
            logging.info("Motion detected! LED activated.")
        except Exception as e:
            logging.error(f"Error activating LED: {e}")

    def deactivate_led(self):
        try:
            GPIO.output(self.config['gpio_pin'], GPIO.LOW)
            logging.info("LED deactivated.")
        except Exception as e:
            logging.error(f"Error deactivating LED: {e}")

    def cleanup(self):
        self.running = False
        if self.timer and self.timer.is_alive():
            self.timer.cancel()
        if self.camera:
            self.camera.release()
        if self.gpio_initialized:
            GPIO.cleanup()
        logging.info("Resources cleaned up.")

    def run(self):
        try:
            self.initialize_camera()
            capture_thread = threading.Thread(target=self.capture_frames, daemon=True)
            motion_thread = threading.Thread(target=self.detect_motion, daemon=True)

            capture_thread.start()
            motion_thread.start()

            while self.running:
                time.sleep(0.1)

        except Exception as e:
            logging.error(f"An unexpected error occurred: {e}")
        finally:
            self.cleanup()

def signal_handler(sig, frame):
    logging.info("Program interrupted by signal.")
    sys.exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        detector = MotionDetector('config.json')
        detector.run()
    except Exception as e:
        logging.error(f"Failed to start motion detector: {e}")
        sys.exit(1)

