import time
import logging
import configparser
import random
import signal
import sys
from typing import Optional, Tuple

try:
    from gpiozero import Servo, OutputDevice
except ImportError:
    print("Error: gpiozero is not installed. Install with: pip install gpiozero")
    sys.exit(1)

try:
    import greenhouse_vent_control as api
except ImportError:
    print("Error: greenhouse_vent_control library not found.")
    sys.exit(1)

CONFIG_FILE = 'config.ini'
LOG_FILE = 'hydroponics.log'

DEFAULT_CONFIG = {
    'CALIBRATION': {
        'min_angle': '0',
        'max_angle': '90',
        'min_pot_value': '0.1',
        'max_pot_value': '0.9'
    }
}

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def load_config(config_file: str) -> configparser.ConfigParser:
    config = configparser.ConfigParser()
    if not config.read(config_file):
        print(f"Warning: Config file '{config_file}' not found. Creating with defaults.")
        config.read_dict(DEFAULT_CONFIG)
        try:
            with open(config_file, 'w') as f:
                config.write(f)
        except OSError as e:
            print(f"Warning: Could not write default config file: {e}")
    return config


def get_calibration_values(config: configparser.ConfigParser) -> Tuple[float, float, float, float]:
    try:
        return (
            float(config['CALIBRATION']['min_angle']),
            float(config['CALIBRATION']['max_angle']),
            float(config['CALIBRATION']['min_pot_value']),
            float(config['CALIBRATION']['max_pot_value'])
        )
    except (KeyError, ValueError) as e:
        print(f"Error: Invalid calibration values in config: {e}")
        sys.exit(1)


def get_simulated_sensor_data() -> Tuple[float, int]:
    temperature = random.uniform(20, 30)
    greenness = random.randint(0, 100)
    return temperature, greenness


def map_to_angle(pot_value: float, min_angle: float, max_angle: float, min_pot: float, max_pot: float) -> float:
    if max_pot == min_pot:
        return (max_angle + min_angle) / 2.0
    return (max_angle - min_angle) * (pot_value - min_pot) / (max_pot - min_pot) + min_angle


def set_servo_angle(servo: Servo, angle: float) -> None:
    try:
        servo.value = (angle / 90.0) * 2 - 1
    except Exception as e:
        logging.error(f"Error setting servo angle: {e}")


def main() -> None:
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    logging.basicConfig(
        filename=LOG_FILE,
        level=logging.INFO,
        format='%(asctime)s - %(levelname)s - %(message)s'
    )

    config = load_config(CONFIG_FILE)
    min_angle, max_angle, min_pot, max_pot = get_calibration_values(config)

    try:
        api.initialize()
    except Exception as e:
        logging.error(f"Error initializing greenhouse_vent_control library: {e}")
        print("Error: Could not initialize greenhouse_vent_control library.")
        sys.exit(1)

    servo_pin = 17
    pot_pin = 18

    try:
        servo = Servo(servo_pin, min_pulse_width=1.0/1000, max_pulse_width=2.0/1000, frame_width=20/1000)
        pot = OutputDevice(pot_pin)
    except Exception as e:
        logging.error(f"Error initializing GPIO devices: {e}")
        print("Error: Could not initialize GPIO devices.")
        try:
            api.close()
        except Exception:
            pass
        sys.exit(1)

    initial_angle = 0.0
    set_servo_angle(servo, initial_angle)

    try:
        while _running:
            temperature, greenness = get_simulated_sensor_data()
            try:
                api.set_temperature(temperature)
                api.set_greenness(greenness)
            except Exception as e:
                logging.error(f"Error setting sensor data in API: {e}")

            try:
                pot_value = pot.value
            except Exception as e:
                logging.error(f"Error reading potentiometer: {e}")
                pot_value = 0.5

            angle = map_to_angle(pot_value, min_angle, max_angle, min_pot, max_pot)
            set_servo_angle(servo, angle)

            try:
                api.set_vent_angle(angle)
            except Exception as e:
                logging.error(f"Error setting vent angle in API: {e}")

            logging.info(f"Temperature: {temperature:.2f}°C, Greenness: {greenness}, Vent Angle: {angle:.2f}°")

            for _ in range(5):
                if not _running:
                    break
                time.sleep(1)
    finally:
        try:
            servo.close()
        except Exception:
            pass
        try:
            pot.close()
        except Exception:
            pass
        try:
            api.close()
        except Exception:
            pass
        logging.info("Program terminated gracefully.")


if __name__ == "__main__":
    main()

