import time
import signal
import random
import sys
import board
import busio
import adafruit_amg88xx
from gpiozero import Buzzer

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
THERMAL_THRESHOLD = 30.0   # °C
POLL_INTERVAL = 0.1        # seconds
BUZZER_PIN = 17            # BCM GPIO17
BUZZER_DURATION = 1.0      # seconds

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_running = True
_i2c = None
_buzzer = None


def _signal_handler(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False


def _cleanup():
    """Release hardware resources."""
    global _buzzer, _i2c
    if _buzzer is not None:
        try:
            _buzzer.close()
        except Exception:
            pass
        _buzzer = None
    if _i2c is not None:
        try:
            _i2c.deinit()
        except Exception:
            pass
        _i2c = None


def _init_buzzer():
    """Initialise the buzzer; return None on failure."""
    try:
        return Buzzer(BUZZER_PIN)
    except Exception as exc:
        print(f"[ERROR] Failed to initialise buzzer on GPIO{BUZZER_PIN}: {exc}",
              file=sys.stderr)
        return None


def _init_sensor():
    """Initialise the AMG8833 on the default I2C bus; return None on failure."""
    global _i2c
    try:
        _i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        print(f"[ERROR] I2C bus initialisation failed: {exc}", file=sys.stderr)
        _i2c = None
        return None

    try:
        sensor = adafruit_amg88xx.AMG88XX(_i2c)
        # Allow the sensor to stabilise after power-up / reset
        time.sleep(0.1)
        return sensor
    except Exception as exc:
        print(f"[ERROR] AMG8833 not detected on I2C bus: {exc}", file=sys.stderr)
        _i2c = None
        return None


def _read_thermal_data(sensor):
    """Read 8×8 temperature matrix; return None on error."""
    try:
        return sensor.pixels
    except Exception as exc:
        print(f"[ERROR] Failed to read thermal data: {exc}", file=sys.stderr)
        return None


def _simulate_thermal_data():
    """Return an 8×8 matrix of simulated temperatures in °C."""
    return [[random.uniform(20.0, 45.0) for _ in range(8)] for _ in range(8)]


def detect_human(thermal_data):
    """Return True if any pixel exceeds THERMAL_THRESHOLD."""
    if thermal_data is None:
        return False
    for row in thermal_data:
        for temp in row:
            if temp > THERMAL_THRESHOLD:
                return True
    return False


def trigger_alert(buzzer):
    """Sound the buzzer for BUZZER_DURATION seconds."""
    if buzzer is None:
        return
    try:
        buzzer.on()
        time.sleep(BUZZER_DURATION)
        buzzer.off()
    except Exception as exc:
        print(f"[ERROR] Buzzer alert failed: {exc}", file=sys.stderr)


def main():
    global _buzzer

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    _buzzer = _init_buzzer()
    sensor = _init_sensor()

    try:
        while _running:
            thermal_data = None

            if sensor is not None:
                thermal_data = _read_thermal_data(sensor)
                if thermal_data is None:
                    print("[WARN] Sensor read failed; using simulated data.",
                          file=sys.stderr)
                    thermal_data = _simulate_thermal_data()

            human_detected = detect_human(thermal_data)

            if human_detected:
                print("Human detected!")
                trigger_alert(_buzzer)
            else:
                print("No human detected.")

            time.sleep(POLL_INTERVAL)

    except Exception as exc:
        print(f"[ERROR] Unexpected exception: {exc}", file=sys.stderr)
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

