import smbus2
import time
import signal
import sys
import RPi.GPIO as GPIO

I2C_BUS = 1
PCF8574_ADDR = 0x38
INT_PIN = 17
DEBOUNCE_S = 0.05
LOOP_S = 1.0

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def _read_with_debounce(bus):
    time.sleep(DEBOUNCE_S)
    return bus.read_byte(PCF8574_ADDR)

def _on_falling(channel):
    global _running
    if not _running:
        return
    try:
        data = _read_with_debounce(bus)
    except OSError:
        return
    for i in range(8):
        if (data & (1 << i)) == 0:
            print(f"Obstacle detected by sensor {i}")

def main():
    global bus
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    GPIO.setup(INT_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)

    try:
        bus = smbus2.SMBus(I2C_BUS)
    except OSError as e:
        print(f"Failed to open I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        GPIO.cleanup()
        sys.exit(1)

    try:
        GPIO.add_event_detect(INT_PIN, GPIO.FALLING, callback=_on_falling, bouncetime=int(DEBOUNCE_S * 1000))
    except Exception as e:
        print(f"Failed to register interrupt on GPIO{INT_PIN}: {e}", file=sys.stderr)
        bus.close()
        GPIO.cleanup()
        sys.exit(1)

    try:
        while _running:
            time.sleep(LOOP_S)
    except Exception as e:
        print(f"Runtime error: {e}", file=sys.stderr)
    finally:
        try:
            GPIO.remove_event_detect(INT_PIN)
        except Exception:
            pass
        GPIO.cleanup()
        if 'bus' in globals():
            try:
                bus.close()
            except Exception:
                pass

if __name__ == "__main__":
    main()

