import cv2
import numpy as np
import time
import signal
import sys
import logging

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class DualCSICameraApp:
    def __init__(self, camera_num1=0, camera_num2=1, width=640, height=480,
                 framerate=30, display_window_name="Dual CSI Cameras"):
        self.camera_num1 = camera_num1
        self.camera_num2 = camera_num2
        self.width = width
        self.height = height
        self.framerate = framerate
        self.display_window_name = display_window_name
        self.running = True
        self.camera1 = None
        self.camera2 = None

    def initialize_cameras(self):
        try:
            self.camera1 = cv2.VideoCapture(self.camera_num1, cv2.CAP_CSI)
            if not self.camera1.isOpened():
                raise IOError(f"Cannot open camera {self.camera_num1}")
            self.camera1.set(cv2.CAP_PROP_FRAME_WIDTH, self.width)
            self.camera1.set(cv2.CAP_PROP_FRAME_HEIGHT, self.height)
            self.camera1.set(cv2.CAP_PROP_FORMAT, cv2.CV_8UC3)
            self.camera1.set(cv2.CAP_PROP_FPS, self.framerate)
            self.camera1.set(cv2.CAP_PROP_BUFFERSIZE, 1)

            self.camera2 = cv2.VideoCapture(self.camera_num2, cv2.CAP_CSI)
            if not self.camera2.isOpened():
                raise IOError(f"Cannot open camera {self.camera_num2}")
            self.camera2.set(cv2.CAP_PROP_FRAME_WIDTH, self.width)
            self.camera2.set(cv2.CAP_PROP_FRAME_HEIGHT, self.height)
            self.camera2.set(cv2.CAP_PROP_FORMAT, cv2.CV_8UC3)
            self.camera2.set(cv2.CAP_PROP_FPS, self.framerate)
            self.camera2.set(cv2.CAP_PROP_BUFFERSIZE, 1)

            logging.info("Cameras initialized successfully.")
        except Exception as e:
            logging.error(f"Error initializing cameras: {e}")
            self.stop_cameras()
            raise

    def read_frames(self):
        ret1, frame1 = self.camera1.read()
        ret2, frame2 = self.camera2.read()
        if not ret1 or frame1 is None:
            logging.warning("Failed to grab frame from camera 1.")
        if not ret2 or frame2 is None:
            logging.warning("Failed to grab frame from camera 2.")
        return frame1, frame2

    def display_frames(self, frame1, frame2):
        try:
            if frame1 is not None and frame2 is not None:
                combined_frame = np.hstack((frame1, frame2))
                cv2.imshow(self.display_window_name, combined_frame)
            else:
                logging.warning("One or both frames are None. Skipping display.")
        except cv2.error as e:
            logging.error(f"OpenCV error displaying frames: {e}")

    def stop_cameras(self):
        for cam, name in [(self.camera1, 'camera1'), (self.camera2, 'camera2')]:
            if cam is not None:
                try:
                    cam.release()
                except Exception as e:
                    logging.error(f"Error releasing {name}: {e}")
        try:
            cv2.destroyAllWindows()
        except Exception as e:
            logging.error(f"Error destroying windows: {e}")

    def signal_handler(self, signum, frame):
        logging.info(f"Signal {signum} received. Initiating graceful shutdown.")
        self.running = False

    def run(self):
        signal.signal(signal.SIGINT, self.signal_handler)
        signal.signal(signal.SIGTERM, self.signal_handler)

        try:
            self.initialize_cameras()
            cv2.startWindowThread()

            while self.running:
                start_time = time.time()

                frame1, frame2 = self.read_frames()
                self.display_frames(frame1, frame2)

                key = cv2.waitKey(1) & 0xFF
                if key == 27:
                    logging.info("ESC key pressed. Exiting.")
                    break

                try:
                    cv2.getWindowProperty(self.display_window_name, cv2.WND_PROP_AUTOSIZE)
                except cv2.error:
                    logging.info("Display window closed. Exiting.")
                    break

                elapsed = time.time() - start_time
                sleep_time = (1.0 / self.framerate) - elapsed
                if sleep_time > 0:
                    time.sleep(sleep_time)

        except KeyboardInterrupt:
            logging.info("KeyboardInterrupt received. Exiting.")
        except Exception as e:
            logging.error(f"An unexpected error occurred: {e}")
        finally:
            self.stop_cameras()

if __name__ == "__main__":
    app = DualCSICameraApp()
    app.run()

