import os
import sys
import signal
import time
import numpy as np
import tensorflow as tf
from PIL import Image

try:
    from picamera2 import Picamera2
except ImportError:
    print("Error: picamera2 library is not installed. Install with: pip install picamera2", file=sys.stderr)
    sys.exit(1)

try:
    from gc import collect
except ImportError:
    pass

MODEL_FILE = 'resnet_v2_50_data/resnet_v2_50_weights_tf_dim_ordering_tf_kernels.h5'
LABELS_FILE = 'resnet_v2_50_data/imagenet_synset_to_human_label_map.txt'
IMAGE_DIR = 'images'
CAPTURE_WIDTH = 64
CAPTURE_HEIGHT = 64

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def load_model(model_path, labels_path):
    try:
        model = tf.keras.applications.ResNet50_v2(weights='imagenet')
        model.trainable = False
    except Exception as e:
        print(f"Error loading ResNet50_v2 model: {e}", file=sys.stderr)
        return None

    try:
        with open(labels_path, 'r') as f:
            labels = [line.strip() for line in f if line.strip()]
    except OSError as e:
        print(f"Error reading labels file '{labels_path}': {e}", file=sys.stderr)
        return None
    except Exception as e:
        print(f"Error loading labels: {e}", file=sys.stderr)
        return None

    if not labels:
        print("Error: labels file is empty.", file=sys.stderr)
        return None

    return model, labels

def capture_image(picam2, width, height):
    try:
        picam2.configure(picam2.create_still_configuration(main={"size": (width, height)}))
        picam2.start()
        time.sleep(0.5)
        frame = picam2.capture_array()
        picam2.stop()
        return frame
    except Exception as e:
        print(f"Error capturing image: {e}", file=sys.stderr)
        try:
            picam2.stop()
        except Exception:
            pass
        return None

def save_image(frame, image_dir):
    try:
        os.makedirs(image_dir, exist_ok=True)
    except OSError as e:
        print(f"Error creating directory '{image_dir}': {e}", file=sys.stderr)
        return None

    timestamp = time.strftime("%Y%m%d%H%M%S", time.gmtime())
    image_name = os.path.join(image_dir, f"capture_{timestamp}.jpg")
    try:
        img = Image.fromarray(frame)
        img.save(image_name, "JPEG")
        return image_name
    except Exception as e:
        print(f"Error saving image '{image_name}': {e}", file=sys.stderr)
        return None

def predict(model, labels, image_path, top_n=5):
    try:
        img = Image.open(image_path)
        img = img.resize((224, 224))
