        results = []
        for i in order:
            results.append((float(preds[0, i]), labels[i]))
        return results
    except Exception as e:
        print(f"Error during prediction: {e}", file=sys.stderr)
        return None

def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

