from email import encoders

from flask import Flask, render_template, Response, request, jsonify

try:
    from camera import Camera
except ImportError:
    print("Error: camera module not found. Ensure it is in the same directory or installed.")
    exit(1)

try:
    from mail_config import MAIL_SERVER, MAIL_PORT, FROM_ADDR, SEND_MAIL_ALERTS
except ImportError:
    print("Warning: mail_config.py not found. Email alerts will be disabled.")
    SEND_MAIL_ALERTS = False

try:
    from general import send_email
except ImportError:
    print("Warning: send_email function not found. Email alerts will be disabled.")
    SEND_MAIL_ALERTS = False

try:
    from specific import get_object as specific_get_object
except ImportError:
    specific_get_object = None

try:
    from motion_detector import get_object as motion_get_object
except ImportError:
    motion_get_object = None


app = Flask(__name__)

output_frame = None
frame_lock = threading.Lock()
prev_frame = None
last_epoch = 0

shutdown_event = threading.Event()


def signal_handler(signum, frame):
    print(f"\nReceived signal {signum}, shutting down...")
    shutdown_event.set()


signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)


def initialize_camera():
    try:
        camera = Camera(flip=False, src=0)
        print("Camera initialized successfully.")
        return camera
    except Exception as e:
        print(f"Error initializing camera: {e}")
        return None


def detect_object(camera, classifier_name):
    global prev_frame
    try:
        if classifier_name == 'motion_detector':
            if motion_get_object:
                frame, detected = motion_get_object(prev_frame)
            else:
                print("Error: motion_detector not available.")
                return None, False
        else:
            if specific_get_object:
                frame, detected = specific_get_object(classifier_name)
            else:
                print(f"Error: classifier '{classifier_name}' not available.")
                return None, False

        if frame is None:
            return None, False

        if classifier_name == 'motion_detector':
            prev_frame = frame

        return frame, detected
    except Exception as e:
        print(f"Error in object detection: {e}")
        return None, False


def check_for_objects(camera, classifier_name, interval, recipient, camera_id=0):
    global last_epoch
    while not shutdown_event.is_set():
        try:
            frame, detected = detect_object(camera, classifier_name)
            if frame is not None:
                with frame_lock:
                    output_frame = frame.copy()

                if detected and SEND_MAIL_ALERTS:
                    try:
                        elapsed = time.time() - last_epoch
                        if elapsed > interval * 60:
                            print("Sending email...")
                            send_email(frame, recipient, camera_id=camera_id)
                            last_epoch = time.time()
                        else:
                            print("Email alert interval not elapsed.")
                    except Exception as e:
                        print(f"Error sending email: {e}")
        except Exception as e:
            print(f"Error in object checking: {e}")

        shutdown_event.wait(5.0)


def generate():
    global output_frame, shutdown_event
    while not shutdown_event.is_set():
        with frame_lock:
            if output_frame is None:
                continue
            try:
                (flag, encoded_image) = output_frame.encode(format="jpeg")
                if not flag:
                    continue
            except Exception as e:
                print(f"Error encoding frame: {e}")
                continue

        yield (b'--frame\r\n'
               b'Content-Type: image/jpeg\r\n\r\n' +
               bytearray(encoded_image) + b'\r\n')


