    camera = initialize_camera()
    if camera is None:
        print("Failed to initialize camera. Exiting.")
        exit(1)

    atexit.register(camera.stop)

    try:
        classifier_name = request.form.get('classifier', 'motion_detector')
        use_mobile = bool(request.form.get('useMobile', False))
        send_email_flag = bool(request.form.get('sendEmailNotifications', False))
        recipient_email = request.form.get('recipientEmail', '')
        interval = request.form.get('emailInterval', 60, type=int)
    except Exception:
        classifier_name = 'motion_detector'
        use_mobile = False
        send_email_flag = False
        recipient_email = ''
        interval = 60

    if send_email_flag and SEND_MAIL_ALERTS:
        print("Starting object detection...")
        object_detection_thread = threading.Thread(
            target=check_for_objects,
            args=(camera, classifier_name, interval, recipient_email, 0),
            daemon=True
        )
        object_detection_thread.start()

        try:
            app.run(host='0.0.0.0', debug=False, threaded=True)
        except Exception as e:
            print(f"Error running app: {e}")
    else:
        print("Email alerts disabled or send_email function not available.")
        try:
            app.run(host='0.0.0.0', debug=False, threaded=True)
        except Exception as e:
            print(f"Error running app: {e}")

