import cv2
import numpy as np
import serial
import serial.tools.list_ports
import signal
import sys

running = True

def signal_handler(signum, frame):
    global running
    running = False

def send_serial(ser, data):
    if ser is None:
        return
    try:
        ser.write(data.encode('utf-8'))
        ser.flush()
    except serial.SerialException as e:
        print(f"Serial write error: {e}", file=sys.stderr)

def main():
    global running

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    cap = None
    ser = None

    try:
        cap = cv2.VideoCapture(0)
        if not cap.isOpened():
            print("Error: Could not open camera at index 0.", file=sys.stderr)
            return

        print("Camera opened successfully.")

        available_ports = [p.device for p in serial.tools.list_ports.comports()]
        preferred_port = '/dev/ttyACM0'
        if preferred_port in available_ports:
            try:
                ser = serial.Serial(preferred_port, 9600, timeout=1)
                print(f"Connected to Arduino on {preferred_port}")
            except serial.SerialException as e:
                print(f"Warning: Could not connect to Arduino on {preferred_port}: {e}", file=sys.stderr)
                ser = None
        else:
            if available_ports:
                fallback = available_ports[0]
                print(f"Warning: {preferred_port} not found; using {fallback} instead.", file=sys.stderr)
                try:
                    ser = serial.Serial(fallback, 9600, timeout=1)
                    print(f"Connected to Arduino on {fallback}")
                except serial.SerialException as e:
                    print(f"Warning: Could not connect to Arduino on {fallback}: {e}", file=sys.stderr)
                    ser = None
            else:
                print("Warning: No serial ports found.", file=sys.stderr)
                ser = None

        min_hsv = np.array([0, 0, 0])
        max_hsv = np.array([179, 255, 255])
        tracking = True

        while running:
            ret, frame = cap.read()
            if not ret or frame is None:
                print("Error: Could not read frame from camera.", file=sys.stderr)
                break

            h_min = int(min_hsv[0])
            h_max = int(max_hsv[0])
            s_min = int(min_hsv[1])
            s_max = int(max_hsv[1])
            v_min = int(min_hsv[2])
            v_max = int(max_hsv[2])

            hsv = cv2.cvtColor(frame, cv2.COLOR_BGR2HSV)
            mask = cv2.inRange(hsv, np.array([h_min, s_min, v_min]), np.array([h_max, s_max, v_max]))

            contours, _ = cv2.findContours(mask, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)

            for contour in contours:
                if cv2.contourArea(contour) > 500:
                    x, y, w, h = cv2.boundingRect(contour)
                    cv2.rectangle(frame, (x, y), (x + w, y + h), (255, 0, 0), 2)

                    ball_x = x + w // 2
                    ball_y = y + h // 2

                    if tracking:
                        if ball_x > 320 and ball_y > 240:
                            position = '1'
                        elif ball_x > 320 and ball_y < 240:
                            position = '2'
                        elif ball_x < 320 and ball_y > 240:
                            position = '3'
                        elif ball_x < 320 and ball_y < 240:
                            position = '4'
                        else:
                            position = '5'

                        print(f"Ball Position: {position}")
                        send_serial(ser, position)

            cv2.imshow("Frame", frame)
            cv2.imshow("Mask", mask)

            k = cv2.waitKey(1) & 0xFF

            if k == ord('s'):
                min_hsv = np.array([h_min, s_min, v_min])
                max_hsv = np.array([h_max, s_max, v_max])
                print(f"Min HSV: {min_hsv}, Max HSV: {max_hsv}")
            elif k == ord('o'):
                tracking = not tracking
                print(f"Tracking: {'ON' if tracking else 'OFF'}")
            elif k == 27:
                running = False

    except Exception as e:
        print(f"An error occurred: {e}", file=sys.stderr)

    finally:
        if cap is not None and cap.isOpened():
            cap.release()
        if ser is not None and ser.is_open:
            try:
                ser.close()
            except serial.SerialException:
                pass
        cv2.destroyAllWindows()

if __name__ == "__main__":
    main()

