import cv2
import face_recognition
import numpy as np
import os
import time
import signal
import sys

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
BUTTON_PIN = 23
DATASET_DIR = "Dataset"
CAMERA_INDEX = 0
WINDOW_TITLE = "Video"
DEBOUNCE_DELAY = 0.2          # seconds
FACE_TOLERANCE = 0.6
NAME_LABEL_COOLDOWN = 5.0     # seconds

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_video_capture = None
_running = True


def _signal_handler(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False


def load_encodings(dataset_dir):
    """Load face encodings and names from image files in dataset_dir."""
    known_encodings = []
    known_names = []

    if not os.path.isdir(dataset_dir):
        print(f"[ERROR] Dataset directory '{dataset_dir}' not found.")
        return None, None

    for filename in os.listdir(dataset_dir):
        if not filename.lower().endswith((".jpg", ".jpeg", ".png")):
            continue
        image_path = os.path.join(dataset_dir, filename)
        try:
            image = cv2.imread(image_path)
            if image is None:
                print(f"[WARN] Could not read image: {image_path}")
                continue
            encodings = face_recognition.face_encodings(image)
            if not encodings:
                print(f"[WARN] No face found in: {image_path}")
                continue
            known_encodings.append(encodings[0])
            known_names.append(os.path.splitext(filename)[0])
        except Exception as e:
            print(f"[WARN] Error processing {image_path}: {e}")

    if not known_encodings:
        print("[ERROR] No valid face encodings found in the dataset.")
        return None, None

    return known_encodings, known_names


def recognize_faces(frame, known_encodings, known_names,
                     face_tolerance=FACE_TOLERANCE):
    """Return (locations, names) for faces in the frame."""
    rgb_frame = cv2.cvtColor(frame, cv2.COLOR_BGR2RGB)
    face_locations = face_recognition.face_locations(rgb_frame)
    face_encodings = face_recognition.face_encodings(
        rgb_frame, face_locations)

    results = []
    for face_encoding in face_encodings:
        matches = face_recognition.compare_faces(
            known_encodings, face_encoding, tolerance=face_tolerance)
        name = "Unknown"

        if True in matches:
            matched_idxs = [i for i, m in enumerate(matches) if m]
            counts = {}
            for i in matched_idxs:
                n = known_names[i]
                counts[n] = counts.get(n, 0) + 1
            name = max(counts, key=counts.get)

        results.append(name)
    return list(zip(face_locations, results))


def _cleanup():
    """Release camera and destroy all OpenCV windows."""
    global _video_capture
    if _video_capture is not None:
        _video_capture.release()
        _video_capture = None
    cv2.destroyAllWindows()


def main():
    global _video_capture, _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # --- Load known faces at startup ---
    known_encodings, known_names = load_encodings(DATASET_DIR)
    if known_encodings is None or known_names is None:
        _cleanup()
        return

    # --- Initialize USB/CSI camera ---
    _video_capture = cv2.VideoCapture(CAMERA_INDEX)
    if not _video_capture.isOpened():
        print("[ERROR] Could not open USB/CSI camera.")
        _cleanup()
        return

    print("[INFO] Camera opened. Press the button (GPIO 23) to start video...")

