import json
import logging
import signal
import statistics
import sys
import time
from pathlib import Path

try:
    import RPi.GPIO as GPIO
except (ImportError, RuntimeError):
    GPIO = None

CONFIG_FILE = "config.json"
DEFAULT_CONFIG = {
    "sensor1": {"trigger": 17, "echo": 18, "offset": 0.0, "max_distance": 200.0},
    "sensor2": {"trigger": 22, "echo": 23, "offset": 0.0, "max_distance": 200.0},
    "sensor3": {"trigger": 24, "echo": 25, "offset": 0.0, "max_distance": 200.0},
    "alert_threshold_low": 10.0,
    "alert_threshold_high": 180.0,
    "alert_repeat_delay": 60,
    "log_file": "water_level.log",
}

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def _load_config(path):
    try:
        with open(path, "r") as f:
            cfg = json.load(f)
    except FileNotFoundError:
        logging.warning("Config file not found; using defaults.")
        return DEFAULT_CONFIG.copy()
    except json.JSONDecodeError as e:
        logging.error(f"Config JSON decode error: {e}; using defaults.")
        return DEFAULT_CONFIG.copy()

    required = ["trigger", "echo", "offset", "max_distance", "alert_threshold_low",
                "alert_threshold_high", "alert_repeat_delay", "log_file"]
    defaults = DEFAULT_CONFIG.copy()
    for name in ("sensor1", "sensor2", "sensor3"):
        defaults[name] = {**defaults[name], **DEFAULT_CONFIG[name]}
    for name in ("sensor1", "sensor2", "sensor3"):
        if name not in cfg:
            logging.warning(f"Missing sensor '{name}'; using defaults.")
            continue
        for key in required:
            if key not in cfg[name]:
                logging.warning(f"Missing '{key}' in '{name}'; using default.")
                cfg[name][key] = defaults[name][key]
    return cfg


def _setup_logging(log_file):
    logging.basicConfig(
        filename=log_file,
        level=logging.INFO,
        format="%(asctime)s - %(levelname)s - %(message)s",
    )
    logging.info("Program started.")


def _read_distance(trigger_pin, echo_pin, offset, max_distance):
    if GPIO is None:
        return None
    try:
        GPIO.output(trigger_pin, False)
        time.sleep(0.00005)
        GPIO.output(trigger_pin, True)
        time.sleep(0.00001)
        GPIO.output(trigger_pin, False)

        deadline = time.time() + 0.05
        while GPIO.input(echo_pin) == 0:
            if time.time() > deadline:
                return None
        pulse_start = time.time()

        deadline = time.time() + 0.05
        while GPIO.input(echo_pin) == 1:
            if time.time() > deadline:
                return None
        pulse_end = time.time()

        pulse_duration = pulse_end - pulse_start
        distance = pulse_duration * 17150.0
        distance = round(distance - offset, 2)
        if distance < 2 or distance > max_distance:
            return None
        return distance
    except Exception as e:
        logging.error(f"Error reading sensor on trigger={trigger_pin}, echo={echo_pin}: {e}")
        return None


def _get_median_distance(config):
    distances = []
    for name in ("sensor1", "sensor2", "sensor3"):
        cfg = config[name]
        dist = _read_distance(cfg["trigger"], cfg["echo"], cfg["offset"], cfg["max_distance"])
        if dist is not None:
            distances.append(dist)
    if not distances:
        logging.warning("No valid sensor readings; using None.")
        return None
    return statistics.median(distances)


def _check_alerts(distance, config):
    low = config["alert_threshold_low"]
    high = config["alert_threshold_high"]
    repeat = config["alert_repeat_delay"]
    now = time.time()
    if distance is not None:
        if distance < low:
            if not hasattr(sys.modules[__name__], "_low_alert_time") or (now - getattr(sys.modules[__name__], "_low_alert_time", 0)) > repeat:
                logging.warning(f"Water level LOW: {distance:.2f} cm")
                setattr(sys.modules[__name__], "_low_alert_time", now)
        elif distance > high:
            if not hasattr(sys.modules[__name__], "_high_alert_time") or (now - getattr(sys.modules[__name__], "_high_alert_time", 0)) > repeat:
                logging.warning(f"Water level HIGH: {distance:.2f} cm")
                setattr(sys.modules[__name__], "_high_alert_time", now)


def _cleanup():
    logging.info("Program finished.")
    if GPIO is not None:
        try:
            GPIO.cleanup()
        except Exception:
            pass


def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    config = _load_config(CONFIG_FILE)
    _setup_logging(config["log_file"])

    if GPIO is None:
        logging.error("RPi.GPIO not available; exiting cleanly.")
        return

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        for name in ("sensor1", "sensor2", "sensor3"):
            cfg = config[name]
            GPIO.setup(cfg["trigger"], GPIO.OUT, initial=GPIO.LOW)
            GPIO.setup(cfg["echo"], GPIO.IN)
    except Exception as e:
        logging.error(f"GPIO setup failed: {e}")
        _cleanup()
        return

    sensor_errors = {name: 0 for name in ("sensor1", "sensor2", "sensor3")}

    try:
        while _running:
            distance = _get_median_distance(config)
            if distance is None:
                for name in ("sensor1", "sensor2", "sensor3"):
                    sensor_errors[name] += 1
                    if sensor_errors[name] >= 5:
                        logging.error(f"Sensor {name} disabled after 5 consecutive errors.")
            else:
                for name in ("sensor1", "sensor2", "sensor3"):
                    sensor_errors[name] = 0
                _check_alerts(distance, config)
            for _ in range(5):
                if not _running:
                    break
                time.sleep(1)
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

