import time
import signal
import sys
import os
import random
import logging
import threading

try:
    import RPi.GPIO as GPIO
except (ImportError, RuntimeError):
    GPIO = None

try:
    import board
    import adafruit_dht
    DHT_AVAILABLE = True
except (ImportError, NotImplementedError):
    DHT_AVAILABLE = False

try:
    from picamera2 import Picamera2
    CAMERA_AVAILABLE = True
except ImportError:
    CAMERA_AVAILABLE = False

try:
    import pyaudio
    AUDIO_AVAILABLE = True
except ImportError:
    AUDIO_AVAILABLE = False

# Constants
DHT_PIN = 4
LIGHT_RELAY_PIN = 17
WAKE_WORD = "Greenhouse"
LISTENING_TIMEOUT = 5
CAMERA_RESOLUTION = (64, 64)

# Logging setup
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# Global state
lights_on = False
camera = None
audio_engine = None
dht_device = None
running = True

# GPIO setup
if GPIO is not None:
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(LIGHT_RELAY_PIN, GPIO.OUT, initial=GPIO.LOW)
else:
    logger.warning("RPi.GPIO not available. Simulating GPIO.")

def simulate_gpio_setup(pin):
    logger.info(f"Simulating GPIO setup for pin {pin}")

def simulate_gpio_output(pin, value):
    logger.info(f"Simulating GPIO output to pin {pin}: {value}")

def simulate_gpio_cleanup(pin):
    logger.info(f"Simulating GPIO cleanup for pin {pin}")

def simulate_gpio_input(pin):
    return random.choice([GPIO.HIGH, GPIO.LOW]) if GPIO else random.choice([1, 0])

def gpio_setup(pin):
    if GPIO is not None:
        GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)
    else:
        simulate_gpio_setup(pin)

def gpio_output(pin, value):
    if GPIO is not None:
        GPIO.output(pin, value)
    else:
        simulate_gpio_output(pin, value)

def gpio_input(pin):
    if GPIO is not None:
        return GPIO.input(pin)
    else:
        return simulate_gpio_input(pin)

def gpio_cleanup(pin):
    if GPIO is not None:
        GPIO.cleanup(pin)
    else:
        simulate_gpio_cleanup(pin)

def init_camera():
    global camera
    if CAMERA_AVAILABLE:
        try:
            camera = Picamera2()
            config = camera.create_still_configuration(main={"size": CAMERA_RESOLUTION})
            camera.configure(config)
            camera.start()
            logger.info("Camera initialized successfully.")
            return True
        except Exception as e:
            logger.error(f"Failed to initialize camera: {e}")
            camera = None
            return False
    else:
        logger.warning("picamera2 not available. Camera functionality disabled.")
        return False

def init_audio():
    global audio_engine
    if AUDIO_AVAILABLE:
        try:
            audio_engine = pyaudio.PyAudio()
            logger.info("Audio engine initialized successfully.")
            return True
        except Exception as e:
            logger.error(f"Failed to initialize audio engine: {e}")
            audio_engine = None
            return False
    else:
        logger.warning("pyaudio not available. Audio functionality disabled.")
        return False

def init_dht():
    global dht_device
    if DHT_AVAILABLE:
        try:
            dht_device = adafruit_dht.DHT11(board.D4)
            logger.info("DHT11 sensor initialized successfully.")
            return True
        except Exception as e:
            logger.error(f"Failed to initialize DHT11 sensor: {e}")
            dht_device = None
            return False
    else:
        logger.warning("Adafruit Blinka not available. DHT11 functionality disabled.")
        return False

def read_temperature():
    if dht_device is not None:
        try:
            temperature = dht_device.temperature
            if temperature is not None:
                return temperature
            else:
                logger.warning("DHT11 returned None temperature.")
        except RuntimeError as e:
            logger.warning(f"DHT11 read error (checksum or no response): {e}")
        except Exception as e:
            logger.error(f"Unexpected error reading DHT11: {e}")
    return None

def simulate_temperature():
    return random.uniform(15, 35)

def take_picture():
    if camera is None:
        logger.warning("Camera not available. Cannot take picture.")
        return None
    try:
        timestamp = int(time.time() * 1000)
        filename = f"greenhouse_{timestamp}.jpg"
        camera.capture(filename)
        logger.info(f"Picture saved as {filename}")
        return filename
    except Exception as e:
        logger.error(f"Error taking picture: {e}")
        return None

def listen_for_wake_word(timeout=LISTENING_TIMEOUT):
    if audio_engine is None:
        logger.warning("Audio engine not available. Skipping wake word detection.")
        return False
    try:
        stream = audio_engine.open(format=pyaudio.paInt16, channels=1, rate=16000, input=True, frames_per_buffer=1024)
        logger.info("Listening for wake word...")
        start_time = time.time()
        while time.time() - start_time < timeout:
            data = stream.read(1024, exception_on_overflow=False)
            if WAKE_WORD.lower() in str(data).lower():
                logger.info("Wake word detected!")
                return True
        logger.info("Wake word not detected within timeout.")
        return False
    except Exception as e:
        logger.error(f"Error during audio listening: {e}")
        return False

def process_command(command):
    global lights_on
    logger.info(f"Processing command: {command}")
    if "turn on the lights" in command.lower():
        gpio_output(LIGHT_RELAY_PIN, GPIO.HIGH) if GPIO else simulate_gpio_output(LIGHT_RELAY_PIN, 1)
        lights_on = True
        logger.info("Lights turned on.")
    elif "turn off the lights" in command.lower():
        gpio_output(LIGHT_RELAY_PIN, GPIO.LOW) if GPIO else simulate_gpio_output(LIGHT_RELAY_PIN, 0)
        lights_on = False
        logger.info("Lights turned off.")
    elif "what is the temperature" in command.lower():
        temperature = read_temperature()
        if temperature is not None:
            logger.info(f"Temperature: {temperature:.1f}°C")
        else:
            temperature = simulate_temperature()
            logger.info(f"Simulated Temperature: {temperature:.1f}°C")
    elif "take a picture" in command.lower():
        take_picture()
    else:
        logger.warning("Unknown command.")

def signal_handler(sig, frame):
    global running
    logger.info("Shutting down gracefully...")
    running = False
    if camera is not None:
        try:
            camera.stop()
            camera.close()
        except Exception as e:
            logger.error(f"Error closing camera: {e}")
    if GPIO is not None:
        GPIO.cleanup()
    sys.exit(0)

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    if not init_camera():
        logger.warning("Camera initialization failed. Continuing without camera.")
    if not init_audio():
        logger.warning("Audio initialization failed. Continuing without audio.")
    if not init_dht():
        logger.warning("DHT11 initialization failed. Continuing without DHT11.")

    try:
        while running:
            if listen_for_wake_word():
                command = input("Enter command: ")
                process_command(command)
    except Exception as e:
        logger.error(f"Unexpected error in main loop: {e}")
    finally:
        if camera is not None:
            try:
                camera.stop()
                camera.close()
            except Exception as e:
                logger.error(f"Error closing camera: {e}")
        if GPIO is not None:
            GPIO.cleanup()
        logger.info("Program terminated.")

if __name__ == "__main__":
    main()

