import time

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("Error: RPi.GPIO requires root privileges or a Raspberry Pi environment.", file=sys.stderr)
    sys.exit(1)
except ImportError:
    print("Error: RPi.GPIO library not found. Install with: pip install RPi.GPIO", file=sys.stderr)
    sys.exit(1)

# BCM pin assignments
INPUT_PINS = [4, 5, 6]
OUTPUT_PINS = [23, 24]
POLL_INTERVAL = 0.05  # seconds

# Global state
output_state = False
running = True


def signal_handler(signum, frame):
    """Handle SIGINT (Ctrl-C) for graceful shutdown."""
    global running
    running = False


def cleanup():
    """Release GPIO resources safely."""
    try:
        GPIO.cleanup()
    except Exception:
        pass


def main():
    global output_state

    # Register signal handler for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)

    # Initialize GPIO
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)

        for pin in INPUT_PINS:
            GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)

        for pin in OUTPUT_PINS:
            GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)

    except Exception as e:
        print(f"Error initializing GPIO: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    print("GPIO initialized. Polling inputs every 0.05 s. Press Ctrl-C to exit.")

    try:
        while running:
            try:
                # Read input pins; GPIO.input returns 0 (LOW) or 1 (HIGH)
                input_4 = GPIO.input(4)
                input_5 = GPIO.input(5)
                input_6 = GPIO.input(6)

                # Determine desired output state
                if input_4 == GPIO.LOW:
                    GPIO.output(23, GPIO.HIGH)
                else:
                    GPIO.output(23, GPIO.LOW)

                if input_5 == GPIO.LOW:
                    GPIO.output(23, GPIO.LOW)

                if input_6 == GPIO.LOW:
                    output_state = not output_state
                    GPIO.output(24, output_state)

            except Exception as e:
                print(f"Warning: GPIO read/write error: {e}", file=sys.stderr)

            time.sleep(POLL_INTERVAL)

    finally:
        cleanup()
        print("GPIO cleaned up. Exiting.")


if __name__ == "__main__":
    main()

