import io
import os
import time
import signal
import logging
import datetime
import threading
import queue
import shutil
import subprocess
import numpy as np
from PIL import Image
from picamera2 import Picamera2
from picamera2.encoders import H264Encoder
from picamera2.outputs import FfmpegOutput

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class MotionDetector:
    def __init__(self, threshold=20, min_vectors=10):
        self.threshold = threshold
        self.min_vectors = min_vectors

    def detect(self, frame1, frame2):
        try:
            gray1 = np.array(frame1.convert('L'), dtype=np.int16)
            gray2 = np.array(frame2.convert('L'), dtype=np.int16)
            diff = np.abs(gray1 - gray2)
            motion_pixels = np.sum(diff > self.threshold)
            return motion_pixels > self.min_vectors, motion_pixels
        except Exception as e:
            logging.error(f"Error in motion detection: {e}")
            return False, 0

class VideoRecorder:
    def __init__(self, output_dir, max_disk_usage_gb=1.0):
        self.output_dir = output_dir
        self.max_disk_usage_bytes = max_disk_usage_gb * 1024 * 1024 * 1024
        self.recording_lock = threading.Lock()
        self.recording_active = False
        self.recording_thread = None
        self.recording_queue = queue.Queue()
        self.stop_event = threading.Event()
        self.encoder = None
        self.camera = None
        self.ffmpeg_process = None
        self.current_output = None
        self.current_filename = None
        self.disk_usage_lock = threading.Lock()
        self._setup_directory()

    def _setup_directory(self):
        try:
            os.makedirs(self.output_dir, exist_ok=True)
            logging.info(f"Output directory ready: {self.output_dir}")
        except OSError as e:
            logging.error(f"Failed to create output directory: {e}")
            raise

    def _get_available_space(self):
        statvfs = os.statvfs(self.output_dir)
        return statvfs.f_frsize * statvfs.f_bavail

    def _delete_oldest_file(self):
        try:
            files = sorted([f for f in os.listdir(self.output_dir) if os.path.isfile(os.path.join(self.output_dir, f))],
                           key=lambda x: os.path.getmtime(os.path.join(self.output_dir, x)))
            if files:
                file_to_delete = os.path.join(self.output_dir, files[0])
                os.remove(file_to_delete)
                logging.info(f"Deleted oldest file: {file_to_delete}")
        except Exception as e:
            logging.error(f"Error deleting oldest file: {e}")

    def _check_disk_space(self):
        with self.disk_usage_lock:
            available_space = self._get_available_space()
            if available_space < self.max_disk_usage_bytes:
                logging.warning(f"Disk space low: {available_space / 1024 / 1024 / 1024:.2f} GB available, limit is {self.max_disk_usage_bytes / 1024 / 1024 / 1024:.2f} GB")
                self._delete_oldest_file()

    def _start_recording(self):
        timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        filename = os.path.join(self.output_dir, f"{timestamp}.h264")
        try:
            self.encoder = H264Encoder(bitrate=10000000)
            self.current_output = FfmpegOutput(filename)
            self.camera.start_recording(self.encoder, self.current_output)
            self.current_filename = filename
            logging.info(f"Started recording: {filename}")
        except Exception as e:
            logging.error(f"Failed to start recording: {e}")
            self.current_output = None
            self.current_filename = None

    def _stop_recording(self):
        if self.current_output:
            try:
                self.camera.stop_recording()
                logging.info("Stopped recording.")
            except Exception as e:
                logging.error(f"Error stopping recording: {e}")
            finally:
                self.current_output = None
                self.current_filename = None

    def _recording_loop(self):
        while not self.stop_event.is_set():
            try:
                item = self.recording_queue.get(timeout=1)
                if item == "start":
                    with self.recording_lock:
                        if not self.recording_active:
                            self._start_recording()
                            self.recording_active = True
                elif item == "stop":
                    with self.recording_lock:
                        if self.recording_active:
                            self._stop_recording()
                            self.recording_active = False
                elif item == "check_disk":
                    self._check_disk_space()
            except queue.Empty:
                continue
            except Exception as e:
                logging.error(f"Error in recording loop: {e}")

    def start_recording_thread(self):
        if not self.recording_thread or not self.recording_thread.is_alive():
            self.stop_event.clear()
            self.recording_thread = threading.Thread(target=self._recording_loop, daemon=True)
            self.recording_thread.start()
            logging.info("Recording thread started.")

    def stop_recording_thread(self):
        self.stop_event.set()
        if self.recording_thread and self.recording_thread.is_alive():
            self.recording_thread.join(timeout=5)
            logging.info("Recording thread stopped.")

    def start_streaming(self, port=8000):
        try:
            self.ffmpeg_process = subprocess.Popen(['ffmpeg', '-f', 'h264', '-i', 'pipe:', '-c', 'copy', '-f', 'mpegts', f'tcp://0.0.0.0:{port}'], stdin=subprocess.PIPE)
            logging.info(f"Streaming started on port {port}")
        except Exception as e:
            logging.error(f"Failed to start streaming: {e}")

    def stop_streaming(self):
        if self.ffmpeg_process and self.ffmpeg_process.poll() is None:
            self.ffmpeg_process.terminate()
            self.ffmpeg_process.wait(timeout=2)
            logging.info("Streaming stopped.")

    def capture_frame(self):
        try:
            return self.camera.capture_array()
        except Exception as e:
            logging.error(f"Error capturing frame: {e}")
            return None

    def initialize_camera(self):
        try:
            self.camera = Picamera2()
            config = self.camera.create_video_configuration(main={"size": (640, 480), "format": "RGB888"}, lores={"size": (320, 240), "format": "YUV420"})
            self.camera.configure(config)
            self.camera.start()
            logging.info("Camera initialized successfully.")
            return True
        except Exception as e:
            logging.error(f"Failed to initialize camera: {e}")
            self.camera = None
            return False

    def close(self):
        self.stop_streaming()
        self.stop_recording_thread()
        if self.camera:
            try:
                self.camera.stop_recording()
                self.camera.close()
                logging.info("Camera closed.")
            except Exception as e:
                logging.error(f"Error closing camera: {e}")
            finally:
                self.camera = None

def main():
    recorder = None
    try:
        recorder = VideoRecorder("recordings", max_disk_usage_gb=1.0)
        if not recorder.initialize_camera():
            return
        recorder.start_recording_thread()
        motion_detector = MotionDetector(threshold=20, min_vectors=10)
        pre_record_seconds = 5
        post_record_seconds = 10
        fps = 15
        frame_interval = 1.0 / fps
        logging.info("Starting motion detection loop...")
        while True:
            frame1 = recorder.capture_frame()
            if frame1 is None:
                time.sleep(frame_interval)
                continue
            time.sleep(frame_interval)
            frame2 = recorder.capture_frame()
            if frame2 is None:
                continue
            motion_detected, motion_pixels = motion_detector.detect(Image.fromarray(frame1), Image.fromarray(frame2))
            if motion_detected:
                logging.info(f"Motion detected: {motion_pixels} pixels")
                recorder.recording_queue.put("start")
                time.sleep(pre_record_seconds)
                recorder.recording_queue.put("check_disk")
                time.sleep(post_record_seconds)
                recorder.recording_queue.put("stop")
            else:
                recorder.recording_queue.put("check_disk")
    except KeyboardInterrupt:
        logging.info("Program interrupted by user.")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        if recorder:
            recorder.close()

if __name__ == "__main__":
    main()

