#!/usr/bin/env python3

import cv2
import pyzbar.pyzbar as pyzbar
import time
import datetime
import logging
import configparser
import os
import threading
import queue
import signal
import sys
import random

# Configuration file path
CONFIG_FILE = 'config.ini'

# Default configuration values
DEFAULT_CONFIG = {
    'DEFAULT': {
        'motion_threshold': '20',
        'frame_buffer_size': '5',
        'redundancy_time_window': '30',
        'cloud_upload_interval': '60',
        'reinit_delay': '5',
        'log_level': 'INFO',
        'watchdog_timeout': '30'
    },
    'CAMERA1': {
        'device_node': '/dev/video0'
    },
    'CAMERA2': {
        'device_node': '/dev/video2'
    }
}

# Global variables
inventory_data = {}
inventory_lock = threading.Lock()
frame_buffers = {}
frame_buffer_locks = {}
redundancy_timestamps = {}
last_uploaded_data = {}
last_uploaded_lock = threading.Lock()
running = True

# Configure logging
logging.basicConfig(
    filename='inventory.log',
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# Signal handler for graceful shutdown
def signal_handler(sig, frame):
    global running
    logging.info("Received signal %s, shutting down gracefully...", sig)
    running = False

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

def load_config(config_file):
    """Loads configuration from the specified file, merging with defaults."""
    config = configparser.ConfigParser()
    config.read_dict(DEFAULT_CONFIG)
    if os.path.exists(config_file):
        config.read(config_file)
    return config

def initialize_camera(device_node):
    """Initializes a USB camera with error handling."""
    try:
        cap = cv2.VideoCapture(device_node)
        if not cap.isOpened():
            raise IOError(f"Cannot open camera at {device_node}")
        return cap
    except Exception as e:
        logging.error(f"Error initializing camera at {device_node}: {e}")
        return None

def read_frame(cap):
    """Reads a frame from the camera with error handling."""
    try:
        ret, frame = cap.read()
        if not ret:
            raise IOError("Failed to read frame from camera")
        return frame
    except Exception as e:
        logging.error(f"Error reading frame: {e}")
        return None

def decode_qr_code(frame):
    """Decodes QR codes from a frame."""
    try:
        decoded_objects = pyzbar.decode(frame)
        return [obj.data.decode("utf-8") for obj in decoded_objects]
    except Exception as e:
        logging.error(f"Error decoding QR code: {e}")
        return []

def process_frame(frame, device_node, motion_threshold, frame_buffer, frame_buffer_lock):
    """Processes a single frame, detecting motion and decoding QR codes."""
    global inventory_data, last_uploaded_data

    with frame_buffer_lock:
        if len(frame_buffer) >= int(motion_threshold):
            del frame_buffer[0]

        frame_buffer.append(frame)

    if not any(cv2.mean(frame) < 10):
        return

    qr_codes = decode_qr_code(frame)
    for qr_code in qr_codes:
        timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        logging.info(f"QR Code detected: {qr_code} by {device_node} at {timestamp}")

        with inventory_lock:
            if qr_code not in inventory_data:
                inventory_data[qr_code] = 1
            else:
                inventory_data[qr_code] += 1

        with last_uploaded_lock:
            if qr_code not in last_uploaded_data or last_uploaded_data[qr_code] != inventory_data[qr_code]:
                logging.info(f"Simulated cloud upload: {qr_code} - Quantity: {inventory_data[qr_code]}")
                last_uploaded_data[qr_code] = inventory_data[qr_code]

def camera_worker(device_node, motion_threshold, frame_buffer_size, redundancy_time_window, reinit_delay):
    """Worker function for camera processing."""
    global running
    cap = None

    while running:
        if cap is None:
            cap = initialize_camera(device_node)
            if cap is None:
                logging.error(f"Failed to initialize camera at {device_node}. Retrying in {reinit_delay} seconds...")
                time.sleep(int(reinit_delay))
                continue

        try:
            frame = read_frame(cap)
            if frame is None:
                logging.error(f"Failed to read frame from {device_node}. Releasing camera and retrying...")
                cap.release()
                cap = None
                time.sleep(int(reinit_delay))
                continue

            process_frame(frame, device_node, motion_threshold, frame_buffers[device_node], frame_buffer_locks[device_node])

        except Exception as e:
            logging.error(f"Error in camera worker for {device_node}: {e}")
            if cap:
                cap.release()
                cap = None
            time.sleep(int(reinit_delay))

    if cap:
        cap.release()

def cloud_upload_worker(cloud_upload_interval):
    """Worker function for simulated cloud upload."""
    global inventory_data, last_uploaded_data, running

    while running:
        try:
            with inventory_lock:
                for item, quantity in inventory_data.items():
                    if item not in last_uploaded_data or last_uploaded_data[item] != quantity:
                        logging.info(f"Simulated cloud upload: {item} - Quantity: {quantity}")
                        last_uploaded_data[item] = quantity

            time.sleep(int(cloud_upload_interval))

        except Exception as e:
            logging.error(f"Error in cloud upload worker: {e}")
            time.sleep(int(cloud_upload_interval))

def watchdog_timer(timeout):
    """Monitors the program for inactivity and restarts if necessary."""
    global running
    last_activity = time.time()

    while running:
        time.sleep(1)
        if time.time() - last_activity > int(timeout):
            logging.warning("Watchdog timeout triggered. Restarting program...")
            os.execv(sys.executable, [sys.executable] + sys.argv)

def main():
    """Main function to initialize and run the program."""
    global running, inventory_data, frame_buffers, frame_buffer_locks, redundancy_timestamps, last_uploaded_data

    config = load_config(CONFIG_FILE)

    motion_threshold = config.getint('DEFAULT', 'motion_threshold')
    frame_buffer_size = config.getint('DEFAULT', 'frame_buffer_size')
    redundancy_time_window = config.getfloat('DEFAULT', 'redundancy_time_window')
    cloud_upload_interval = config.getint('DEFAULT', 'cloud_upload_interval')
    reinit_delay = config.getfloat('DEFAULT', 'reinit_delay')
    watchdog_timeout = config.getint('DEFAULT', 'watchdog_timeout')

    log_level = config.get('DEFAULT', 'log_level')
    if log_level == 'DEBUG':
        logging.getLogger().setLevel(logging.DEBUG)
    elif log_level == 'INFO':
        logging.getLogger().setLevel(logging.INFO)
    elif log_level == 'WARNING':
        logging.getLogger().setLevel(logging.WARNING)
    elif log_level == 'ERROR':
        logging.getLogger().setLevel(logging.ERROR)
    elif log_level == 'CRITICAL':
        logging.getLogger().setLevel(logging.CRITICAL)

    device_nodes = [config.get('CAMERA1', 'device_node'), config.get('CAMERA2', 'device_node')]

    for device_node in device_nodes:
        frame_buffers[device_node] = []
        frame_buffer_locks[device_node] = threading.Lock()
        redundancy_timestamps[device_node] = {}

    threads = []
    for device_node in device_nodes:
        t = threading.Thread(target=camera_worker, args=(device_node, motion_threshold, frame_buffer_size, redundancy_time_window, reinit_delay))
        t.daemon = True
        threads.append(t)
        t.start()

    cloud_thread = threading.Thread(target=cloud_upload_worker, args=(cloud_upload_interval,))
    cloud_thread.daemon = True
    cloud_thread.start()

    watchdog_thread = threading.Thread(target=watchdog_timer, args=(watchdog_timeout,))
    watchdog_thread.daemon = True
    watchdog_thread.start()

    try:
        while running:
            time.sleep(1)
    except KeyboardInterrupt:
        logging.info("KeyboardInterrupt received. Shutting down...")
    finally:
        running = False
        for t in threads:
            t.join(timeout=5)
        if cloud_thread.is_alive():
            cloud_thread.join(timeout=5)
        if watchdog_thread.is_alive():
            watchdog_thread.join(timeout=5)
        logging.info("Program finished.")

if __name__ == "__main__":
    main()

