import os
import sys
import time
import signal
import datetime

try:
    from gpiozero import LED
    from picamera2 import Picamera2
except ImportError as exc:
    print(f"Missing required library: {exc}", file=sys.stderr)
    sys.exit(1)

LED_PIN = 17
IMAGE_DIR = "static/images"
COUNTDOWN_SECONDS = 2
BLINK_ON_TIME = 0.2
BLINK_OFF_TIME = 0.2
BLINK_COUNT = 5

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def setup_hardware():
    led = LED(LED_PIN)
    picam2 = Picamera2()
    try:
        picam2.start()
    except Exception as exc:
        led.close()
        raise RuntimeError(f"Failed to initialize camera: {exc}") from exc
    return led, picam2

def cleanup(led, picam2):
    try:
        led.off()
        led.close()
    except Exception:
        pass
    try:
        picam2.close()
    except Exception:
        pass

def countdown(seconds):
    for i in range(seconds, 0, -1):
        if not _running:
            return False
        print(i)
        time.sleep(1)
    return True

def blink_led(led, count):
    for _ in range(count):
        if not _running:
            return False
        led.on()
        time.sleep(BLINK_ON_TIME)
        led.off()
        time.sleep(BLINK_OFF_TIME)
    return True

def capture_image(led, picam2, image_dir):
    try:
        os.makedirs(image_dir, exist_ok=True)
    except OSError as exc:
        print(f"Error creating directory '{image_dir}': {exc}", file=sys.stderr)
        return False

    if not countdown(COUNTDOWN_SECONDS):
        return False

    if not blink_led(led, BLINK_COUNT):
        return False

    led.on()
    timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
    image_path = os.path.join(image_dir, f"image_{timestamp}.jpg")
    try:
        picam2.capture_file(image_path)
        print(f"Image saved to {image_path}")
        led.off()
        return True
    except Exception as exc:
        print(f"Error capturing image: {exc}", file=sys.stderr)
        led.off()
        return False

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    led = None
    picam2 = None
    try:
        led, picam2 = setup_hardware()
        success = capture_image(led, picam2, IMAGE_DIR)
        if not success and _running:
            print("Error: Image capture failed.", file=sys.stderr)
            blink_led(led, BLINK_COUNT)
            sys.exit(1)
    except RuntimeError as exc:
        print(f"Error: {exc}", file=sys.stderr)
        if led is not None:
            try:
                blink_led(led, BLINK_COUNT)
            except Exception:
                pass
        sys.exit(1)
    except KeyboardInterrupt:
        print("\nInterrupted by user.", file=sys.stderr)
        if led is not None:
            try:
                blink_led(led, BLINK_COUNT)
            except Exception:
                pass
        sys.exit(130)
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
        if led is not None:
            try:
                blink_led(led, BLINK_COUNT)
            except Exception:
                pass
        sys.exit(1)
    finally:
        cleanup(led, picam2)

if __name__ == "__main__":
    main()

