import cv2
import select
import sys
import time
import signal
import os
import logging
import threading
import numpy as np
import config
import face

logging.basicConfig(level=logging.INFO, format='%(asctime)s %(levelname)s %(message)s')
logger = logging.getLogger(__name__)

DOOR_LOCK_PIN = 17
BUTTON_PIN = 5

_running = True

def _signal_handler(signum, frame):
    global _running
    logger.info('Signal %s received, shutting down...', signum)
    _running = False

def init_gpio():
    import RPi.GPIO as GPIO
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    GPIO.setup(DOOR_LOCK_PIN, GPIO.OUT, initial=GPIO.HIGH)
    GPIO.setup(BUTTON_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)

def cleanup_gpio():
    try:
        import RPi.GPIO as GPIO
        GPIO.cleanup()
    except Exception:
        pass

def init_audio():
    import pyaudio
    p = pyaudio.PyAudio()
    stream = p.open(format=p.get_format_from_width(2),
                    channels=1,
                    rate=48000,
                    output=True,
                    frames_per_buffer=1024)
    return p, stream

def play_audio_file(stream, filename, channel=0):
    try:
        data = np.fromfile(filename, dtype=np.int16)
        if data.size == 0:
            logger.warning('Audio file %s is empty', filename)
            return
        stream.write(data.tobytes(), channel=channel)
    except FileNotFoundError:
        logger.error('Audio file not found: %s', filename)
    except Exception as e:
        logger.error('Error playing audio %s: %s', filename, e)

def release_resources(camera=None, p=None, stream=None):
    if camera is not None:
        try:
            camera.release()
        except Exception:
            pass
    if stream is not None:
        try:
            stream.stop_stream()
            stream.close()
        except Exception:
            pass
    if p is not None:
        try:
            p.terminate()
        except Exception:
            pass
    cleanup_gpio()

def is_letter_input(letter):
    if select.select([sys.stdin], [], [], 0.0)[0]:
        input_char = sys.stdin.read(1)
        return input_char.lower() == letter.lower()
    return False

def load_model():
    if not os.path.exists(config.TRAINING_FILE):
        logger.error('Model file not found: %s', config.TRAINING_FILE)
        return None
    try:
        model = cv2.face.EigenFaceRecognizer_create()
        model.read(config.TRAINING_FILE)
        logger.info('Model loaded from %s', config.TRAINING_FILE)
        return model
    except Exception as e:
        logger.error('Error loading model: %s', e)
        return None

def detect_single(gray):
    cascade_path = cv2.data.haarcascades + 'haarcascade_frontalface_default.xml'
    cascade = cv2.CascadeClassifier(cascade_path)
    if cascade.empty():
        logger.error('Failed to load Haar cascade')
        return None
    faces = cascade.detectMultiScale(gray, 1.3, 5)
    if len(faces) == 1:
        return faces[0]
    return None

def crop(gray, x, y, w, h):
    h_orig, w_orig = gray.shape
    start_x = max(0, int(x - 0.15 * w))
    start_y = max(0, int(y - 0.25 * h))
    end_x = min(w_orig, int(x + 1.15 * w))
    end_y = min(h_orig, int(y + 1.25 * h))
    return gray[start_y:end_y, start_x:end_x]

def resize(gray, size=(100, 100)):
    return cv2.resize(gray, size)

def recognize(model, gray):
    label, confidence = model.predict(gray)
    logger.info('Predicted %s face with confidence %.2f',
                'POSITIVE' if label == config.POSITIVE_LABEL else 'NEGATIVE', confidence)
    return label == config.POSITIVE_LABEL, confidence

def unlock_door():
    try:
        import RPi.GPIO as GPIO
        GPIO.output(DOOR_LOCK_PIN, GPIO.LOW)
        logger.info('Door unlocked')
    except Exception as e:
        logger.error('Failed to unlock door: %s', e)

def lock_door():
    try:
        import RPi.GPIO as GPIO
        GPIO.output(DOOR_LOCK_PIN, GPIO.HIGH)
        logger.info('Door locked')
    except Exception as e:
        logger.error('Failed to lock door: %s', e)

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    init_gpio()
    p, stream = init_audio()
    model = load_model()
    if model is None:
        release_resources(None, p, stream)
        return

    camera = None
    try:
        camera = config.get_camera()
        if camera is None:
            logger.error('Failed to initialize camera')
            return

        while _running:
            try:
                if config.HARDWARE_BUTTON_ENABLED:
                    if GPIO.input(BUTTON_PIN) == GPIO.LOW:
                        logger.info('Button pressed, looking for face...')
                        time.sleep(0.3)
                        if GPIO.input(BUTTON_PIN) == GPIO.LOW:
                            break
                time.sleep(0.1)
                continue

                if is_letter_input('l'):
                    lock_door()
                    play_audio_file(stream, config.LOCK_SOUND_PATH, 0)
                    time.sleep(0.5)
                    continue

                ret, frame = camera.read()
                if not ret or frame is None:
                    logger.warning('Failed to capture image from camera')
                    time.sleep(0.1)
                    continue

                gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
                result = detect_single(gray)
                if result is None:
                    logger.info('No single face detected')
                    play_audio_file(stream, config.WAIT_SOUND_PATH, 1)
                    time.sleep(0.5)
                    continue

                x, y, w, h = result
                cropped = crop(gray, x, y, w, h)
                resized = resize(cropped)
                matched, confidence = recognize(model, resized)

                if matched and (config.POSITIVE_THRESHOLD <= 0 or confidence < config.POSITIVE_THRESHOLD):
                    unlock_door()
                    play_audio_file(stream, config.WELCOME_SOUND_PATH, 0)
                else:
                    play_audio_file(stream, config.NOT_RECOGNIZED_SOUND_PATH, 2)
                    play_audio_file(stream, config.WAIT_SOUND_PATH, 1)

            except Exception as e:
                logger.error('Error during processing: %s', e)
                time.sleep(0.1)

    except Exception as e:
        logger.error('Fatal error: %s', e)
    finally:
        release_resources(camera, p, stream)
        logger.info('Resources released, exiting.')

if __name__ == '__main__':
    main()

