import signal
import sys
import time
import math
import numpy as np
import pyaudio
from gpiozero import Button

BUTTON_PIN = 5
SAMPLE_RATE = 44100
BLOCK_SIZE = 1024
BOUNCE_TIME = 0.2

running = True
button = None
p = None


def cleanup(signum=None, frame=None):
    global running, button, p
    running = False
    if p is not None:
        try:
            p.stop_stream()
        except Exception:
            pass
        try:
            p.close()
        except Exception:
            pass
    if button is not None:
        try:
            button.close()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)


def process_block(in_data, frame_count, time_info, status):
    if status:
        print(f"Stream status: {status}", file=sys.stderr)
    try:
        in_data = np.frombuffer(in_data, dtype=np.float32).reshape(-1, 1)
    except Exception as e:
        print(f"Buffer conversion error: {e}", file=sys.stderr)
        return None, pyaudio.paContinue

    if button.is_active:
        gain = 2.0
    else:
        gain = 1.0

    try:
        out_data = np.tanh(in_data * gain)
    except Exception as e:
        print(f"Processing error: {e}", file=sys.stderr)
        out_data = in_data

    return out_data.tobytes(), pyaudio.paContinue


def main():
    global button, p

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        button = Button(BUTTON_PIN, pull_up=True, bounce_time=BOUNCE_TIME, active_state=False)
    except Exception as e:
        print(f"Failed to initialize GPIO button on pin {BUTTON_PIN}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        p = pyaudio.PyAudio()
    except Exception as e:
        print(f"Failed to initialize PyAudio: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    try:
        stream = p.open(
            format=pyaudio.paFloat32,
            channels=1,
            rate=SAMPLE_RATE,
            input=True,
            output=True,
            frames_per_buffer=BLOCK_SIZE,
            stream_callback=process_block,
        )
    except Exception as e:
        print(f"Failed to open audio stream: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    print("Listening for button press on GPIO5 (active-low). Press Ctrl+C to exit.")

    try:
        while running:
            time.sleep(0.1)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

