import asyncio
import signal
import threading
import logging
import numpy as np
import cv2

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class WebSocketHandler:
    """Thread-safe WebSocket broadcast dispatcher."""

    def __init__(self):
        self._connections = []
        self._lock = threading.Lock()

    def connect(self, ws):
        with self._lock:
            if ws not in self._connections:
                self._connections.append(ws)
                logger.info(f"WebSocket client connected (total: {len(self._connections)})")

    def disconnect(self, ws):
        with self._lock:
            if ws in self._connections:
                self._connections.remove(ws)
                logger.info(f"WebSocket client disconnected (total: {len(self._connections)})")

    def has_connections(self):
        with self._lock:
            return bool(self._connections)

    def broadcast(self, data):
        if not isinstance(data, (bytes, bytearray)):
            logger.error("broadcast data must be bytes or bytearray")
            return
        with self._lock:
            connections = list(self._connections)
        for conn in connections:
            try:
                conn.send(data)
            except Exception as e:
                logger.error(f"Error broadcasting to client: {e}")


class CameraFeed:
    """Background camera feed with motion detection and thread-safe buffer access."""

    def __init__(self, camera_id=0, width=64, height=48, fps=10, detect_motion_function=None):
        if not callable(detect_motion_function):
            raise ValueError("detect_motion_function must be callable")
        self.camera_id = camera_id
        self.width = width
        self.height = height
        self.fps = fps
        self.detect_motion_function = detect_motion_function
        self.camera = None
        self.frame = None
        self.lock = threading.Lock()
        self.running = False
        self.loop = None
        self._stop_event = threading.Event()

    def _initialize_camera(self):
        """Initialize the camera with the requested resolution and framerate."""
        try:
            self.camera = cv2.VideoCapture(self.camera_id, cv2.CAP_V4L2)
            if not self.camera.isOpened():
                raise RuntimeError(f"Could not open camera {self.camera_id}")

            self.camera.set(cv2.CAP_PROP_FRAME_WIDTH, self.width)
            self.camera.set(cv2.CAP_PROP_FRAME_HEIGHT, self.height)
            self.camera.set(cv2.CAP_PROP_FPS, self.fps)

            actual_w = int(self.camera.get(cv2.CAP_PROP_FRAME_WIDTH))
            actual_h = int(self.camera.get(cv2.CAP_PROP_FRAME_HEIGHT))
            actual_fps = self.camera.get(cv2.CAP_PROP_FPS)
            logger.info(f"Camera initialized: {actual_w}x{actual_h} @ {actual_fps:.1f} fps")
        except Exception as e:
            logger.error(f"Error initializing camera: {e}")
            self.camera = None
            raise

    def _decode_frame(self, data):
        """Decode JPEG data into a NumPy frame using the OpenCV imdecode helper."""
        if data is None or len(data) == 0:
            return None
        try:
            data = np.frombuffer(data, dtype=np.uint8)
            frame = cv2.imdecode(data, cv2.IMREAD_COLOR)
            if frame is None:
                logger.warning("cv2.imdecode returned None; invalid JPEG data")
            return frame
        except Exception as e:
            logger.error(f"Error decoding frame: {e}")
            return None

    def _detect_motion(self, prev_frame, curr_frame):
        """Invoke the motion-detection callback with the current frame and previous frame."""
        try:
            self.detect_motion_function(prev_frame, curr_frame)
        except Exception as e:
            logger.error(f"Error in motion detection callback: {e}")

    def _process_frame(self, data):
        """Process a single frame: decode, detect motion, and broadcast JPEG data."""
        if data is None or len(data) == 0:
            return

        frame = self._decode_frame(data)
        if frame is None:
            return

        with self.lock:
            prev_frame = self.frame
            self.frame = frame

        if prev_frame is not None:
            self._detect_motion(prev_frame, frame)

        if self.loop and self.loop.get_debug():
            logger.debug("Broadcasting frame (thread)")
        self.loop.call_soon_threadsafe(self._broadcast_frame, data)

    def _broadcast_frame(self, data):
        """Broadcast frame data to connected WebSocket clients."""
        if self.handler.has_connections():
            self.handler.broadcast(data)

    def _capture_loop(self):
        """Background capture loop: reads frames and dispatches them to processing."""
        while not self._stop_event.is_set():
            try:
                ret, data = self.camera.read()
                if not ret or data is None:
                    logger.warning("Failed to capture frame from camera")
                    continue
                self._process_frame(data)
            except Exception as e:
                logger.error(f"Error in capture loop: {e}")
                break

    def start(self, loop, handler):
        """Start the camera feed and background capture thread."""
        if self.running:
            logger.warning("Camera feed is already running")
            return
        if loop is None or not isinstance(loop, asyncio.AbstractEventLoop):
            raise ValueError("loop must be an asyncio event loop")
        if not isinstance(handler, WebSocketHandler):
            raise ValueError("handler must be a WebSocketHandler instance")

        self.loop = loop
        self.handler = handler

        try:
            self._initialize_camera()
        except Exception:
            logger.error("Failed to start camera feed")
            return

        self.running = True
        self._stop_event.clear()
        self.thread = threading.Thread(target=self._capture_loop, daemon=True, name="CameraFeedThread")
        self.thread.start()
        logger.info("Camera feed started")

    def stop(self):
        """Stop the camera feed and release all resources."""
        if not self.running:
            return
        self.running = False
        self._stop_event.set()
        if self.thread and self.thread.is_alive():
            self.thread.join(timeout=5.0)
        if self.camera is not None:
            try:
                self.camera.release()
            except Exception as e:
                logger.error(f"Error releasing camera: {e}")
            finally:
                self.camera = None
        logger.info("Camera feed stopped")


def _detect_motion_placeholder(prev_frame, curr_frame):
    """Example motion-detection callback (replace with real implementation)."""
    if prev_frame is not None and curr_frame is not None:
        diff = cv2.absdiff(prev_frame, curr_frame)
        gray = cv2.cvtColor(diff, cv2.COLOR_BGR2GRAY)
        blur = cv2.GaussianBlur(gray, (5, 5), 0)
        _, thresh = cv2.threshold(blur, 20, 255, cv2.THRESH_BINARY)
        cnts = cv2.findContours(thresh.copy(), cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
        cnts = cnts[0] if len(cnts) == 2 else cnts[1]
        if cnts:
            logger.info(f"Motion detected: {len(cnts)} contours")


def main():
    handler = WebSocketHandler()
    feed = CameraFeed(camera_id=0, width=64, height=48, fps=10, detect_motion_function=_detect_motion_placeholder)

    def _signal_handler(signum, frame):
        logger.info(f"Signal {signum} received, shutting down...")
        feed.stop()
        loop.stop()

    loop = asyncio.new_event_loop()
    asyncio.set_event_loop(loop)
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        feed.start(loop, handler)
        loop.run_forever()
    except Exception as e:
        logger.error(f"Fatal error: {e}")
    finally:
        feed.stop()
        loop.close()
        logger.info("Shutdown complete")


if __name__ == "__main__":
    main()

