import sys
import time
import signal
import logging
import numpy as np
import cv2
import requests
import megengine as mge
import megengine.data.transform as T
import megengine.data.dataset as D
from megengine.data.transform import Crop, Resize
from megengine.data.dataset import ImageFolderDataset
from megengine.module import QATModule

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

_camera = None


def _signal_handler(signum, frame):
    global _camera
    logger.info(f"Signal {signum} received, shutting down.")
    if _camera is not None:
        try:
            _camera.stop()
        except Exception:
            pass
        try:
            _camera.close()
        except Exception:
            pass
    sys.exit(0)


signal.signal(signal.SIGINT, _signal_handler)
signal.signal(signal.SIGTERM, _signal_handler)


def download_url(url, save_path):
    try:
        resp = requests.get(url, stream=True, timeout=60)
        resp.raise_for_status()
        with open(save_path, 'wb') as f:
            for chunk in resp.iter_content(chunk_size=8192):
                f.write(chunk)
    except requests.exceptions.RequestException as e:
        logger.error(f"Error downloading {url}: {e}")
        raise


def load_labels(label_file):
    try:
        with open(label_file, 'r') as f:
            return [line.strip() for line in f.readlines()]
    except FileNotFoundError:
        logger.error(f"Label file not found: {label_file}")
        raise
    except Exception as e:
        logger.error(f"Error loading labels: {e}")
        raise


def transform_test(image, short=256, crop_size=224):
    try:
        image = cv2.cvtColor(image, cv2.COLOR_BGR2RGB)
        image = cv2.resize(image, (short, short))
        image = T.CenterCrop(crop_size)(image)
        image = np.transpose(image, (2, 0, 1))
        image = np.expand_dims(image, axis=0)
        image = image.astype(np.float32)
        mean = np.array([0.485, 0.456, 0.406]).reshape(3, 1, 1)
        std = np.array([0.229, 0.224, 0.225]).reshape(3, 1, 1)
        image = (image - mean) / std
        return image
    except Exception as e:
        logger.error(f"Error transforming image: {e}")
        raise


def predict(model, image, topk=3):
    try:
        prob = model(image)[0].numpy()
        idx = np.argsort(prob)[::-1][:topk]
        return idx, prob[idx]
    except Exception as e:
        logger.error(f"Error during prediction: {e}")
        raise


def main():
    global _camera
    model_url = 'http://download.tensorflow.org/models/resnet_v2_50_2016_08_28.tar.gz'
    labels_file = 'labels.txt'
    image_dir = 'images'
    os.makedirs(image_dir, exist_ok=True)

    try:
        labels = load_labels(labels_file)
    except Exception:
        return

    try:
        download_url(model_url, 'resnet_v2_50.tar.gz')
    except Exception:
        return

    try:
        from megengine.data.transform import Transform
        from megengine.data.dataset import ImageFolderDataset
        from megengine.module import QATModule
        from megengine.quantization.utils import load_checkpoint_with_eval

        def build_transform(short=256, crop_size=224):
            return Transform(
                T.Compose([
                    Resize(short),
                    Crop(crop_size),
                    T.ToMode('CHW'),
                    T.ToType(np.float32),
                    T.Normalize(mean=0.485, std=0.229),
                ])
            )

        dataset = ImageFolderDataset(image_dir, transform=build_transform())
        model = QATModule(dataset.init_model())
        load_checkpoint_with_eval(model, 'resnet_v2_50.tar.gz')
    except Exception as e:
        logger.error(f"Error loading model: {e}")
        return

    try:
        _camera = cv2.VideoCapture(0)
        if not _camera.isOpened():
            raise RuntimeError("Cannot open camera at index 0")
    except Exception as e:
        logger.error(f"Camera error: {e}")
        return

    try:
        ret, frame = _camera.read()
        if not ret or frame is None:
            raise RuntimeError("Cannot read frame from camera")
    except Exception as e:
        logger.error(f"Camera read error: {e}")
        _camera.release()
        return

    try:
        timestamp = time.strftime("%Y%m%d%H%M%S", time.localtime())
        image_path = os.path.join(image_dir, f"{timestamp}.jpg")
        if not cv2.imwrite(image_path, frame):
            raise RuntimeError(f"Failed to write image to {image_path}")
        logger.info(f"Image saved to {image_path}")
    except Exception as e:
        logger.error(f"Error saving image: {e}")
        _camera.release()
        return

    try:
        transformed_image = transform_test(frame)
    except Exception:
        _camera.release()
        return

    try:
        top_indices, top_probs = predict(model, transformed_image)
        for i in top_indices:
            logger.info(f"prob={top_probs[i]:.5f}, {labels[i]}")
    except Exception as e:
        logger.error(f"Prediction error: {e}")
    finally:
        _camera.release()


if __name__ == '__main__':
    main()

