import io
import logging
import signal
import threading
import time
from typing import Callable, Optional

import cv2
import numpy as np
from picamera2 import Picamera2
from picamera2.encoders import MJPEGEncoder
from picamera2.outputs import Output

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class CameraStreamBuffer:
    """Thread-safe buffer for streaming complete JPEG frames from the camera."""

    def __init__(self, motion_detect_function: Callable[[np.ndarray, np.ndarray], None]):
        if not callable(motion_detect_function):
            raise TypeError("motion_detect_function must be callable")
        self._buffer = io.BytesIO()
        self._lock = threading.Lock()
        self._motion_detect_function = motion_detect_function

    def write(self, data: bytes) -> int:
        """Accumulate bytes; detect JPEG boundaries and broadcast complete frames."""
        with self._lock:
            self._buffer.write(data)
            data_bytes = self._buffer.getvalue()
            start_idx = 0
            while start_idx < len(data_bytes) - 1:
                if data_bytes[start_idx] == 0xFF and data_bytes[start_idx + 1] == 0xD8:
                    frame_data = data_bytes[start_idx:start_idx + 1024]
                    if self._has_active_connections():
                        self._broadcast(frame_data)
                    start_idx += len(frame_data)
                else:
                    start_idx += 1
            if start_idx > 0:
                self._buffer.seek(0)
                self._buffer.truncate()
                self._buffer.write(data_bytes[start_idx:])
        return len(data)

    def flush(self) -> None:
        """Emit any remaining buffered frame."""
        with self._lock:
            if self._buffer.tell() > 0:
                frame_data = self._buffer.getvalue()
                if self._has_active_connections():
                    self._broadcast(frame_data)
                self._buffer.seek(0)
                self._buffer.truncate()

    def _has_active_connections(self) -> bool:
        """Placeholder for WebSocket connection management."""
        return True

    def _broadcast(self, frame_data: bytes) -> None:
        """Placeholder for WebSocket broadcast."""
        pass


class MotionDetectionBuffer(Output):
    """Picamera2 Output that buffers complete JPEG frames for motion detection."""

    def __init__(self, camera: Picamera2, motion_detect_function: Callable[[np.ndarray, np.ndarray], None]):
        if not callable(motion_detect_function):
            raise TypeError("motion_detect_function must be callable")
        super().__init__()
        self._camera = camera
        self._buffer = io.BytesIO()
        self._lock = threading.Lock()
        self._motion_detect_function = motion_detect_function
        self._previous_frame: Optional[np.ndarray] = None
        self._current_frame: Optional[np.ndarray] = None

    def outputframe(self, frame: bytes, keyframe: bool = True, timestamp: int = 0) -> None:
        """Called by picamera2 for each encoded frame; detects JPEG boundaries and runs motion detection."""
        try:
            with self._lock:
                self._buffer.write(frame)
                data_bytes = self._buffer.getvalue()
                start_idx = 0
                while start_idx < len(data_bytes) - 1:
                    if data_bytes[start_idx] == 0xFF and data_bytes[start_idx + 1] == 0xD8:
                        frame_data = data_bytes[start_idx:start_idx + 1024]
                        self._process_frame(frame_data)
                        start_idx += len(frame_data)
                    else:
                        start_idx += 1
                if start_idx > 0:
                    self._buffer.seek(0)
                    self._buffer.truncate()
                    self._buffer.write(data_bytes[start_idx:])
        except Exception as e:
            logger.error(f"Error in MotionDetectionBuffer: {e}", exc_info=True)

    def _process_frame(self, frame_data: bytes) -> None:
        """Decode a JPEG frame, store previous/current, and run motion detection."""
        try:
            frame_np = self._camera.decode_frame(frame_data)
            if frame_np is None:
                logger.error("decode_frame returned None; skipping.")
                return
            with self._lock:
                self._previous_frame = self._current_frame
                self._current_frame = frame_np
            if self._previous_frame is not None and self._current_frame is not None:
                self._motion_detect_function(self._previous_frame.copy(), self._current_frame.copy())
        except Exception as e:
            logger.error(f"Error processing frame: {e}", exc_info=True)

    def flush(self) -> None:
        """Emit any remaining buffered frame."""
        with self._lock:
            if self._buffer.tell() > 0:
                frame_data = self._buffer.getvalue()
                frame_np = self._camera.decode_frame(frame_data)
                if frame_np is not None:
                    self._previous_frame = self._current_frame
                    self._current_frame = frame_np
                self._buffer.seek(0)
                self._buffer.truncate()


def main() -> None:
    camera = Picamera2()
    try:
        video_config = camera.create_video_configuration(
            main={"size": (640, 480), "format": "RGB888"},
            lores={"size": (320, 240), "format": "YUV420"},
            encode="lores",
        )
        camera.configure(video_config)
        camera.start()
        logger.info("Camera started successfully.")

        stream_buffer = CameraStreamBuffer(lambda prev, curr: None)
        motion_buffer = MotionDetectionBuffer(camera, lambda prev, curr: None)
        camera.start_recording(MJPEGEncoder(), motion_buffer)
        logger.info("Recording started with motion detection buffer.")

        stop_event = threading.Event()

        def signal_handler(signum, frame):
            logger.info(f"Signal {signum} received; shutting down.")
            stop_event.set()

        signal.signal(signal.SIGINT, signal_handler)
        signal.signal(signal.SIGTERM, signal_handler)

        while not stop_event.is_set():
            time.sleep(0.1)

    except Exception as e:
        logger.error(f"An error occurred: {e}", exc_info=True)
    finally:
        try:
            camera.stop_recording()
        except Exception:
            pass
        try:
            camera.stop()
        except Exception:
            pass
        try:
            stream_buffer.flush()
        except Exception:
            pass
        try:
            motion_buffer.flush()
        except Exception:
            pass
        logger.info("Program terminated.")


if __name__ == "__main__":
    main()

