import io
import logging
import numpy as np

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class CameraStreamBuffer:
    """
    A buffer that receives MJPEG data from the camera driver and decodes complete
    H.264 frames using the provided driver's imdecode on a NumPy array.
    """

    def __init__(self, c):
        if c is None:
            raise ValueError("Camera driver instance 'c' must not be None")
        self.c = c
        self.buf = io.BytesIO()
        self.output = None
        self.encode = None
        self.frame_complete = False
        self.current_frame_type = None

    def set_output(self, output):
        self.output = output

    def set_encode(self, encode):
        self.encode = encode

    def write(self, d):
        if d:
            self.buf.write(d)
            if self.encode and self.encode.get('motion_detection'):
                self.frame_complete = True
            elif self.encode and not self.encode.get('motion_detection'):
                self.frame_complete = True
        else:
            if self.frame_complete and self.output:
                try:
                    data = self.buf.getvalue()
                    if data:
                        array = self.c.imdecode(np.frombuffer(data, dtype=np.uint8))
                        if array is not None:
                            self.output.write(array)
                        else:
                            logger.warning("imdecode returned None; skipping frame.")
                    self.buf.seek(0)
                    self.buf.truncate(0)
                except Exception as e:
                    logger.error(f"Error processing frame: {e}")
        return len(d)


class MotionDetectionBuffer:
    """
    A buffer that detects motion by comparing consecutive JPEG frames.
    """

    def __init__(self, f):
        if f is None:
            raise ValueError("Callback function 'f' must not be None")
        self.f = f
        self.buf = io.BytesIO()
        self.previous_frame = None
        self.current_frame = None

    def write(self, d):
        if d:
            self.buf.write(d)
            data = self.buf.getvalue()
            start_marker = b'\xff\xd8'
            end_marker = b'\xff\xd9'

            start_idx = data.find(start_marker)
            end_idx = data.find(end_marker)

            if start_idx != -1 and end_idx != -1:
                jpeg_data = data[start_idx:end_idx + 2]
                try:
                    if self.previous_frame is not None:
                        self.current_frame = self.f(self.previous_frame, self.current_frame)
                    self.previous_frame = self.current_frame
                    self.current_frame = jpeg_data
                except Exception as e:
                    logger.error(f"Error in motion detection callback: {e}")

                self.buf.seek(0)
                self.buf.truncate(0)
                self.buf.write(data[end_idx + 2:])
        return len(d)

