import time
import signal
import sys
import config
import face
import audio

try:
    from gpiozero import Button, OutputDevice
except ImportError:
    print("Error: gpiozero is required. Install with: pip install gpiozero", file=sys.stderr)
    sys.exit(1)


class Door:
    """Thin wrapper around gpiozero for the button (pull-up) and lock actuator."""

    def __init__(self, button_pin=17, lock_pin=18):
        self.button = Button(button_pin, pull_up=True, bounce_time=0.05)
        self.lock = OutputDevice(lock_pin, active_high=True, initial_value=True)

    def is_button_up(self):
        """Return True when the button is pressed (pin reads LOW)."""
        return not self.button.is_pressed

    def lock_door(self):
        self.lock.on()

    def unlock_door(self):
        self.lock.off()

    def cleanup(self):
        self.lock.close()
        self.button.close()


class SoundSystem:
    """Manages audio playback and pre-loading of sound files."""

    def __init__(self, sample_rate=48000):
        self.sample_rate = sample_rate
        self.audio_queue = []
        self.sounds = {}
        self._running = True

    def load_sound(self, filename):
        """Load a sound file into memory; return None on failure."""
        try:
            return audio.AudioFile(filename, self.sample_rate)
        except Exception as e:
            print(f"Error loading sound file '{filename}': {e}", file=sys.stderr)
            return None

    def preload_sound(self, filename):
        """Pre-load a sound file into the audio queue."""
        sound = self.load_sound(filename)
        if sound is not None:
            self.audio_queue.append(sound)

    def play_sound(self, sound):
        """Add a sound to the audio queue for playback."""
        if sound is not None:
            self.audio_queue.append(sound)

    def stop(self):
        """Signal the audio thread to stop."""
        self._running = False

    def is_running(self):
        return self._running


def signal_handler(signum, frame, door, sound_system):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    print(f"\nReceived signal {signum}, shutting down...")
    sound_system.stop()
    door.cleanup()
    sys.exit(0)


def main():
    door = None
    sound_system = None
    try:
        door = Door()
        sound_system = SoundSystem()

        # Register signal handlers
        signal.signal(signal.SIGINT, lambda s, f: signal_handler(s, f, door, sound_system))
        signal.signal(signal.SIGTERM, lambda s, f: signal_handler(s, f, door, sound_system))

        # Pre-load sounds
        sound_system.preload_sound(config.WELCOME_SOUND_PATH)
        sound_system.preload_sound(config.WAIT_SOUND_PATH)
        sound_system.preload_sound(config.LATER_SOUND_PATH)

        # Load face recognition model
        print("Loading face recognition model...")
        try:
            face_recognizer = face.EigenFaceRecognizer(config.TRAINING_FILE)
        except Exception as e:
            print(f"Error loading training data: {e}", file=sys.stderr)
            return

        print("Running Lock System...")
        print("Press button to lock (if unlocked), or unlock if the correct face is detected.")
        print("Press Ctrl-C to quit.")

        while True:
            try:
                if door.is_button_up():
                    print("Button pressed, looking for face...")
                    try:
                        image = face.get_image()
                        label, confidence = face_recognizer.predict(image)

                        if label == config.POSITIVE_LABEL and confidence < config.POSITIVE_THRESHOLD:
                            print("Recognized face! Unlocking Door...")
                            door.unlock_door()
                            sound_system.play_sound(sound_system.sounds.get(config.WELCOME_SOUND_PATH))
                        else:
                            print("Face not recognized.")
                            sound_system.play_sound(sound_system.sounds.get(config.LATER_SOUND_PATH))
                    except Exception as e:
                        print(f"Error during face recognition: {e}", file=sys.stderr)
                        sound_system.play_sound(sound_system.sounds.get(config.LATER_SOUND_PATH))
                time.sleep(0.1)

            except Exception as e:
                print(f"An error occurred: {e}", file=sys.stderr)
                time.sleep(1)

    except Exception as e:
        print(f"Fatal error: {e}", file=sys.stderr)
    finally:
        if door is not None:
            door.cleanup()
        print("Exiting...")


if __name__ == "__main__":
    main()

