import os
import sys
import signal
import logging
import termios
import tty
import contextlib

import speech_recognition as sr
from picamera2 import Picamera2
from picamera2.encoders import JpegEncoder
from picamera2.outputs import FileOutput
import sx126x

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
SAMPLE_RATE = 44100
CHUNK_SIZE = 1024
CAPTURE_COMMAND = "capture"
DESKTOP_PATH = "/home/raspberry/Desktop/IoT Project"
IMAGE_PATH = os.path.join(DESKTOP_PATH, "captured_image.jpg")
LORA_FREQUENCY = 868
LORA_ADDRESS = 0
LORA_POWER = 22
LORA_AIR_SPEED = 2400

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_running = True
_old_settings = None
_camera = None
_lora = None


def _signal_handler(signum, frame):
    global _running
    _running = False


signal.signal(signal.SIGINT, _signal_handler)
signal.signal(signal.SIGTERM, _signal_handler)


def _restore_terminal():
    global _old_settings
    if _old_settings is not None:
        try:
            termios.tcsetattr(sys.stdin, termios.TCSADRAIN, _old_settings)
        except Exception as exc:
            logging.warning("Could not restore terminal settings: %s", exc)
        _old_settings = None


@contextlib.contextmanager
def _raw_mode():
    global _old_settings
    try:
        _old_settings = termios.tcgetattr(sys.stdin)
        tty.setraw(sys.stdin.fileno())
        yield
    finally:
        try:
            termios.tcsetattr(sys.stdin, termios.TCSADRAIN, _old_settings)
        except Exception:
            pass
        _old_settings = None


def _cleanup():
    global _camera, _lora
    if _camera is not None:
        try:
            _camera.stop()
        except Exception as exc:
            logging.warning("Error stopping camera: %s", exc)
        _camera = None
    if _lora is not None:
        try:
            _lora.close()
        except Exception as exc:
            logging.warning("Error closing LoRa: %s", exc)
        _lora = None
    _restore_terminal()


def _init_lora():
    try:
        _lora = sx126x.sx126x(
            freq=LORA_FREQUENCY,
            addr=LORA_ADDRESS,
            power=LORA_POWER,
            rssi=True,
            air_speed=LORA_AIR_SPEED,
            relay=False,
        )
        logging.info("LoRa initialised on %d MHz (addr=%d, power=%d dBm).",
                     LORA_FREQUENCY, LORA_ADDRESS, LORA_POWER)
        return True
    except Exception as exc:
        logging.error("LoRa init failed: %s", exc)
        _lora = None
        return False


def _init_camera():
    global _camera
    try:
        _camera = Picamera2()
        _camera.configure(
            _camera.create_still_configuration(
                main={"size": (640, 480), "format": "RGB888"}
            )
        )
        _camera.start()
        logging.info("Camera initialised at 640x480.")
        return True
    except Exception as exc:
        logging.error("Camera init failed: %s", exc)
        _camera = None
        return False


def _ensure_desktop_dir():
    try:
        os.makedirs(DESKTOP_PATH, exist_ok=True)
        return True
    except OSError as exc:
        logging.error("Cannot create desktop directory %s: %s", DESKTOP_PATH, exc)
        return False


def _capture_image():
    if _camera is None:
        logging.error("Camera not initialised; cannot capture.")
        return False
    try:
        _camera.capture_file(IMAGE_PATH)
        logging.info("Image saved to %s", IMAGE_PATH)
        return True
    except Exception as exc:
        logging.error("Image capture failed: %s", exc)
        return False


def _send_lora_message(message):
    if _lora is None:
        logging.error("LoRa not initialised; cannot send.")
        return False
    try:
        data = message.encode("utf-8")
        _lora.send(data)
        logging.info("LoRa message sent: %s", message)
        return True
    except Exception as exc:
        logging.error("LoRa send failed: %s", exc)
        return False


def _recognize_speech():
    recognizer = sr.Recognizer()
    try:
        with _raw_mode(), sr.Microphone(
            sample_rate=SAMPLE_RATE,
            chunk_size=CHUNK_SIZE,
        ) as source:
            logging.info("Listening for '%s'... (Ctrl-C to quit)", CAPTURE_COMMAND)
            recognizer.adjust_for_ambient_noise(source, duration=1)
            audio = recognizer.listen(source, timeout=5)
    except sr.WaitTimeoutError:
        logging.warning("No speech detected within timeout.")
        return None
    except Exception as exc:
        logging.error("Microphone error: %s", exc)
        return None

    try:
        text = recognizer.recognize_google(audio)
        logging.info("Heard: %s", text)
        return text.lower()
    except sr.UnknownValueError:
        logging.warning("Speech not understood.")
        return None
    except sr.RequestError as exc:
        logging.error("Speech recognition service error: %s", exc)
        return None


def main():
    if not _ensure_desktop_dir():
        return

    if not _init_camera():
        return

    if not _init_lora():
        logging.warning("LoRa unavailable; continuing without transmit.")

    try:
        while _running:
            command = _recognize_speech()
            if command is None:
                continue
            if CAPTURE_COMMAND in command:
                if _capture_image():
                    _send_lora_message("Image captured")
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

