import time
import threading
import signal
import sys
import smbus
import RPi.GPIO as GPIO

# Constants
LCD_I2C_ADDR = 0x27
LCD_WIDTH = 16
LCD_CHR = 1
LCD_CMD = 0
LCD_LINE_1 = 0x80
LCD_LINE_2 = 0xC0
LCD_BACKLIGHT = 0x08
ENABLE = 0x04
E_PULSE = 0.0005
E_DELAY = 0.0005

# GPIO pin assignments for LEDs (BCM numbering)
LED_PINS = [17, 18, 23, 27, 22]


class LCD:
    def __init__(self, bus_num=1):
        self.bus = smbus.SMBus(bus_num)
        self.backlight = LCD_BACKLIGHT
        self._init_lcd()

    def _write_byte(self, addr, val):
        try:
            self.bus.write_byte_data(LCD_I2C_ADDR, addr, val)
        except OSError as e:
            raise RuntimeError(f"I2C write failed (addr=0x{addr:02X}, val=0x{val:02X}): {e}")

    def _toggle_enable(self, bits):
        time.sleep(E_DELAY)
        self._write_byte(LCD_I2C_ADDR, bits | ENABLE)
        time.sleep(E_PULSE)
        self._write_byte(LCD_I2C_ADDR, bits & ~ENABLE)
        time.sleep(E_DELAY)

    def _init_lcd(self):
        self._write_byte(LCD_I2C_ADDR, 0x33)
        self._write_byte(LCD_I2C_ADDR, 0x32)
        self._write_byte(LCD_I2C_ADDR, 0x06)
        self._write_byte(LCD_I2C_ADDR, 0x0C)
        self._write_byte(LCD_I2C_ADDR, 0x28)
        self._write_byte(LCD_I2C_ADDR, 0x01)
        time.sleep(E_DELAY)

    def lcd_string(self, message, line):
        message = message.ljust(LCD_WIDTH, " ")
        self._write_byte(LCD_I2C_ADDR, line)
        for ch in message:
            self._write_byte(LCD_I2C_ADDR, ord(ch))

    def clear(self):
