import time
import signal
import sys

try:
    import smbus2 as smbus
except ImportError:
    import smbus

# Constants
I2C_BUS = 1
OLED_ADDR = 0x3C
THERMAL_ZONE = "/sys/class/thermal/thermal_zone0/temp"

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global _running
    _running = False

def read_temperature():
    """Reads the CPU temperature from the thermal zone file."""
    try:
        with open(THERMAL_ZONE, "r") as f:
            temp_raw = f.read().strip()
            return float(temp_raw) / 1000.0
    except FileNotFoundError:
        print(f"Error: Thermal zone file not found: {THERMAL_ZONE}")
        return None
    except PermissionError:
        print(f"Error: Permission denied reading {THERMAL_ZONE}")
        return None
    except (ValueError, OSError) as e:
        print(f"Error reading temperature: {e}")
        return None

def main():
    """Main function to read and display CPU temperature."""
    global _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # Initialize I2C bus for bus availability check (bus 1 only)
    bus = None
    try:
        bus = smbus.SMBus(I2C_BUS)
    except FileNotFoundError:
        print(f"Error: I2C bus {I2C_BUS} not found. Enable I2C via raspi-config.")
        sys.exit(1)
    except PermissionError:
        print(f"Error: Permission denied opening I2C bus {I2C_BUS}. Run as root or add user to i2c group.")
        sys.exit(1)
    except OSError as e:
        print(f"Error initializing I2C bus {I2C_BUS}: {e}")
        sys.exit(1)

    try:
        while _running:
            temperature = read_temperature()
            if temperature is not None:
                print(f"CPU Temperature: {temperature:.2f} °C")
            time.sleep(2)
    finally:
        if bus is not None:
            try:
                bus.close()
            except Exception:
                pass
        print("Program terminated.")

if __name__ == "__main__":
    main()

