import time
import signal
import sys
import logging
import configparser
from typing import Optional, Tuple

import RPi.GPIO as GPIO
import adafruit_dht
from adafruit_character_lcd.character_lcd_i2c import Character_LCD_I2C

try:
    from greenhouse_vent import vent  # type: ignore
except ImportError:
    print("Warning: greenhouse_vent module not found; vent angle will be 0.")
    vent = lambda: 0

CONFIG_FILE = "greenhouse.conf"
LOG_FILE = "greenhouse.log"

DEFAULT_CONFIG = {
    "GPIO": {
        "lcd_rs": "25",
        "lcd_en": "24",
        "lcd_d4": "23",
        "lcd_d5": "17",
        "lcd_d6": "18",
        "lcd_d7": "22",
        "dht_pin": "4",
        "servo_pin": "12",
    },
    "ventilation": {
        "temp_low": "20",
        "temp_mid": "25",
    },
    "logging": {
        "level": "INFO",
    },
}

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def load_config(config_file: str) -> configparser.ConfigParser:
    config = configparser.ConfigParser()
    config.read_dict(DEFAULT_CONFIG)
    try:
        with open(config_file, "r") as f:
            config.read_file(f)
    except FileNotFoundError:
        logging.warning(f"Config file {config_file} not found; using defaults.")
    except PermissionError:
        logging.error(f"Permission denied reading {config_file}; using defaults.")
    except configparser.Error as e:
        logging.error(f"Error parsing {config_file}: {e}; using defaults.")
    return config


def setup_logging(log_file: str, level_str: str) -> None:
    numeric_level = getattr(logging, level_str.upper(), logging.INFO)
    logging.basicConfig(
        filename=log_file,
        level=numeric_level,
        format="%(asctime)s - %(levelname)s - %(message)s",
    )


def init_lcd(config: configparser.ConfigParser) -> Optional[Character_LCD_I2C]:
    try:
        lcd = Character_LCD_I2C(
            i2c_expander="PCF8574",
            address=0x27,
            port=1,
            rs=int(config["GPIO"]["lcd_rs"]),
            en=int(config["GPIO"]["lcd_en"]),
            d4=int(config["GPIO"]["lcd_d4"]),
            d5=int(config["GPIO"]["lcd_d5"]),
            d6=int(config["GPIO"]["lcd_d6"]),
            d7=int(config["GPIO"]["lcd_d7"]),
            cols=16,
            rows=2,
        )
        lcd.clear()
        return lcd
    except Exception as e:
        logging.error(f"LCD init failed: {e}")
        return None


def init_dht22(config: configparser.ConfigParser) -> Optional[adafruit_dht.DHT22]:
    try:
        pin = int(config["GPIO"]["dht_pin"])
        return adafruit_dht.DHT22(pin, use_pulseio=False)
    except Exception as e:
        logging.error(f"DHT22 init failed: {e}")
        return None


def read_dht22(sensor: adafruit_dht.DHT22) -> Tuple[Optional[float], Optional[float]]:
    for attempt in range(3):
        try:
            temp = sensor.temperature
            hum = sensor.humidity
            if temp is not None and hum is not None:
                return temp, hum
        except RuntimeError as e:
            logging.warning(f"DHT22 read attempt {attempt + 1} failed: {e}")
        except Exception as e:
            logging.error(f"DHT22 unexpected error: {e}")
            break
        time.sleep(2)
    return None, None


def update_lcd(lcd, temp: Optional[float], hum: Optional[float], angle: int) -> None:
    if lcd is None:
        return
    try:
        lcd.clear()
        t = f"{temp:.1f}" if temp is not None else "--"
        h = f"{hum:.1f}" if hum is not None else "--"
        lcd.message = f"Temp: {t}C\nVent: {angle}deg"
    except Exception as e:
        logging.error(f"LCD update failed: {e}")


def cleanup(lcd, sensor, dht_pin: int) -> None:
    logging.info("Cleaning up resources.")
    if lcd is not None:
        try:
            lcd.clear()
            lcd.close()
        except Exception as e:
            logging.error(f"LCD cleanup error: {e}")
    if sensor is not None:
        try:
            sensor.exit()
        except Exception as e:
            logging.error(f"DHT22 cleanup error: {e}")
    try:
        GPIO.cleanup()
    except Exception as e:
        logging.error(f"GPIO cleanup error: {e}")


def main() -> None:
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    config = load_config(CONFIG_FILE)
    setup_logging(LOG_FILE, config["logging"]["level"])

    lcd = init_lcd(config)
    sensor = init_dht22(config)

    if lcd is None and sensor is None:
        logging.critical("No hardware initialized; exiting.")
        sys.exit(1)

    temp_low = int(config["ventilation"]["temp_low"])
    temp_mid = int(config["ventilation"]["temp_mid"])

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
    except Exception as e:
        logging.critical(f"GPIO setmode failed: {e}")
        cleanup(lcd, sensor, int(config["GPIO"]["dht_pin"]))
        sys.exit(1)

    try:
        while _running:
            temp, hum = read_dht22(sensor)
            if temp is not None and hum is not None:
                logging.info(f"Temp: {temp:.1f}C, Humidity: {hum:.1f}%")
            else:
                logging.warning("DHT22 read failed; using last good values or defaults.")

            try:
                angle = vent(temp, hum, temp_low, temp_mid)
                logging.info(f"Vent angle: {angle}deg")
            except Exception as e:
                logging.error(f"Vent API call failed: {e}")
                angle = 0

            update_lcd(lcd, temp, hum, angle)

            for _ in range(5):
                if not _running:
                    break
                time.sleep(1)
    finally:
        cleanup(lcd, sensor, int(config["GPIO"]["dht_pin"]))


if __name__ == "__main__":
    main()

