            hum = sensor.humidity
            if temp is not None and hum is not None:
                return temp, hum
        except RuntimeError as e:
            logging.warning(f"DHT22 read attempt {attempt + 1} failed: {e}")
        except Exception as e:
            logging.error(f"DHT22 unexpected error: {e}")
            break
        time.sleep(2)
    return None, None


def update_lcd(lcd, temp: Optional[float], hum: Optional[float], angle: int) -> None:
    if lcd is None:
        return
    try:
        lcd.clear()
        t = f"{temp:.1f}" if temp is not None else "--"
        h = f"{hum:.1f}" if hum is not None else "--"
        lcd.message = f"Temp: {t}C\nVent: {angle}deg"
    except Exception as e:
        logging.error(f"LCD update failed: {e}")


def cleanup(lcd, sensor, dht_pin: int) -> None:
    logging.info("Cleaning up resources.")
    if lcd is not None:
        try:
            lcd.clear()
            lcd.close()
        except Exception as e:
            logging.error(f"LCD cleanup error: {e}")
    if sensor is not None:
        try:
            sensor.exit()
        except Exception as e:
            logging.error(f"DHT22 cleanup error: {e}")
    try:
        GPIO.cleanup()
    except Exception as e:
        logging.error(f"GPIO cleanup error: {e}")


def main() -> None:
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    config = load_config(CONFIG_FILE)
    setup_logging(LOG_FILE, config["logging"]["level"])

    lcd = init_lcd(config)
    sensor = init_dht22(config)

    if lcd is None and sensor is None:
        logging.critical("No hardware initialized; exiting.")
        sys.exit(1)

    temp_low = int(config["ventilation"]["temp_low"])
    temp_mid = int(config["ventilation"]["temp_mid"])

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
    except Exception as e:
        logging.critical(f"GPIO setmode failed: {e}")
        cleanup(lcd, sensor, int(config["GPIO"]["dht_pin"]))
        sys.exit(1)

    try:
        while _running:
            temp, hum = read_dht22(sensor)
            if temp is not None and hum is not None:
                logging.info(f"Temp: {temp:.1f}C, Humidity: {hum:.1f}%")
            else:
                logging.warning("DHT22 read failed; using last good values or defaults.")

            try:
                angle = vent(temp, hum, temp_low, temp_mid)
                logging.info(f"Vent angle: {angle}deg")
            except Exception as e:
                logging.error(f"Vent API call failed: {e}")
                angle = 0

            update_lcd(lcd, temp, hum, angle)

            for _ in range(5):
                if not _running:
                    break
                time.sleep(1)
    finally:
        cleanup(lcd, sensor, int(config["GPIO"]["dht_pin"]))


