import signal
import sys
import time
import board
import busio
import adafruit_bme280
import adafruit_tsl2561
from adafruit_ssd1306 import SSD1306_I2C

# Global resources for cleanup
_i2c = None
_oled = None
_running = True


def cleanup():
    """Clear the OLED and release I2C resources on exit."""
    global _i2c, _oled
    if _oled is not None:
        try:
            _oled.fill(0)
            _oled.show()
        except Exception:
            pass
    if _i2c is not None:
        try:
            _i2c.deinit()
        except Exception:
            pass


def handle_sigint(signum, frame):
    """Graceful shutdown on SIGINT (Ctrl-C)."""
    global _running
    _running = False


def init_i2c():
    """Initialize the I2C bus; return the bus object or None on failure."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C bus: {e}", file=sys.stderr)
        return None


def init_oled(i2c_bus):
    """Initialize the SSD1306 OLED; return the display object or None on failure."""
    try:
        return SSD1306_I2C(128, 64, i2c_bus)
    except Exception as e:
        print(f"Error initializing OLED: {e}", file=sys.stderr)
        return None


def init_sensors(i2c_bus):
    """Initialize BME280 and TSL2561 sensors; return dict of objects or None on failure."""
    sensors = {}
    try:
        sensors['bme280'] = adafruit_bme280.Adafruit_BME280_I2C(i2c_bus, address=0x76)
    except Exception as e:
        print(f"Error initializing BME280: {e}", file=sys.stderr)
        sensors['bme280'] = None

    try:
        sensors['tsl2561'] = adafruit_tsl2561.TSL2561(i2c_bus)
    except Exception as e:
        print(f"Error initializing TSL2561: {e}", file=sys.stderr)
        sensors['tsl2561'] = None

    if sensors['bme280'] is None and sensors['tsl2561'] is None:
        print("No sensors initialized. Exiting.", file=sys.stderr)
        return None
    return sensors


def read_sensor_data(sensors):
    """Read temperature, humidity, pressure, and light level from sensors.
    Returns a dict of values or None on transient read error."""
    data = {}
    if sensors['bme280'] is not None:
        try:
            data['temperature'] = sensors['bme280'].temperature
            data['humidity'] = sensors['bme280'].humidity
            data['pressure'] = sensors['bme280'].pressure
        except Exception as e:
            print(f"Error reading BME280: {e}", file=sys.stderr)
            data['temperature'] = None
            data['humidity'] = None
            data['pressure'] = None
    else:
        data['temperature'] = None
        data['humidity'] = None
        data['pressure'] = None

    if sensors['tsl2561'] is not None:
        try:
            data['light'] = sensors['tsl2561'].lux
        except Exception as e:
            print(f"Error reading TSL2561: {e}", file=sys.stderr)
            data['light'] = None
    else:
        data['light'] = None

    return data


def display_data(oled, data):
    """Display sensor data on the OLED, four lines per update."""
    oled.fill(0)
    line = 0
    for key, value in data.items():
        if value is not None:
            text = f"{key.capitalize()}: {value:.1f}" if isinstance(value, float) else f"{key.capitalize()}: {value}"
        else:
            text = f"{key.capitalize()}: Error"
        oled.text(text, 0, line * 10, 1)
        line += 1
    oled.show()


def main():
    global _i2c, _oled

    signal.signal(signal.SIGINT, handle_sigint)

    _i2c = init_i2c()
    if _i2c is None:
        sys.exit(1)

    _oled = init_oled(_i2c)
    if _oled is None:
        cleanup()
        sys.exit(1)

    sensors = init_sensors(_i2c)
    if sensors is None:
        cleanup()
        sys.exit(1)

    try:
        while _running:
            data = read_sensor_data(sensors)
            if data:
                display_data(_oled, data)
            time.sleep(1)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

