import os
import time
import signal
import sys
import logging
from PIL import Image, ImageSequence

try:
    import st7789
except ImportError:
    st7789 = None

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

DEFAULT_DISPLAY_WIDTH = 240
DEFAULT_DISPLAY_HEIGHT = 240
DEFAULT_GIF_FOLDER = "./gifs"
DEFAULT_FRAME_DELAY = 0.1  # seconds


class GifPlayer:
    def __init__(self, display_width=DEFAULT_DISPLAY_WIDTH, display_height=DEFAULT_DISPLAY_HEIGHT,
                 gif_folder=DEFAULT_GIF_FOLDER, frame_delay=DEFAULT_FRAME_DELAY):
        self.display_width = display_width
        self.display_height = display_height
        self.gif_folder = gif_folder
        self.frame_delay = frame_delay
        self.display = None
        self.running = True
        self.logger = logging.getLogger(__name__)

        if st7789 is None:
            self.logger.error("st7789 library not available. Install with: pip install st7789")
            return

        try:
            self.display = st7789.ST7789(
                self.display_width, self.display_height,
                spi_port=0, spi_device=0,
                rst_pin=17, dc_pin=25,
                backlight_pin=24, rotation=0,
                bgr=False
            )
            self.display.begin()
            self.logger.info("Display initialized successfully.")
        except Exception as e:
            self.logger.error(f"Failed to initialize display: {e}")
            self.display = None

    def _signal_handler(self, signum, frame):
        self.logger.info(f"Signal {signum} received, shutting down...")
        self.running = False

    def _get_gif_files(self):
        if not os.path.isdir(self.gif_folder):
            self.logger.error(f"GIF folder not found: {self.gif_folder}")
            return []
        try:
            files = [os.path.join(self.gif_folder, f) for f in os.listdir(self.gif_folder)
                     if f.lower().endswith('.gif')]
            return sorted(files)
        except OSError as e:
            self.logger.error(f"Error accessing GIF folder: {e}")
            return []

    def _convert_gif_to_rgb(self, gif_file):
        try:
            image = Image.open(gif_file)
            image.resize((self.display_width, self.display_height))
            return image.convert('RGB')
        except Exception as e:
            self.logger.error(f"Error converting GIF to RGB: {e}")
            return None

    def _get_frame_delay(self, frame):
        try:
            delay = frame.info.get('duration', 0)
            if delay <= 0:
                return self.frame_delay
            return delay / 1000.0
        except Exception:
            return self.frame_delay

    def play(self, gif_file):
        if self.display is None:
            self.logger.error("Display not initialized. Cannot play GIF.")
            return False
        image = self._convert_gif_to_rgb(gif_file)
        if image is None:
            return False
        try:
            for frame in ImageSequence.Iterator(image):
                if not self.running:
                    return False
                frame_delay = self._get_frame_delay(frame)
                frame_image = frame.convert('RGB')
                pixels = frame_image.tobytes()
                self.display.image(pixels)
                time.sleep(frame_delay)
            return True
        except Exception as e:
            self.logger.error(f"Error playing GIF: {e}")
            return False

    def run(self):
        if self.display is None:
            self.logger.error("Display not initialized. Cannot run GIF player.")
            return
        signal.signal(signal.SIGINT, self._signal_handler)
        signal.signal(signal.SIGTERM, self._signal_handler)
        gif_files = self._get_gif_files()
        if not gif_files:
            self.logger.error("No GIF files found in folder.")
            return
        while self.running:
            for gif_file in gif_files:
                if not self.running:
                    break
                self.logger.info(f"Playing: {os.path.basename(gif_file)}")
                if not self.play(gif_file):
                    self.logger.warning(f"Failed to play {gif_file}, skipping.")
            if self.running:
                self.logger.info("Playback completed, restarting...")

    def cleanup(self):
        self.running = False
        if self.display is not None:
            try:
                self.display.cleanup()
            except Exception:
                pass


if __name__ == "__main__":
    player = GifPlayer()
    try:
        player.run()
    except KeyboardInterrupt:
        pass
    finally:
        player.cleanup()

