import os
import time
import signal
import logging
from PIL import Image, ImageOps
import RPi.GPIO as GPIO
from luma.core.interface.serial import i2c
from luma.oled.device import ssd1306
from luma.core.render import canvas

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

DISPLAY_WIDTH = 128
DISPLAY_HEIGHT = 64
I2C_PORT = 1
I2C_ADDRESS = 0x3C

running = True

def signal_handler(sig, frame):
    global running
    running = False
    logging.info("Shutdown signal received. Cleaning up...")

def load_gif(gif_path):
    try:
        image = Image.open(gif_path)
        image.seek(0)
        return image
    except FileNotFoundError:
        logging.error(f"File not found: {gif_path}")
        return None
    except Exception as e:
        logging.error(f"Error loading GIF {gif_path}: {e}")
        return None

def get_frame_duration(image):
    try:
        return image.info.get('duration', 100)
    except Exception:
        return 100

def resize_and_pad(image):
    try:
        resized = image.resize((DISPLAY_WIDTH, DISPLAY_HEIGHT), Image.LANCZOS)
        bg = Image.new('RGB', (DISPLAY_WIDTH, DISPLAY_HEIGHT), (0, 0, 0))
        bg.paste(resized, ((DISPLAY_WIDTH - resized.width) // 2, (DISPLAY_HEIGHT - resized.height) // 2))
        return bg
    except Exception as e:
        logging.error(f"Error resizing/padding image: {e}")
        return None

def display_gif(display, image, duration):
    try:
        with canvas(display) as draw:
            draw.bitmap((0, 0), image)
        time.sleep(duration / 1000.0)
    except Exception as e:
        logging.error(f"Error displaying frame: {e}")

def play_gif(display, gif_path):
    image = load_gif(gif_path)
    if image is None:
        return
    try:
        for frame_index in range(image.n_frames):
            if not running:
                break
            image.seek(frame_index)
            frame_image = ImageOps.invert(image.convert('RGB'))
            duration = get_frame_duration(image)
            padded_frame = resize_and_pad(frame_image)
            if padded_frame is not None:
                display_gif(display, padded_frame, duration)
    except Exception as e:
        logging.error(f"Error playing GIF {gif_path}: {e}")

def play_gif_folder(display, folder_path):
    try:
        gif_files = [f for f in os.listdir(folder_path) if f.lower().endswith('.gif')]
        if not gif_files:
            logging.warning(f"No GIF files found in {folder_path}")
            return
        for gif_file in gif_files:
            if not running:
                break
            gif_path = os.path.join(folder_path, gif_file)
            play_gif(display, gif_path)
    except Exception as e:
        logging.error(f"Error playing GIF folder {folder_path}: {e}")

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    serial = None
    display = None
    try:
        serial = i2c(port=I2C_PORT, address=I2C_ADDRESS)
        display = ssd1306(serial)
        play_gif_folder(display, 'gifs')
    except Exception as e:
        logging.error(f"Fatal error: {e}")
    finally:
        if display:
            try:
                display.cleanup()
            except Exception:
                pass
        if serial:
            try:
                serial.cleanup()
            except Exception:
                pass
        GPIO.cleanup()
        logging.info("Program finished.")

if __name__ == "__main__":
    main()

