import time
import logging
import signal
import sys
from typing import Tuple, Optional

try:
    import smbus2 as smbus
except ImportError:
    import smbus

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class DHT20:
    """Driver for the DHT20 temperature/humidity sensor over I2C."""

    # Register addresses
    REG_STATUS = 0x71
    REG_MEASURE = 0xAC
    REG_DATA = 0x71

    # Status register bit masks
    STATUS_POWER_ON = 0x01
    STATUS_MEASURE_IN_PROGRESS = 0x80

    # CRC-8 parameters
    CRC_POLYNOMIAL = 0x31
    CRC_INITIAL = 0xFF

    def __init__(self, i2c_bus: int = 1, retries: int = 5, retry_delay: float = 2.0,
                 power_on_delay: float = 0.5, read_timeout: float = 0.1):
        self.i2c_bus = i2c_bus
        self.retries = retries
        self.retry_delay = retry_delay
        self.power_on_delay = power_on_delay
        self.read_timeout = read_timeout
        self.bus: Optional[smbus.SMBus] = None
        self._closed = False

        try:
            self.bus = smbus.SMBus(self.i2c_bus)
        except FileNotFoundError:
            logger.error("I2C bus %d not found. Enable I2C and check /dev/i2c-%d.", self.i2c_bus, self.i2c_bus)
            raise
        except PermissionError:
            logger.error("Permission denied on /dev/i2c-%d. Run as root or add user to the 'i2c' group.", self.i2c_bus)
            raise
        except OSError as e:
            logger.error("Failed to open I2C bus %d: %s", self.i2c_bus, e)
            raise

        time.sleep(self.power_on_delay)

        if not self._check_status():
            logger.error("DHT20 not responding or in invalid state. Check wiring and power.")
            self.close()
            raise OSError("DHT20 not responding or in invalid state.")

        logger.info("DHT20 initialized successfully on bus %d.", self.i2c_bus)

    def _check_status(self) -> bool:
        """Read the status register and verify power-on bit is set."""
        try:
            status = self.bus.read_byte_data(0x40, self.REG_STATUS)
            return bool(status & self.STATUS_POWER_ON)
        except OSError as e:
            logger.error("I2C error reading status register: %s", e)
            return False

    def _read_raw_data(self) -> Tuple[Optional[bytes], bool]:
        """Trigger a measurement and read 7 bytes of raw data with CRC verification."""
        for attempt in range(1, self.retries + 1):
            try:
                self.bus.write_byte(0x40, self.REG_MEASURE)
            except OSError as e:
                logger.error("I2C error writing measure command (attempt %d/%d): %s", attempt, self.retries, e)
                time.sleep(self.retry_delay)
                continue

            # Wait for measurement to complete or timeout
            deadline = time.monotonic() + self.read_timeout
            while True:
                try:
                    status = self.bus.read_byte_data(0x40, self.REG_STATUS)
                except OSError as e:
                    logger.error("I2C error reading status (attempt %d/%d): %s", attempt, self.retries, e)
                    time.sleep(self.retry_delay)
                    break

                if not (status & self.STATUS_MEASURE_IN_PROGRESS):
                    break
                if time.monotonic() > deadline:
                    logger.warning("Measurement timed out (attempt %d/%d).", attempt, self.retries)
                    time.sleep(self.retry_delay)
                    break
                time.sleep(0.005)
            else:
                continue

            time.sleep(self.retry_delay)

        try:
            data = self.bus.read_i2c_block_data(0x40, self.REG_DATA, 7)
        except OSError as e:
            logger.error("I2C error reading data: %s", e)
            return None, True

        # Compute CRC over the first six bytes
        crc = self._calculate_crc8(data[:6])
        if crc != data[6]:
            logger.warning("CRC mismatch: computed 0x%02X, received 0x%02X", crc, data[6])
            return None, True

        return bytes(data), False

    @staticmethod
    def _calculate_crc8(data: bytes) -> int:
        crc = DHT20.CRC_INITIAL
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ DHT20.CRC_POLYNOMIAL) & 0xFF
                else:
                    crc = (crc << 1) & 0xFF
        return crc

    def read_retry(self) -> Tuple[Optional[float], Optional[float], bool]:
        """Read temperature and humidity with retry logic. Returns (temp, hum, crc_error)."""
        for attempt in range(1, self.retries + 1):
            raw_data, crc_error = self._read_raw_data()
            if raw_data is None:
                logger.warning("Data read failed (attempt %d/%d).", attempt, self.retries)
                time.sleep(self.retry_delay)
                continue

            if crc_error:
                logger.warning("CRC error detected (attempt %d/%d).", attempt, self.retries)
                time.sleep(self.retry_delay)
                continue

            return self._process_data(raw_data)

        logger.error("Failed to read valid data after %d retries.", self.retries)
        return None, None, True

    @staticmethod
    def _process_data(raw_data: bytes) -> Tuple[Optional[float], Optional[float], bool]:
        """Convert raw 7-byte payload to (temperature, humidity, crc_error)."""
        humidity_raw = ((raw_data[1] << 12) | (raw_data[2] << 4) | (raw_data[3] >> 4)) & 0xFFFFF
        temperature_raw = (((raw_data[3] & 0x0F) << 16) | (raw_data[4] << 8) | raw_data[5]) & 0xFFFFF

        humidity = (humidity_raw / 2**20) * 100.0
        temperature = (temperature_raw / 2**20) * 200.0 - 50.0

        return temperature, humidity, False

    def read(self) -> Tuple[Optional[float], Optional[float], bool]:
        """Read temperature and humidity once. Returns (temp, hum, crc_error)."""
        raw_data, crc_error = self._read_raw_data()
        if raw_data is None:
            return None, None, True
        if crc_error:
            return None, None, True
        return self._process_data(raw_data)

    def close(self) -> None:
        """Release the I2C bus handle."""
        if self.bus is not None and not self._closed:
            try:
                self.bus.close()
            except OSError as e:
                logger.error("Error closing I2C bus: %s", e)
            finally:
                self._closed = True
        self.bus = None

    def __del__(self):
        self.close()


def _main() -> None:
    sensor = None
    try:
        sensor = DHT20(i2c_bus=1, retries=5, retry_delay=2.0, power_on_delay=0.5, read_timeout=0.1)
        temp, hum, crc_err = sensor.read_retry()
        if crc_err:
            logger.error("Read failed due to CRC error.")
        else:
            logger.info("Temperature: %.2f C  Humidity: %.2f %%", temp, hum)
    except Exception as e:
        logger.error("Fatal error: %s", e)
    finally:
        if sensor is not None:
            sensor.close()


if __name__ == "__main__":
    _main()

