import asyncio
import json
import logging
import logging.handlers
import signal
import sys
from typing import Dict, Optional, Tuple

import gpiozero

try:
    import adafruit_dht
    import board
except ImportError:
    adafruit_dht = None
    board = None


DEFAULT_CONFIG = {
    "gpio_transmitter_pin": 17,
    "gpio_dht22_pin": 4,
    "dht22_read_interval": 60,
    "log_file": "greenhouse.log",
    "outlet_configurations": {
        "10101": {
            "1": {"name": "Outlet 1", "state": "off"},
            "2": {"name": "Outlet 2", "state": "off"},
            "3": {"name": "Outlet 3", "state": "off"},
        }
    },
}


class GreenhouseController:
    def __init__(self, config_file: str = "greenhouse_config.json"):
        self.config_file = config_file
        self.config: Dict = DEFAULT_CONFIG.copy()
        self.outlet_states: Dict[str, Dict[str, str]] = {}
        self.dht22_sensor = None
        self.transmitter = None
        self._shutdown = False
        self._tasks: list = []

        self.load_config()
        self.setup_logging()
        self.setup_gpio()
        self.setup_dht22()

    def load_config(self) -> None:
        try:
            with open(self.config_file, "r") as f:
                user_config = json.load(f)
            self.config.update(user_config)
            self.validate_config(self.config)
            logging.info("Configuration loaded successfully.")
        except FileNotFoundError:
            logging.warning("Configuration file not found. Using default configuration.")
        except json.JSONDecodeError as e:
            logging.error(f"Error decoding JSON from {self.config_file}: {e}. Using default configuration.")
        except Exception as e:
            logging.error(f"Error loading configuration: {e}. Using default configuration.")

    def validate_config(self, config: Dict) -> None:
        required_keys = ["gpio_transmitter_pin", "gpio_dht22_pin", "dht22_read_interval", "log_file", "outlet_configurations"]
        for key in required_keys:
            if key not in config:
                raise ValueError(f"Missing required config key: {key}")

    def setup_logging(self) -> None:
        log_level = getattr(logging, (self.config.get("log_level", "INFO").upper()), logging.INFO)
        log_file = self.config.get("log_file", "greenhouse.log")
        logger = logging.getLogger(__name__)
        logger.setLevel(log_level)
        logger.handlers.clear()
        handler = logging.handlers.RotatingFileHandler(
            log_file, maxBytes=1024 * 1024, backupCount=5
        )
        formatter = logging.Formatter("%(asctime)s - %(levelname)s - %(message)s")
        handler.setFormatter(formatter)
        logger.addHandler(handler)
        console = logging.StreamHandler()
        console.setFormatter(formatter)
        logger.addHandler(console)
        logging.info("Logging initialized.")

    def setup_gpio(self) -> None:
        try:
            self.transmitter = gpiozero.OutputDevice(self.config["gpio_transmitter_pin"], active_high=True, initial_value=False)
            logging.info(f"GPIO transmitter pin {self.config['gpio_transmitter_pin']} initialized.")
        except Exception as e:
            logging.error(f"Error initializing GPIO transmitter pin: {e}")
            raise

    def setup_dht22(self) -> None:
        if adafruit_dht is None or board is None:
            logging.warning("adafruit_dht or board not available. DHT22 sensor disabled.")
            return
        try:
            pin = getattr(board, f"D{self.config['gpio_dht22_pin']}")
            self.dht22_sensor = adafruit_dht.DHT22(pin, use_pulseio=False)
            logging.info(f"DHT22 sensor initialized on GPIO {self.config['gpio_dht22_pin']}.")
        except Exception as e:
            logging.error(f"Error initializing DHT22 sensor: {e}")
            self.dht22_sensor = None

    def cleanup(self) -> None:
        logging.info("Cleaning up resources...")
        for task in self._tasks:
            task.cancel()
        if self.transmitter:
            self.transmitter.close()
        if self.dht22_sensor:
            try:
                self.dht22_sensor.exit()
            except Exception:
                pass
        logging.info("Cleanup complete.")

    def signal_handler(self, signum, frame) -> None:
        logging.info(f"Signal {signum} received. Shutting down...")
        self._shutdown = True

    def transmit_code(self, code: str, retries: int = 3, delay: float = 0.1) -> bool:
        if self.transmitter is None:
            logging.error("Transmitter not initialized.")
            return False
        for attempt in range(retries):
            try:
                self.transmitter.off()
                for _ in range(3):
                    self.transmitter.on()
                    time.sleep(0.0003)
                self.transmitter.off()
                for bit in code:
                    if bit == "1":
                        self.transmitter.on()
                        time.sleep(0.0003)
                        self.transmitter.off()
                        time.sleep(0.0003)
                        self.transmitter.on()
                        time.sleep(0.0003)
                        self.transmitter.off()
                    elif bit == "0":
                        self.transmitter.on()
                        time.sleep(0.0003)
                        self.transmitter.off()
                        time.sleep(0.0003)
                        self.transmitter.off()
                        time.sleep(0.0003)
                        self.transmitter.on()
                        time.sleep(0.0003)
                        self.transmitter.off()
                    else:
                        logging.warning(f"Invalid bit in code: {bit}")
                        return False
                self.transmitter.on()
                time.sleep(0.0003)
                self.transmitter.off()
                time.sleep(0.0003)
                self.transmitter.on()
                time.sleep(0.0003)
                self.transmitter.off()
                logging.debug(f"Transmitted code: {code}")
                return True
            except Exception as e:
                logging.error(f"Error transmitting code (attempt {attempt + 1}/{retries}): {e}")
                if attempt < retries - 1:
                    time.sleep(delay)
        logging.error("Failed to transmit code after multiple retries.")
        return False

