                for _ in range(3):
                    self.transmitter.on()
                    time.sleep(0.0003)
                self.transmitter.off()
                for bit in code:
                    if bit == "1":
                        self.transmitter.on()
                        time.sleep(0.0003)
                        self.transmitter.off()
                        time.sleep(0.0003)
                        self.transmitter.on()
                        time.sleep(0.0003)
                        self.transmitter.off()
                    elif bit == "0":
                        self.transmitter.on()
                        time.sleep(0.0003)
                        self.transmitter.off()
                        time.sleep(0.0003)
                        self.transmitter.off()
                        time.sleep(0.0003)
                        self.transmitter.on()
                        time.sleep(0.0003)
                        self.transmitter.off()
                    else:
                        logging.warning(f"Invalid bit in code: {bit}")
                        return False
                self.transmitter.on()
                time.sleep(0.0003)
                self.transmitter.off()
                time.sleep(0.0003)
                self.transmitter.on()
                time.sleep(0.0003)
                self.transmitter.off()
                logging.debug(f"Transmitted code: {code}")
                return True
            except Exception as e:
                logging.error(f"Error transmitting code (attempt {attempt + 1}/{retries}): {e}")
                if attempt < retries - 1:
                    time.sleep(delay)
        logging.error("Failed to transmit code after multiple retries.")
        return False

    def control_outlet(self, system_code: str, unit_code: str, state: str) -> bool:
        if system_code not in self.config["outlet_configurations"]:
            logging.error(f"Invalid system code: {system_code}")
