            logging.error(f"Invalid state: {state}. Must be 'on' or 'off'.")
            return False
        outlet_config = self.config["outlet_configurations"][system_code][unit_code]
        code = f"{system_code}{unit_code}{'1' if state == 'on' else '0'}"
        logging.info(f"Control outlet {outlet_config['name']} (code {code}) to state: {state}")
