import time
import logging
from typing import Optional, Tuple

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")


class DHT20:
    """Driver for the DHT20 I2C humidity/temperature sensor on Raspberry Pi."""

    I2C_BUS = 1
    I2C_ADDR = 0x60
    REG_STATUS = 0x71
    REG_MEASURE = 0xAC
    POLYNOMIAL = 0x31
    INITIAL_CRC = 0xFF

    def __init__(self, bus: int = I2C_BUS, addr: int = I2C_ADDR) -> None:
        self.addr = addr
        self.bus_num = bus
        self.bus: Optional[object] = None
        try:
            import smbus2 as smbus
            self.bus = smbus.SMBus(bus)
            logging.info("Opened I2C bus %d", bus)
        except Exception as exc:
            logging.error("Failed to open I2C bus %d: %s", bus, exc)
            self.bus = None
            return

        if not self._verify_sensor():
            logging.error("DHT20 not detected at address 0x%02X on bus %d", addr, bus)
            self.close()
            self.bus = None

    def _verify_sensor(self) -> bool:
        if self.bus is None:
            return False
        try:
            status = self.bus.read_byte_data(self.addr, self.REG_STATUS)
            logging.info("DHT20 status register = 0x%02X", status)
            return True
        except Exception as exc:
            logging.error("Error reading DHT20 status: %s", exc)
            return False

    def _read_register(self, reg: int, length: int) -> Optional[bytes]:
        if self.bus is None:
            logging.error("I2C bus not initialized")
            return None
        try:
            return self.bus.read_i2c_block_data(self.addr, reg, length)
        except Exception as exc:
            logging.error("I2C read error at register 0x%02X: %s", reg, exc)
            return None

    def measure(self) -> Tuple[Optional[float], Optional[float], bool]:
        if self.bus is None:
            logging.error("Cannot measure: I2C bus not initialized")
            return None, None, True

        data = self._read_register(self.REG_MEASURE, 7)
        if data is None or len(data) < 7:
            logging.error("Failed to initiate measurement (got %s bytes)", data)
            return None, None, True

        start = time.monotonic()
        deadline = start + 0.1
        while True:
            status = self._read_register(self.REG_STATUS, 1)
            if status is None or len(status) < 1:
                logging.error("Failed to read status register")
                return None, None, True
            if (status[0] & 0x80) != 0:
                break
            if time.monotonic() >= deadline:
                logging.error("Measurement timed out (status 0x%02X)", status[0])
                return None, None, True
            time.sleep(0.01)

        raw = self._read_register(self.REG_MEASURE, 7)
        if raw is None or len(raw) < 7:
            logging.error("Failed to read measurement data")
            return None, None, True

        crc_error = self._calculate_crc(raw) != raw[6]
        if crc_error:
            logging.warning("CRC mismatch: calculated 0x%02X, received 0x%02X",
                            self._calculate_crc(raw), raw[6])

        humidity_raw = ((raw[1] << 12) | (raw[2] << 4) | (raw[3] >> 4)) & 0xFFFFF
        temperature_raw = (((raw[3] & 0x0F) << 16) | (raw[4] << 8) | raw[5]) & 0xFFFFF

        humidity = (humidity_raw / 0x100000) * 100.0
        temperature = (temperature_raw / 0x100000) * 200.0 - 50.0

        return temperature, humidity, crc_error

    @staticmethod
    def _calculate_crc(data: bytes) -> int:
        crc = DHT20.INITIAL_CRC
        for byte in data[:6]:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ DHT20.POLYNOMIAL) & 0xFF
                else:
                    crc = (crc << 1) & 0xFF
        return crc

    def close(self) -> None:
        if self.bus is not None:
            try:
                self.bus.close()
                logging.info("I2C bus closed")
            except Exception as exc:
                logging.error("Error closing I2C bus: %s", exc)
            finally:
                self.bus = None


_sensor: Optional[DHT20] = None


def _signal_handler(signum, frame):
    logging.info("Signal %d received, shutting down", signum)
    if _sensor is not None:
        _sensor.close()
    sys.exit(0)


if __name__ == "__main__":
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    _sensor = DHT20(bus=1, addr=0x60)
    if _sensor.bus is None:
        sys.exit(1)

    try:
        temp, hum, crc = _sensor.measure()
        if crc:
            print("Error: CRC mismatch")
        else:
            print(f"Temperature: {temp:.2f} C  Humidity: {hum:.2f} %")
    finally:
        _sensor.close()

