import time
import signal
import sys
import board
import busio
import adafruit_tca9548a
import adafruit_bme280
import adafruit_tsl2591

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_i2c():
    """Initialize the I2C bus on board.SCL / board.SDA."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        # Probe the bus to confirm the sensors are present
        while not i2c_bus.try_lock():
            pass
        try:
            devices = i2c_bus.scan()
        finally:
            i2c_bus.unlock()

        if 0x76 not in devices:
            print("Error: TCA9548A multiplexer not found at I2C address 0x76.")
            return None
        if 0x73 not in devices:
            print("Error: BME280 sensor not found at I2C address 0x73.")
            return None
        if 0x29 not in devices:
            print("Error: TSL2591 sensor not found at I2C address 0x29.")
            return None
        return i2c_bus
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None

def initialize_multiplexer(i2c_bus):
    """Initialize the TCA9548A I2C multiplexer."""
    try:
        return adafruit_tca9548a.TCA9548A(i2c_bus)
    except Exception as e:
        print(f"Error initializing TCA9548A multiplexer: {e}")
        return None

def initialize_bme280(multiplexer):
    """Initialize the BME280 sensor via the multiplexer."""
    try:
        return adafruit_bme280.Adafruit_BME280_I2C(multiplexer[0], address=0x76)
    except Exception as e:
        print(f"Error initializing BME280 sensor: {e}")
        return None

def initialize_tsl2591(multiplexer):
    """Initialize the TSL2591 sensor via the multiplexer."""
    try:
        return adafruit_tsl2591.TSL2591(i2c_bus=multiplexer[0])
    except Exception as e:
        print(f"Error initializing TSL2591 sensor: {e}")
        return None

def read_sensor_data(bme280_sensor, tsl2591_sensor):
    """Read data from BME280 and TSL2591 sensors, handling transient errors."""
