#!/usr/bin/env python3
"""
Hydroponics controller: relay-driven water pump on BCM 17, simulated DHT11
temperature sensor on BCM 4 (fixed 25.0 °C), TCP socket on port 12345
accepting only 192.168.1.100, with graceful shutdown and GPIO cleanup.
"""

import argparse
import json
import logging
import signal
import socket
import sys

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    GPIO = None


class HydroponicsController:
    """Manage a relay-driven pump and a simulated DHT11 temperature sensor."""

    def __init__(self, relay_pin, dht_pin, port, allowed_ip, log_file):
        self.relay_pin = relay_pin
        self.dht_pin = dht_pin
        self.port = port
        self.allowed_ip = allowed_ip
        self.log_file = log_file
        self.pump_state = False
        self.server_socket = None
        self.running = True

        logging.basicConfig(
            filename=self.log_file,
            level=logging.INFO,
            format="%(asctime)s - %(levelname)s - %(message)s",
        )
        logging.info("Hydroponics controller starting.")

        if GPIO is None:
            logging.warning("RPi.GPIO not available; running in mock mode.")
        else:
            try:
                GPIO.setmode(GPIO.BCM)
                GPIO.setup(self.relay_pin, GPIO.OUT, initial=GPIO.LOW)
                logging.info(f"GPIO pin {self.relay_pin} configured as output (initial LOW).")
            except Exception as e:
                logging.error(f"GPIO setup failed: {e}")
                raise

    def _cleanup(self):
        """Release GPIO resources and close the socket."""
        if GPIO is not None:
            try:
                GPIO.output(self.relay_pin, GPIO.LOW)
                GPIO.cleanup()
                logging.info("GPIO cleaned up.")
            except Exception as e:
                logging.error(f"GPIO cleanup error: {e}")
        if self.server_socket is not None:
            try:
                self.server_socket.close()
                logging.info("Server socket closed.")
            except Exception as e:
                logging.error(f"Socket close error: {e}")

    def _signal_handler(self, signum, frame):
        """Handle SIGINT/SIGTERM for graceful shutdown."""
        logging.info(f"Received signal {signum}; shutting down.")
        self.running = False

    def _get_temperature(self):
        """Return the simulated DHT11 temperature (25.0 °C)."""
        return 25.0

    def _set_pump(self, state):
        """Set the pump relay state and log the change."""
        if GPIO is not None:
            try:
                GPIO.output(self.relay_pin, GPIO.HIGH if state else GPIO.LOW)
            except Exception as e:
                logging.error(f"GPIO output error: {e}")
                return False
        self.pump_state = state
        logging.info(f"Pump turned {'ON' if state else 'OFF'}.")
        return True

    def _handle_client(self, client_socket):
        """Process a single client connection."""
        try:
            data = client_socket.recv(1024).decode("utf-8", errors="ignore").strip()
            if not data:
                logging.warning("Empty request from client.")
                return

            try:
                command = json.loads(data)
            except json.JSONDecodeError:
                logging.warning("Invalid JSON received.")
                return

            if not isinstance(command, dict) or "command" not in command:
                logging.warning("Malformed command: missing 'command' key.")
                return

            cmd = command["command"]

            if cmd == "pump_on":
                self._set_pump(True)
            elif cmd == "pump_off":
                self._set_pump(False)
            elif cmd == "get_status":
                status = {"pump_state": "on" if self.pump_state else "off", "temperature": self._get_temperature()}
                response = json.dumps(status)
                client_socket.sendall(response.encode("utf-8"))
                logging.info(f"Status sent to client: {response}")
            else:
                logging.warning(f"Unknown command: {cmd}")

        except socket.timeout:
            logging.warning("Socket timeout from client.")
        except Exception as e:
            logging.error(f"Error handling client: {e}")
        finally:
            try:
                client_socket.close()
            except Exception:
                pass

    def run(self):
        """Start the TCP server and accept connections."""
        signal.signal(signal.SIGINT, self._signal_handler)
        signal.signal(signal.SIGTERM, self._signal_handler)

        try:
            self.server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            self.server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            self.server_socket.bind(("", self.port))
            self.server_socket.listen(5)
            self.server_socket.settimeout(1.0)
            logging.info(f"Listening on port {self.port} for {self.allowed_ip}.")

            while self.running:
                try:
                    client_socket, client_address = self.server_socket.accept()
                    logging.info(f"Connection from {client_address}.")
                    if client_address[0] != self.allowed_ip:
                        logging.warning(f"Unauthorized connection from {client_address[0]}.")
                        try:
                            client_socket.sendall(b"Unauthorized.\n")
                        except Exception:
                            pass
                        client_socket.close()
                        continue
                    self._handle_client(client_socket)
                except socket.timeout:
                    continue
                except Exception as e:
                    if self.running:
                        logging.error(f"Accept error: {e}")
        except Exception as e:
            logging.error(f"Server error: {e}")
        finally:
            self._cleanup()
            logging.info("Hydroponics controller stopped.")


def main():
    parser = argparse.ArgumentParser(description="Hydroponics controller.")
    parser.add_argument("--relay_pin", type=int, default=17, help="GPIO BCM pin for relay (default: 17)")
    parser.add_argument("--dht_pin", type=int, default=4, help="GPIO BCM pin for DHT11 (default: 4)")
    parser.add_argument("--port", type=int, default=12345, help="Listening port (default: 12345)")
    parser.add_argument("--allowed_ip", type=str, default="192.168.1.100", help="Allowed client IP (default: 192.168.1.100)")
    parser.add_argument("--log_file", type=str, default="hydroponics.log", help="Log file path (default: hydroponics.log)")
    args = parser.parse_args()

    try:
        controller = HydroponicsController(args.relay_pin, args.dht_pin, args.port, args.allowed_ip, args.log_file)
        controller.run()
    except Exception as e:
        logging.error(f"Fatal error: {e}")
        sys.exit(1)


if __name__ == "__main__":
    main()

