import time
import sys
from typing import Optional

from gpiozero import CPUTemperature


def read_cpu_temperature() -> Optional[float]:
    """
    Read the CPU temperature from the on-board sensor.

    Returns the temperature in °C, or None if the sensor is unavailable
    or a read error occurs.
    """
    try:
        # Lazily create the CPUTemperature object so that a missing
        # thermal file (e.g. on a non-Pi or with thermal disabled) is
        # reported as a per-read error, not a start-up failure.
        cpu = CPUTemperature()
        return float(cpu.temperature)
    except FileNotFoundError:
        print("Error: CPU temperature sensor not found (thermal file missing).")
        return None
    except Exception as exc:
        print(f"Error reading CPU temperature: {exc}")
        return None


def main() -> int:
    try:
        while True:
            temperature = read_cpu_temperature()
            if temperature is not None:
                print(f"CPU Temperature: {temperature:.2f} °C")
            time.sleep(5)
    except KeyboardInterrupt:
        print("Program terminated")
        return 0


if __name__ == "__main__":
    sys.exit(main())

