import time
import logging
import random
import signal
import sys

try:
    from gpiozero import AngularServo
    from gpiozero.pins.pigpio import PiGPIOFactory
    _GPIOZERO_AVAILABLE = True
except Exception:
    _GPIOZERO_AVAILABLE = False

# Constants
SERVO_PIN_1 = 17
SERVO_PIN_2 = 18
TEMP_MIN = 15
TEMP_MAX = 35
TEMP_STEP = 5
SERVO_STEP = 5
SERVO_MIN_ANGLE = 0
SERVO_MAX_ANGLE = 180
PWM_FREQUENCY = 50
MOVEMENT_DELAY = 0.1
LOG_FILE = 'greenhouse_vent.log'
FAILURE_RATE = 0.10

# Logging setup
logging.basicConfig(
    filename=LOG_FILE,
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# Global state
servo1 = None
servo2 = None
pwm1 = None
pwm2 = None
using_library_api = False
failure_count = 0
max_failures = 3


def initialize_gpio():
    """Initialize GPIO and PWM using gpiozero or the library's API."""
    global servo1, servo2, pwm1, pwm2, using_library_api

    if not _GPIOZERO_AVAILABLE:
        logging.error("gpiozero library not available; using library API fallback.")
        using_library_api = True
        return

    try:
        factory = PiGPIOFactory()
        servo1 = AngularServo(
            SERVO_PIN_1,
            initial_angle=SERVO_MIN_ANGLE,
            min_angle=SERVO_MIN_ANGLE,
            max_angle=SERVO_MAX_ANGLE,
            pin_factory=factory
        )
        servo2 = AngularServo(
            SERVO_PIN_2,
            initial_angle=SERVO_MIN_ANGLE,
            min_angle=SERVO_MIN_ANGLE,
            max_angle=SERVO_MAX_ANGLE,
            pin_factory=factory
        )
        logging.info("GPIO initialized with gpiozero (pigpio backend).")
    except Exception as e:
        logging.error(f"gpiozero initialization failed: {e}. Falling back to library API.")
        using_library_api = True


def initialize_pwm():
    """Initialize PWM for the library API."""
    global pwm1, pwm2
    if using_library_api:
        try:
            import RPi.GPIO as GPIO
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(SERVO_PIN_1, GPIO.OUT)
            GPIO.setup(SERVO_PIN_2, GPIO.OUT)
            pwm1 = GPIO.PWM(SERVO_PIN_1, PWM_FREQUENCY)
            pwm2 = GPIO.PWM(SERVO_PIN_2, PWM_FREQUENCY)
            pwm1.start(0)
            pwm2.start(0)
            logging.info("PWM initialized via RPi.GPIO.")
        except Exception as e:
            logging.error(f"PWM initialization failed: {e}")
            raise


def get_simulated_temperature():
    """Generates a random temperature between TEMP_MIN and TEMP_MAX."""
    base_temp = random.uniform(TEMP_MIN, TEMP_MAX)
    return base_temp + random.uniform(-TEMP_STEP / 2, TEMP_STEP / 2)


def calculate_servo_angle(temperature):
    """Calculates the servo angle based on the temperature."""
    if temperature < 20:
        return 0
    elif 20 <= temperature < 25:
        return 45
    elif 25 <= temperature < 30:
        return 90
    elif 30 <= temperature < 35:
        return 135
    else:
        return 180


def move_servo(servo, target_angle, current_angle):
    """Moves the servo to the target angle in 5-degree steps."""
    global failure_count
    if using_library_api:
        try:
            if servo == servo1:
                pwm = pwm1
            else:
                pwm = pwm2

            if random.random() < FAILURE_RATE:
                raise Exception("Simulated library API failure.")

            step = SERVO_STEP if target_angle > current_angle else -SERVO_STEP
            angle = current_angle
            while True:
                angle += step
                if (step > 0 and angle >= target_angle) or (step < 0 and angle <= target_angle):
                    break
                pwm.ChangeDutyCycle(angle)
                time.sleep(MOVEMENT_DELAY)
            pwm.ChangeDutyCycle(target_angle)
            time.sleep(MOVEMENT_DELAY)
            failure_count = 0
            logging.info(f"Servo moved to {target_angle} degrees.")
        except Exception as e:
            logging.error(f"Servo movement failed: {e}")
            failure_count += 1
            if failure_count >= max_failures:
                logging.warning("Max failures reached. Switching to gpiozero API.")
                using_library_api = False
                initialize_gpio()
                if servo1 is not None:
                    servo1.angle = target_angle
                if servo2 is not None:
                    servo2.angle = target_angle
                failure_count = 0
            else:
                if servo == servo1:
                    servo1.angle = current_angle
                else:
                    servo2.angle = current_angle
