def cleanup():
    """Clean up GPIO and PWM resources."""
    global servo1, servo2, pwm1, pwm2
    logging.info("Cleaning up GPIO and PWM...")
    try:
        if using_library_api:
            if pwm1 is not None:
                pwm1.stop()
            if pwm2 is not None:
