import time
import logging
import signal
import sys
from typing import List, Optional

try:
    import board
    import busio
    import adafruit_bmp280
except ImportError as exc:
    logging.error("Missing dependency: %s", exc)
    sys.exit(1)

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

DEFAULT_SEA_LEVEL_PRESSURE = 1013.25
I2C_SDA_PIN = board.D4
I2C_SCL_PIN = board.D5
NUM_SAMPLES = 100

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


class CalibrationError(Exception):
    pass


def initialize_i2c() -> Optional[busio.I2C]:
    try:
        i2c = busio.I2C(sda=I2C_SDA_PIN, scl=I2C_SCL_PIN)
        while not i2c.try_lock():
            time.sleep(0.01)
        i2c.unlock()
        return i2c
    except (OSError, ValueError, RuntimeError) as e:
        logging.error("I2C initialization failed: %s", e)
        return None


def initialize_sensor(i2c: busio.I2C) -> Optional["adafruit_bmp280.Adafruit_BMP280_I2C"]:
    try:
        sensor = adafruit_bmp280.Adafruit_BMP280_I2C(i2c, address=0x76)
        sensor.sea_level_pressure = DEFAULT_SEA_LEVEL_PRESSURE
        return sensor
    except (OSError, ValueError, RuntimeError) as e:
        logging.error("BMP280 initialization failed: %s", e)
        return None


def read_pressure(sensor: "adafruit_bmp280.Adafruit_BMP280_I2C") -> float:
    try:
        return sensor.pressure
    except (OSError, RuntimeError) as e:
        logging.error("Error reading pressure: %s", e)
        raise


def get_baseline_pressure(sensor: "adafruit_bmp280.Adafruit_BMP280_I2C", num_samples: int = NUM_SAMPLES) -> float:
    pressures: List[float] = []
    for i in range(num_samples):
        try:
            pressures.append(read_pressure(sensor))
        except (OSError, RuntimeError):
            logging.warning("Sample %d/%d failed; retrying...", i + 1, num_samples)
            time.sleep(0.1)
        time.sleep(0.05)

    if not pressures:
        raise CalibrationError("No pressure samples collected.")

    pressures.sort()
    discard_count = int(num_samples * 0.25)
    valid_pressures = pressures[discard_count:-discard_count or None]

    if not valid_pressures:
        raise CalibrationError("No valid pressure samples after trimming.")

    return sum(valid_pressures) / len(valid_pressures)


def main() -> None:
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    i2c = initialize_i2c()
    if i2c is None:
        sys.exit(1)

    sensor = initialize_sensor(i2c)
    if sensor is None:
        i2c.deinit()
        sys.exit(1)

    try:
        baseline = get_baseline_pressure(sensor)
        sensor.sea_level_pressure = baseline
        logging.info("Baseline pressure established: %.2f hPa", baseline)

        while _running:
            try:
                altitude = sensor.altitude
                print(f"Altitude: {altitude:.2f} meters")
            except (OSError, RuntimeError) as e:
                logging.error("Error reading altitude: %s", e)
            time.sleep(1)

    except CalibrationError as e:
        logging.error("Calibration failed: %s", e)
        logging.warning("Falling back to default sea level pressure: %.2f hPa", DEFAULT_SEA_LEVEL_PRESSURE)
        try:
            sensor.sea_level_pressure = DEFAULT_SEA_LEVEL_PRESSURE
        except Exception:
            pass
    except Exception as e:
        logging.error("Unexpected error: %s", e)
    finally:
        try:
            sensor.sea_level_pressure = DEFAULT_SEA_LEVEL_PRESSURE
        except Exception:
            pass
        try:
            i2c.deinit()
        except Exception:
            pass
        logging.info("Resources released. Exiting.")


if __name__ == "__main__":
    main()

