import adafruit_tca9548a
import adafruit_bme280
import adafruit_tsl2591


def main():
    # Initialize I2C bus on GPIO2 (SDA) and GPIO3 (SCL)
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return

    # Initialize the TCA9548A I2C multiplexer
    try:
        i2c_multiplexer = adafruit_tca9548a.TCA9548A(i2c_bus)
    except Exception as e:
        print(f"Error initializing TCA9548A multiplexer: {e}")
        return

    # Initialize the BME280 sensor (I2C address 0x76)
    try:
        bme280_sensor = adafruit_bme280.Adafruit_BME280_I2C(
            i2c_multiplexer[0], address=0x76
        )
    except Exception as e:
        print(f"Error initializing BME280 sensor: {e}")
        return

    # Initialize the TSL2591 light sensor (I2C address 0x29)
    try:
        tsl2591_sensor = adafruit_tsl2591.TSL2591(i2c_multiplexer[1])
    except Exception as e:
        print(f"Error initializing TSL2591 sensor: {e}")
        return

    print("Starting sensor readings. Press Ctrl+C to exit.")

    try:
        while True:
            # Read temperature and humidity from the BME280 sensor
            try:
                temperature = bme280_sensor.temperature
                humidity = bme280_sensor.humidity
            except Exception as e:
                print(f"Error reading BME280: {e}")
                temperature = None
                humidity = None

            # Read light level from the TSL2591 sensor
            try:
                light_level = tsl2591_sensor.lux
            except Exception as e:
                print(f"Error reading TSL2591: {e}")
                light_level = None

            # Print the readings to the console
            print(
                f"Temperature: {temperature:.2f} C, "
                f"Humidity: {humidity:.2f} %, "
                f"Light: {light_level:.2f} lux"
            )

            # Wait for 2 seconds before the next reading
            time.sleep(2)

    except KeyboardInterrupt:
        print("\nExiting program.")


if __name__ == "__main__":
    main()

