import sys
import time
import signal
from datetime import datetime

try:
    import serial
except ImportError:
    print("Error: pyserial is not installed. Install with: pip install pyserial", file=sys.stderr)
    sys.exit(1)

SERIAL_PORT = "/dev/ttyACM0"
BAUD_RATE = 115200
READ_TIMEOUT = 2.0
LOG_FILE = "temperature_log.csv"

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def initialize_uart(port, baudrate, timeout):
    try:
        uart = serial.Serial(
            port=port,
            baudrate=baudrate,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=timeout,
            xonxoff=False,
            rtscts=False,
            dsrdtr=False,
        )
        if not uart.is_open:
            print(f"Error: failed to open {port}", file=sys.stderr)
            return None
        return uart
    except serial.SerialException as e:
        print(f"Error: cannot open {port}: {e}", file=sys.stderr)
        return None
    except OSError as e:
        print(f"Error: device not available {port}: {e}", file=sys.stderr)
        return None

def read_temperature_data(uart):
    try:
        raw = uart.readline()
        if not raw:
            return None
        line = raw.decode("ascii", errors="replace").strip()
        if not line:
            return None
        return line
    except serial.SerialException as e:
        print(f"Warning: serial read error: {e}", file=sys.stderr)
        return None

def convert_to_fahrenheit(celsius):
    try:
        fahrenheit = (celsius * 9.0 / 5.0) + 32.0
        return fahrenheit
    except (TypeError, ValueError) as e:
        print(f"Warning: invalid temperature value: {e}", file=sys.stderr)
        return None

def log_temperature(log_file, timestamp, celsius, fahrenheit):
    try:
        with open(log_file, "a", encoding="utf-8") as file:
            file.write(f"{timestamp},{celsius},{fahrenheit}\n")
    except OSError as e:
        print(f"Warning: failed to write log: {e}", file=sys.stderr)

def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    uart = initialize_uart(SERIAL_PORT, BAUD_RATE, READ_TIMEOUT)
    if uart is None:
        sys.exit(1)

    try:
        try:
            with open(LOG_FILE, "x", encoding="utf-8") as file:
                file.write("Timestamp,Celsius,Fahrenheit\n")
