import RPi.GPIO as GPIO
import time
import sys

DHT_PIN = 4
RETRY_COUNT = 3
RETRY_DELAY = 2
SUCCESS_DELAY = 5

def setup_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(DHT_PIN, GPIO.OUT, initial=GPIO.HIGH)

def read_dht22():
    GPIO.output(DHT_PIN, GPIO.LOW)
    time.sleep(0.018)
    GPIO.setup(DHT_PIN, GPIO.IN)

    timeout = time.time() + 0.0002
    while GPIO.input(DHT_PIN) == GPIO.HIGH:
        if time.time() > timeout:
            raise TimeoutError("Sensor not responding (stuck high)")

    timeout = time.time() + 0.0002
    while GPIO.input(DHT_PIN) == GPIO.LOW:
        if time.time() > timeout:
            raise TimeoutError("Sensor not responding (stuck low)")

    data = []
    for _ in range(40):
        timeout = time.time() + 0.0002
        while GPIO.input(DHT_PIN) == GPIO.LOW:
            if time.time() > timeout:
                raise TimeoutError("Bit read timeout (low)")
        start = time.time()
        timeout = time.time() + 0.0002
        while GPIO.input(DHT_PIN) == GPIO.HIGH:
            if time.time() > timeout:
                raise TimeoutError("Bit read timeout (high)")
        duration = time.time() - start
        data.append(1 if duration > 0.00005 else 0)

    humidity_int = 0
    humidity_dec = 0
    temp_int = 0
    temp_dec = 0
    checksum = 0

    for i in range(8):
        humidity_int = (humidity_int << 1) | data[i]
    for i in range(8, 16):
        humidity_dec = (humidity_dec << 1) | data[i]
    for i in range(16, 24):
        temp_int = (temp_int << 1) | data[i]
    for i in range(24, 32):
        temp_dec = (temp_dec << 1) | data[i]
    for i in range(32, 40):
        checksum = (checksum << 1) | data[i]

    calc_checksum = (humidity_int + humidity_dec + temp_int + temp_dec) & 0xFF
    if calc_checksum != checksum:
        raise ValueError(f"Checksum mismatch: got {checksum}, expected {calc_checksum}")

    humidity = humidity_int + humidity_dec / 10.0
    temperature = temp_int + temp_dec / 10.0
    return temperature, humidity

def cleanup():
    GPIO.cleanup()

def main():
    setup_gpio()
    consecutive_failures = 0
    try:
        while True:
            try:
                temperature, humidity = read_dht22()
                print(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")
                consecutive_failures = 0
                time.sleep(SUCCESS_DELAY)
            except (TimeoutError, ValueError) as e:
                print(f"Error reading DHT22: {e}")
                consecutive_failures += 1
                if consecutive_failures >= RETRY_COUNT:
                    print("Failed to read DHT22 after multiple retries. Retrying in 5 seconds...")
                    time.sleep(5)
                    consecutive_failures = 0
                else:
                    time.sleep(RETRY_DELAY)
            except Exception as e:
                print(f"Unexpected error: {e}")
                consecutive_failures = 0
                time.sleep(5)
    except KeyboardInterrupt:
        print("\nExiting program.")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

