import time
import datetime
import json
import logging
import random
import signal
import sys
import urllib.request
import urllib.error

try:
    import board
    import adafruit_dht
except ImportError:
    board = None
    adafruit_dht = None

CONFIG_FILE = "config.json"

DEFAULT_CONFIG = {
    "webhook_url": "http://example.com/webhook",
    "sensor_pin": 4,
    "logging_level": "INFO",
    "temperature_min": -40,
    "temperature_max": 80,
    "humidity_min": 0,
    "humidity_max": 100,
    "moving_average_window": 5,
    "retry_delay_base": 1,
    "retry_delay_multiplier": 2,
    "max_retries": 3,
    "sensor_pause_duration": 300,
    "sensor_read_interval": 60,
}

running = True


def load_config(config_file):
    try:
        with open(config_file, "r") as f:
            config = json.load(f)
        merged = DEFAULT_CONFIG.copy()
        merged.update(config)
        return merged
    except FileNotFoundError:
        logging.warning(f"Configuration file '{config_file}' not found. Using defaults.")
        return DEFAULT_CONFIG.copy()
    except json.JSONDecodeError as e:
        logging.error(f"Error decoding JSON from '{config_file}': {e}. Using defaults.")
        return DEFAULT_CONFIG.copy()


def setup_logging(level_name):
    numeric_level = getattr(logging, level_name.upper(), None)
    if not isinstance(numeric_level, int):
        raise ValueError(f"Invalid log level: {level_name}")
    logging.basicConfig(
        level=numeric_level,
        format="%(asctime)s - %(levelname)s - %(message)s",
    )


def read_dht22(sensor):
    try:
        temperature = sensor.temperature
        humidity = sensor.humidity
        if temperature is None or humidity is None:
            raise RuntimeError("Sensor returned None for temperature or humidity.")
        return temperature, humidity
    except RuntimeError as e:
        logging.error(f"DHT22 read error: {e}")
        return None, None
    except Exception as e:
        logging.error(f"Unexpected DHT22 error: {e}")
        return None, None


def validate_data(temperature, humidity, config):
    if not (config["temperature_min"] <= temperature <= config["temperature_max"]):
        logging.warning(f"Temperature {temperature:.1f}°C out of range.")
        return False
    if not (config["humidity_min"] <= humidity <= config["humidity_max"]):
        logging.warning(f"Humidity {humidity:.1f}% out of range.")
        return False
    return True


def send_webhook(data, config):
    payload = json.dumps(data).encode("utf-8")
    url = config["webhook_url"]
    for attempt in range(1, config["max_retries"] + 1):
        try:
            req = urllib.request.Request(
                url, data=payload, headers={"Content-Type": "application/json"}
            )
            with urllib.request.urlopen(req, timeout=10) as response:
                if 200 <= response.status < 300:
                    logging.info(f"Webhook sent successfully (attempt {attempt}).")
                    return True
                else:
                    logging.error(
                        f"Webhook returned status {response.status} (attempt {attempt})."
                    )
        except urllib.error.URLError as e:
            logging.error(f"Network error sending webhook (attempt {attempt}): {e}")
        except Exception as e:
            logging.error(f"Unexpected error sending webhook (attempt {attempt}): {e}")

        if attempt < config["max_retries"]:
            delay = config["retry_delay_base"] * (
                config["retry_delay_multiplier"] ** (attempt - 1)
            )
            logging.info(f"Retrying in {delay} seconds...")
            time.sleep(delay)

    logging.error("Failed to send webhook after max retries.")
    return False


def signal_handler(signum, frame):
    global running
    logging.info(f"Received signal {signum}, shutting down...")
    running = False


def main():
    global running

    config = load_config(CONFIG_FILE)
    setup_logging(config["logging_level"])

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    sensor = None
    if adafruit_dht and board:
        try:
            pin = getattr(board, f"D{config['sensor_pin']}")
            sensor = adafruit_dht.DHT22(pin, use_pulseio=False)
            logging.info(f"DHT22 initialized on BCM pin {config['sensor_pin']}.")
        except Exception as e:
            logging.error(f"Failed to initialize DHT22: {e}")
            sensor = None
    else:
        logging.warning("adafruit_dht or board not available; running in simulation mode.")

    temperature_readings = []
    last_successful_send = time.time()
    sensor_paused_until = 0.0

    try:
        while running:
            now = time.time()

            if sensor_paused_until > now:
                remaining = sensor_paused_until - now
                logging.info(f"Sensor paused for {remaining:.0f}s. Retrying in {remaining:.0f}s...")
                time.sleep(remaining)
                continue

            if sensor is not None:
                temperature, humidity = read_dht22(sensor)
            else:
                temperature = random.uniform(20, 30)
                humidity = random.uniform(60, 80)
                logging.info(
                    f"Simulated reading: {temperature:.1f}°C, {humidity:.1f}%"
                )

            if temperature is not None and humidity is not None:
                if validate_data(temperature, humidity, config):
                    temperature_readings.append(temperature)
                    if len(temperature_readings) > config["moving_average_window"]:
                        temperature_readings.pop(0)

                    avg_temp = sum(temperature_readings) / len(temperature_readings)
                    data = {
                        "timestamp": datetime.datetime.now().isoformat(),
                        "temperature": round(avg_temp, 1),
                        "humidity": round(humidity, 1),
                    }

                    if send_webhook(data, config):
                        last_successful_send = now
                    else:
                        logging.warning(
                            "Webhook failed. Pausing sensor for "
                            f"{config['sensor_pause_duration']}s."
                        )
                        sensor_paused_until = now + config["sensor_pause_duration"]
                else:
                    logging.warning("Invalid sensor data. Skipping webhook.")
            else:
                logging.warning("Failed to read sensor data. Skipping webhook.")

            for _ in range(config["sensor_read_interval"]):
                if not running:
                    break
                time.sleep(1)

    finally:
        if sensor is not None:
            try:
                sensor.exit()
            except Exception:
                pass
        logging.info("Program terminated.")


if __name__ == "__main__":
    main()

