import matplotlib.animation as animation
import serial
import threading
import queue
import time
import sys

SERIAL_PORT = '/dev/ttyS0'
BAUD_RATE = 9600
TIMEOUT = 1
FRAME_ROWS = 24
FRAME_COLS = 32
EXPECTED_VALUES = FRAME_ROWS * FRAME_COLS


def parse_thermal_frame(raw_line):
    """Parse a comma-separated ASCII line into a 24x32 numpy array of floats."""
    if not raw_line:
        return None
    text = raw_line.decode('ascii', errors='replace').strip()
    if not text:
        return None
    try:
        values = [float(tok) for tok in text.split(',')]
    except ValueError:
        return None
    if len(values) != EXPECTED_VALUES:
        return None
    return np.array(values, dtype=np.float32).reshape((FRAME_ROWS, FRAME_COLS))


def thermal_reader_loop(sensor, data_queue, stop_event):
    """Continuously read thermal frames from the sensor and enqueue them."""
    while not stop_event.is_set():
        try:
            raw_line = sensor.readline()
            if not raw_line:
                continue
            frame = parse_thermal_frame(raw_line)
            if frame is not None:
                data_queue.put(frame)
        except serial.SerialException as e:
            if not stop_event.is_set():
                print(f"Serial read error: {e}", file=sys.stderr)
                break
        except Exception as e:
            if not stop_event.is_set():
                print(f"Unexpected read error: {e}", file=sys.stderr)
                break


def main():
    stop_event = threading.Event()
    data_queue = queue.Queue()

    # Initialize the sensor via the library’s API
    try:
        sensor = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
