import time
import signal
import sys
import board
import adafruit_dht

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def read_dht22(sensor):
    """
    Reads temperature and humidity from the DHT22 sensor.
    Returns (temperature, humidity) or (None, None) on failure.
    """
    for attempt in range(2):
        try:
            temperature = sensor.temperature
            humidity = sensor.humidity
            if temperature is not None and humidity is not None:
                return temperature, humidity
        except RuntimeError as e:
            # DHT22 commonly throws RuntimeError on checksum or timing errors
            print(f"Read error (attempt {attempt + 1}/2): {e}")
        except Exception as e:
            print(f"Unexpected error (attempt {attempt + 1}/2): {e}")
        time.sleep(0.1)
    return None, None

def main():
    global _running

    # Register signal handler for clean Ctrl+C exit
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # Initialize the DHT22 sensor on BCM pin 22 (board.D22)
    # A short delay is required after power-up to let the sensor stabilize
    try:
        sensor = adafruit_dht.DHT22(board.D22, use_pulseio=False)
    except Exception as e:
        print(f"Failed to initialize DHT22 sensor: {e}")
        sys.exit(1)

    time.sleep(1)  # Allow sensor to stabilize after initialization

    try:
        while _running:
            temperature, humidity = read_dht22(sensor)

            if temperature is not None and humidity is not None:
                print(f"Temperature: {temperature:.1f} C")
                print(f"Humidity: {humidity:.1f} %")
            else:
                print("Failed to read from DHT22 sensor.")

            # Sleep in small increments to allow signal handler to interrupt promptly
            for _ in range(30):
                if not _running:
                    break
                time.sleep(0.1)

    finally:
        # Clean resource release on all exit paths
        try:
            sensor.exit()
        except Exception:
            pass
        print("\nProgram terminated. Resources released.")

if __name__ == "__main__":
    main()

