import time
import signal
import sys
import board
import adafruit_dht

# Global sensor handle so the signal handler can release it.
_sensor = None

def _cleanup():
    """Release the DHT11 sensor if it was initialized."""
    global _sensor
    if _sensor is not None:
        try:
            _sensor.exit()
        except Exception:
            pass
        _sensor = None

def _handle_signal(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    print(f"\nReceived signal {signum}, exiting...")
    _cleanup()
    sys.exit(0)

def main():
    global _sensor

    # Register signal handlers for clean termination.
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    # Initialize the DHT11 sensor on board.D4 (BCM GPIO 4, physical pin 7).
    try:
        _sensor = adafruit_dht.DHT11(board.D4, use_pulseio=False)
    except Exception as e:
        print(f"Failed to initialize DHT11 sensor: {e}")
        print("Check wiring: data pin to GPIO 4 (board.D4) and VCC/GND.")
        sys.exit(1)

    try:
        while True:
            try:
                temperature = _sensor.temperature
                humidity = _sensor.humidity

                if temperature is not None and humidity is not None:
                    print(f"Temperature: {temperature:.1f} C")
                    print(f"Humidity: {humidity:.1f} %")
                else:
                    print("Sensor returned None for temperature or humidity.")

            except RuntimeError as e:
                # DHT11 reads frequently fail transiently; log and continue.
                print(f"RuntimeError reading DHT11: {e}")

            time.sleep(5)

    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")

    finally:
        _cleanup()

if __name__ == "__main__":
    main()

