import time
import signal
import sys
import logging
from datetime import datetime

try:
    import RPi.GPIO as GPIO
except (ImportError, RuntimeError):
    GPIO = None

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
DHT_PIN = 17
FAN_PIN = 18
LOG_FILE = "urban_data_log.txt"
TEMP_THRESHOLD = 30.0   # °C
HUMIDITY_THRESHOLD = 70.0  # %
READ_INTERVAL = 2.0      # seconds
NUM_READINGS = 5

# ---------------------------------------------------------------------------
# Logging
# ---------------------------------------------------------------------------
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
log = logging.getLogger("urban_monitor")

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False
    log.info("Signal %s received – shutting down.", signum)


def _cleanup():
    if GPIO is not None:
        try:
            GPIO.cleanup()
        except Exception:
            pass
    log.info("GPIO cleanup completed.")


def _read_dht11(pin):
    """Return (temperature, humidity) or (None, None) on failure."""
    if GPIO is None:
        log.warning("RPi.GPIO unavailable – skipping sensor read.")
        return None, None
    try:
        # DHT11 timing (datasheet): start signal, 18–20 ms low, 80 µs high
        GPIO.setup(pin, GPIO.OUT)
        GPIO.output(pin, GPIO.LOW)
        time.sleep(0.018)
        GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)

        # Wait for sensor response: 80 µs low, then 80 µs high
        deadline = time.time() + 0.0003
        while GPIO.input(pin) == GPIO.HIGH:
            if time.time() > deadline:
                raise TimeoutError("DHT11 not responding (stuck HIGH).")
        deadline = time.time() + 0.0003
        while GPIO.input(pin) == GPIO.LOW:
            if time.time() > deadline:
                raise TimeoutError("DHT11 not responding (stuck LOW).")

        # Read 40 bits
        data = []
        for _ in range(40):
            deadline = time.time() + 0.0001
            while GPIO.input(pin) == GPIO.LOW:
                if time.time() > deadline:
                    raise TimeoutError("DHT11 clock low timeout.")
            deadline = time.time() + 0.0001
            while GPIO.input(pin) == GPIO.HIGH:
                if time.time() > deadline:
                    raise TimeoutError("DHT11 clock high timeout.")
            data.append(1 if GPIO.input(pin) == GPIO.HIGH else 0)

        # Parse 40-bit payload
        humidity_raw = (
            (data[0] << 7) | (data[1] << 6) | (data[2] << 5) | (data[3] << 4)
            | (data[4] << 3) | (data[5] << 2) | (data[6] << 1) | data[7]
        )
        temp_raw = (
            (data[8] << 7) | (data[9] << 6) | (data[10] << 5) | (data[11] << 4)
            | (data[12] << 3) | (data[13] << 2) | (data[14] << 1) | data[15]
        )
        checksum = (
            (data[16] << 7) | (data[17] << 6) | (data[18] << 5) | (data[19] << 4)
            | (data[20] << 3) | (data[21] << 2) | (data[22] << 1) | data[23]
        )

        # Verify checksum
        calc = (
            (humidity_raw + temp_raw) & 0xFF
        )
        if calc != checksum:
            raise ValueError(
                f"Checksum mismatch: got {checksum:#04x}, expected {calc:#04x}."
            )

        humidity = humidity_raw / 10.0
        temperature = temp_raw / 10.0
        return temperature, humidity

    except Exception as exc:
        log.error("DHT11 read failed: %s", exc)
        return None, None


def _set_fan(pin, on):
    if GPIO is None:
        log.warning("RPi.GPIO unavailable – skipping fan control.")
        return
    try:
        GPIO.output(pin, GPIO.HIGH if on else GPIO.LOW)
    except Exception as exc:
        log.error("Failed to set fan %s: %s", "ON" if on else "OFF", exc)


def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    if GPIO is not None:
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setwarnings(False)
        except Exception as exc:
            log.error("GPIO init failed: %s", exc)
            GPIO = None
    else:
        log.warning("RPi.GPIO not available – running in degraded mode.")

    try:
        for i in range(NUM_READINGS):
            if not _running:
                break

            temperature, humidity = _read_dht11(DHT_PIN)

            if temperature is not None and humidity is not None:
                timestamp = datetime.now().isoformat(timespec="seconds")
                log_entry = (
                    f"{timestamp} - Temperature: {temperature:.1f}°C, "
                    f"Humidity: {humidity:.1f}%"
                )
                try:
                    with open(LOG_FILE, "a") as fh:
                        fh.write(log_entry + "\n")
                except OSError as exc:
                    log.error("Failed to write log: %s", exc)

                fan_on = temperature > TEMP_THRESHOLD or humidity > HUMIDITY_THRESHOLD
                _set_fan(FAN_PIN, fan_on)

                status = (
                    f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%, "
                    f"Fan: {'ON' if fan_on else 'OFF'}"
                )
                print(status)
            else:
                log.warning("Skipping iteration %d due to sensor read failure.", i + 1)

            if i < NUM_READINGS - 1 and _running:
                time.sleep(READ_INTERVAL)

    except Exception as exc:
        log.exception("Unexpected error: %s", exc)
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

