import time
import signal
import sys
import logging

from ina219 import INA219, DeviceRangeError

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
log = logging.getLogger("pi_monitor")

SUPPLY_SHUNT = 0.00725
BATTERY_SHUNT = 0.005
READ_INTERVAL = 2.0

_running = True


def _handle_signal(signum, frame):
    global _running
    log.info("Received signal %s, shutting down...", signum)
    _running = False


def _read_ina219(ina, label, shunt):
    try:
        ina.configure(shunt)
        voltage = ina.voltage()
        current = ina.current()
        return f"{voltage:.3f} V, {current:.3f} mA"
    except DeviceRangeError:
        log.error("%s: current out of device range", label)
    except OSError as exc:
        log.error("%s: I2C read failed: %s", label, exc)
    except Exception as exc:
        log.error("%s: unexpected error: %s", label, exc)
    return None


def _read_ups(ups):
    try:
        proc = ups.get_proc_voltage()
        bat_port = ups.get_battery_port_voltage()
        temp = ups.get_temperature()
        capacity = ups.get_battery_remain()
        return (
            f"UPS: Proc {proc}mV, Battery Port {bat_port}mV, "
            f"Temp {temp}C, Capacity {capacity}%"
        )
    except OSError as exc:
        log.error("UPS read failed: %s", exc)
    except Exception as exc:
        log.error("UPS read failed: %s", exc)
    return None


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        ina_supply = INA219(
            address=0x40,
            busnum=1,
            max_expected_amps=20.0,
        )
    except OSError as exc:
        log.error("Failed to open supply INA219 on bus 1: %s", exc)
        sys.exit(1)

    try:
        ina_battery = INA219(
            address=0x41,
            busnum=1,
            max_expected_amps=20.0,
        )
    except OSError as exc:
        log.error("Failed to open battery INA219 on bus 1: %s", exc)
        sys.exit(1)

    try:
        ups = UPSController()
    except Exception as exc:
        log.error("Failed to open UPS controller: %s", exc)
        sys.exit(1)

    log.info("Starting monitoring loop (interval %.1fs)", READ_INTERVAL)

    while _running:
        supply_data = _read_ina219(ina_supply, "Supply", SUPPLY_SHUNT)
        battery_data = _read_ina219(ina_battery, "Battery", BATTERY_SHUNT)
        ups_data = _read_ups(ups)

        if supply_data:
            print(supply_data)
        if battery_data:
            print(battery_data)
        if ups_data:
            print(ups_data)

        for _ in range(int(READ_INTERVAL * 10)):
            if not _running:
                break
            time.sleep(0.1)

    log.info("Exited cleanly.")


if __name__ == "__main__":
    main()

