import subprocess
import time
import signal
import sys
import logging
from gpiozero import PWMOutputDevice

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

PWM_PIN = 14
PWM_FREQ = 100
CHECK_INTERVAL = 5

running = True
fan = None

def signal_handler(signum, frame):
    global running
    logging.info(f"Signal {signum} received, shutting down.")
    running = False

def get_cpu_temp():
    try:
        result = subprocess.run(
            ['vcgencmd', 'measure_temp'],
            capture_output=True, text=True, timeout=5, check=True
        )
        return float(result.stdout.split('=')[1].split("'")[0])
    except (subprocess.CalledProcessError, IndexError, ValueError, subprocess.TimeoutExpired) as e:
        logging.error(f"Failed to get CPU temperature: {e}")
        return None
    except FileNotFoundError:
        logging.error("'vcgencmd' not found. Is this running on a Raspberry Pi?")
        return None

def set_fan_speed(speed):
    if fan is not None:
        try:
            fan.value = speed / 100.0
            logging.info(f"Fan speed set to {speed:.2f}% (hardware PWM)")
        except Exception as e:
            logging.error(f"Failed to set fan speed (hardware PWM): {e}")
    else:
        logging.info(f"Fan speed set to {speed:.2f}% (degraded mode)")

def cleanup():
    global fan
    if fan is not None:
        try:
            fan.close()
            logging.info("PWM device closed.")
        except Exception as e:
            logging.error(f"Error closing PWM device: {e}")
        fan = None

def main():
    global fan
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        fan = PWMOutputDevice(PWM_PIN, frequency=PWM_FREQ, initial_value=0)
        logging.info(f"PWM initialized on GPIO{PWM_PIN} at {PWM_FREQ} Hz.")
    except Exception as e:
        logging.warning(f"Failed to initialize PWM on GPIO{PWM_PIN}: {e}. Continuing in degraded mode.")
        fan = None

    last_speed = 0.0
    try:
        while running:
            temp = get_cpu_temp()
            if temp is not None:
                if temp > 75:
                    speed = 100
                elif temp > 65:
                    speed = 80
                elif temp > 55:
                    speed = 60
                elif temp > 45:
                    speed = 40
                else:
                    speed = 20

                if speed != last_speed:
                    set_fan_speed(speed)
                    last_speed = speed
            else:
                logging.warning("Temperature read failed; keeping last fan speed.")

            for _ in range(CHECK_INTERVAL):
                if not running:
                    break
                time.sleep(1)
    finally:
        cleanup()

if __name__ == "__main__":
    main()

