import time
import random
import logging
import logging.handlers
import os
import signal
import sys

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    GPIO = None

# Constants
DHT_PIN = 4
LOG_FILE = "/var/log/wearable"
BACKUP_COUNT = 7
READ_INTERVAL = 5
MAX_RETRIES = 3
RETRY_DELAY = 1

# Logging setup
log_dir = os.path.expanduser("~/.local/log")
os.makedirs(log_dir, exist_ok=True)
fallback_log_file = os.path.join(log_dir, "wearable")
log_file = LOG_FILE if os.access(LOG_FILE, os.W_OK) else fallback_log_file

logger = logging.getLogger(__name__)
logger.setLevel(logging.INFO)
handler = logging.handlers.TimedRotatingFileHandler(
    log_file, when="midnight", interval=1, backupCount=BACKUP_COUNT
)
formatter = logging.Formatter("%(asctime)s - %(levelname)s - %(message)s")
handler.setFormatter(formatter)
logger.addHandler(handler)

# Graceful shutdown flag
_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


signal.signal(signal.SIGINT, _signal_handler)
signal.signal(signal.SIGTERM, _signal_handler)


def setup_gpio():
    if GPIO is None:
        logger.warning("RPi.GPIO not available; running in simulation mode.")
        return False
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(DHT_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        logger.info(f"GPIO pin {DHT_PIN} configured as input (BCM).")
        return True
    except Exception as e:
        logger.error(f"Failed to initialize GPIO: {e}")
        return False


def read_dht22():
    """Simulate reading temperature and humidity from a DHT22 sensor."""
    temperature = random.uniform(15, 45)
    humidity = random.uniform(40, 95)
    return temperature, humidity


