import RPi.GPIO as GPIO
import time
import sys

LED_PIN = 17

def cleanup_gpio():
    """Drive the LED low and release the GPIO pin."""
    try:
        GPIO.output(LED_PIN, GPIO.LOW)
    except Exception:
        pass
    GPIO.cleanup()

def main():
    led_state = False

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)
    except (RuntimeError, ValueError) as e:
        print(f"GPIO setup failed: {e}")
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected GPIO error: {e}")
        sys.exit(1)

    try:
        while True:
            try:
                user_input = input("Enter 'on' or 'off' to control the LED: ").strip().lower()
            except EOFError:
                print("\nEnd of input. Exiting program.")
                break

            if user_input == "on":
                led_state = True
            elif user_input == "off":
                led_state = False
            else:
                print("Invalid input")

            try:
                GPIO.output(LED_PIN, GPIO.HIGH if led_state else GPIO.LOW)
            except Exception as e:
                print(f"Failed to set GPIO output: {e}")
                break

            print(f"LED is now: {led_state}")
            time.sleep(0.1)

    except KeyboardInterrupt:
        print("\nExiting program.")
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        cleanup_gpio()

if __name__ == "__main__":
    main()

