import logging
import requests
from gpiozero import MotionSensor, LED

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")

PIR_PIN = 17
LED_PIN = 18
SERVER_URL = "http://127.0.0.1:5000/led"
POLL_INTERVAL = 1.0

_running = True

def _handle_sigint(signum, frame):
    global _running
    _running = False

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_sigint)

    try:
        pir = MotionSensor(PIR_PIN)
        led = LED(LED_PIN)
    except Exception as exc:
        logging.error("Failed to initialize GPIO devices: %s", exc)
        return

    logging.info("Monitoring PIR sensor on GPIO %d, driving LED on GPIO %d. Press Ctrl+C to exit.", PIR_PIN, LED_PIN)

    try:
        while _running:
            if pir.motion_detected:
                payload = {"led": "on"}
                logging.info("Motion detected — turning LED on.")
            else:
                payload = {"led": "off"}
                logging.info("No motion — turning LED off.")

            try:
                requests.post(SERVER_URL, json=payload, timeout=5)
            except requests.exceptions.RequestException as exc:
                logging.error("Error sending data to server: %s", exc)

            time.sleep(POLL_INTERVAL)
    finally:
        try:
            led.close()
        except Exception:
            pass
        try:
            pir.close()
        except Exception:
            pass
        logging.info("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

