import sys
import time
import signal
import threading
import traceback

try:
    import DOG
except ImportError:
    print("Error: DOG library not found. Please install it or check your environment variables.")
    sys.exit(1)

# Global state
log_file_name = ""
log_file = None
receive_thread = None
receive_event = threading.Event()
receive_lock = threading.Lock()


def log_data(data):
    """Appends data to the log file with error handling."""
    global log_file
    if log_file is None:
        print("Error: Log file not open.")
        return
    try:
        with log_file.open('a') as f:
            f.write(str(data) + '\n')
            f.flush()
    except IOError as e:
        print(f"Error writing to log file: {e}")


def receive_loop():
    """Background thread to continuously receive data from DOG."""
    while receive_event.is_set():
        try:
            data = DOG.receive()
            if data is not None:
                with receive_lock:
                    if log_file is not None:
                        log_data(data)
            time.sleep(0.1)
        except Exception as e:
            print(f"Error in receive loop: {e}")
            time.sleep(0.1)


def start_receiver(filename):
    """Starts the data receiving thread."""
    global log_file_name, log_file, receive_event, receive_thread
    try:
        log_file_name = filename
        log_file = open(log_file_name, 'a')
        receive_event.set()
        receive_thread = threading.Thread(target=receive_loop, daemon=True)
        receive_thread.start()
        print(f"Receiving data and logging to {log_file_name}")
    except IOError as e:
        print(f"Error starting receiver: {e}")
        log_file = None
        receive_event.clear()


def stop_receiver():
    """Stops the data receiving thread."""
    global receive_event, receive_thread
    receive_event.clear()
    if receive_thread is not None and receive_thread.is_alive():
        receive_thread.join(timeout=2.0)
    receive_thread = None
    print("Receiver stopped.")


def display_log():
    """Displays the contents of the log file."""
    global log_file
    if log_file is None:
        print("Error: Log file not open.")
        return
    try:
        with open(log_file_name, 'r') as f:
            content = f.read()
            print(content if content else "Log file is empty.")
    except IOError as e:
        print(f"Error displaying log: {e}")


def send_data(data):
    """Sends data using DOG.send()."""
    try:
        DOG.send(data)
        print(f"Sent data: {data}")
    except Exception as e:
        print(f"Error sending data: {e}")


def write_to_log(data):
    """Writes data directly to the log file."""
    global log_file
    if log_file is None:
        print("Error: Log file not open.")
        return
    try:
        with log_file.open('a') as f:
            f.write(str(data) + '\n')
            f.flush()
        print(f"Wrote to log: {data}")
    except IOError as e:
        print(f"Error writing to log: {e}")


def help_command(command=None):
    """Displays help information for commands."""
    if command is None:
        print("Available commands:")
        print("  help [command]")
        print("  start <filename>")
        print("  stop")
        print("  display")
        print("  send <data>")
        print("  write <data>")
        print("  exit")
    else:
        commands = {
            "help": "Call 'help' with no parameters to see available commands, or call 'help <command>' for details on a specific command.",
            "start": "Starts listening and logging data to a file. Usage: 'start <filename>'",
            "stop": "Stops listening and logging data. Usage: 'stop'",
            "display": "Displays the contents of the log file. Usage: 'display'",
            "send": "Sends data using DOG.send(). Usage: 'send <data>'",
            "write": "Writes data directly to the log file. Usage: 'write <data>'",
            "exit": "Exits the program. Usage: 'exit'"
        }
        if command in commands:
            print(commands[command])
        else:
            print(f"No help found for command '{command}'.")


def run_command(command):
    """Executes a command based on user input."""
    parts = command.split()
    if not parts:
        return

    cmd = parts[0].lower()
    args = parts[1:]

    if cmd == "start":
        if len(args) < 1:
            print("Error: 'start' requires a filename argument. Usage: 'start <filename>'")
        else:
            start_receiver(args[0])
    elif cmd == "stop":
        stop_receiver()
    elif cmd == "display":
        display_log()
    elif cmd == "send":
        if len(args) < 1:
            print("Error: 'send' requires data to send. Usage: 'send <data>'")
        else:
            send_data(" ".join(args))
    elif cmd == "write":
        if len(args) < 1:
            print("Error: 'write' requires data to write. Usage: 'write <data>'")
        else:
            write_to_log(" ".join(args))
    elif cmd == "help":
        help_command(" ".join(args) if args else None)
    elif cmd == "exit":
        stop_receiver()
        sys.exit(0)
    else:
        print(f"Unknown command: '{cmd}'. Try 'help'")


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    print(f"\nReceived signal {signum}, exiting...")
    stop_receiver()
    sys.exit(0)


def main():
    """Main function to run the DOG CLI."""
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        while True:
            try:
                command = input("JAYES@ROVER53:\t")
                run_command(command)
            except EOFError:
                print("\nEOF received, exiting.")
                break
            except Exception as e:
                print(f"An error occurred: {e}")
                traceback.print_exc()
    finally:
