import asyncio
import json
import logging
import os
import signal
import sys
import time
from pathlib import Path

import sounddevice as sd
import tflite_runtime.interpreter as tflite

CONFIG_FILE = "config.json"
DEFAULT_CONFIG = {
    "sampling_rate": 16000,
    "vad_sensitivity": 0.5,
    "keywords": ["hello", "bye"],
    "led_pin": 17,
    "sentiment_thresholds": {"positive": 0.6, "negative": 0.4},
    "heartbeat_interval": 60,
    "config_update_interval": 300,
    "log_usage_interval": 60,
    "cloud_alert_url": None,
    "cloud_alert_token": None,
}

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)
logger = logging.getLogger(__name__)


class ConfigManager:
    def __init__(self, config_file=CONFIG_FILE):
        self.config_file = config_file
        self.config = DEFAULT_CONFIG.copy()
        self.load_config()

    def load_config(self):
        try:
            with open(self.config_file, "r") as f:
                loaded = json.load(f)
            self.config.update(loaded)
            logger.info("Configuration loaded from %s", self.config_file)
        except FileNotFoundError:
            logger.warning("Configuration file not found. Using default configuration.")
        except json.JSONDecodeError as e:
            logger.error("Error decoding JSON from %s: %s. Using default configuration.", self.config_file, e)
        except Exception as e:
            logger.error("Unexpected error loading config: %s. Using default configuration.", e)

    def get(self, key, default=None):
        return self.config.get(key, default)

    def set(self, key, value):
        self.config[key] = value


class AudioProcessor:
    def __init__(self, config_manager):
        self.config_manager = config_manager
        self.sampling_rate = config_manager.get("sampling_rate", 16000)
        self.vad_sensitivity = config_manager.get("vad_sensitivity", 0.5)
        self.keywords = config_manager.get("keywords", [])
        self.sentiment_thresholds = config_manager.get("sentiment_thresholds", {})
        self.cloud_alert_url = config_manager.get("cloud_alert_url")
        self.cloud_alert_token = config_manager.get("cloud_alert_token")
        self.led_pin = config_manager.get("led_pin", 17)
        self.sentiment_history = []
        self.running = True

        try:
            self.interpreter = tflite.Interpreter(model_path="model.tflite")
            self.interpreter.allocate_tensors()
            self.input_details = self.interpreter.get_input_details()
            self.output_details = self.interpreter.get_output_details()
            logger.info("TensorFlow Lite model loaded successfully.")
        except Exception as e:
            logger.error("Failed to load TensorFlow Lite model: %s", e)
            self.interpreter = None

    async def process_audio(self):
        try:
            with sd.InputStream(samplerate=self.sampling_rate, channels=1, callback=self._callback):
                while self.running:
                    await asyncio.sleep(1)
        except sd.PortAudioError as e:
            logger.error("Audio device error: %s", e)
        except Exception as e:
            logger.error("Unexpected error in audio processing: %s", e)

    def _callback(self, indata, frames, time_info, status):
        if status:
            logger.warning("Audio stream status: %s", status)

    def run_vad(self, audio_data):
        if self.interpreter is None:
            return False
        try:
            input_data = audio_data.reshape(1, -1).astype('float32')
            self.interpreter.set_tensor(self.input_details[0]['index'], input_data)
            self.interpreter.invoke()
            output_data = self.interpreter.get_tensor(self.output_details[0]['index'])
            return float(output_data[0][0]) > self.vad_sensitivity
        except Exception as e:
            logger.error("Error running VAD: %s", e)
            return False

    def run_keyword_spotting(self, audio_data):
        if self.interpreter is None:
            return False
        try:
            input_data = audio_data.reshape(1, -1).astype('float32')
            self.interpreter.set_tensor(self.input_details[0]['index'], input_data)
            self.interpreter.invoke()
            output_data = self.interpreter.get_tensor(self.output_details[0]['index'])
            return float(output_data[0][0]) > 0.5
        except Exception as e:
            logger.error("Error running keyword spotting: %s", e)
            return False

    def run_sentiment_analysis(self, audio_data):
        if self.interpreter is None:
            return 0.0
        try:
            input_data = audio_data.reshape(1, -1).astype('float32')
            self.interpreter.set_tensor(self.input_details[0]['index'], input_data)
            self.interpreter.invoke()
            output_data = self.interpreter.get_tensor(self.output_details[0]['index'])
            sentiment = float(output_data[0][0])
            self.sentiment_history.append(sentiment)
            if len(self.sentiment_history) > 5:
                self.sentiment_history.pop(0)
            return sentiment
        except Exception as e:
            logger.error("Error running sentiment analysis: %s", e)
            return 0.0

    def trigger_alert(self, alert_type):
        logger.warning("Alert triggered: %s", alert_type)
        try:
            import RPi.GPIO as GPIO
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.led_pin, GPIO.OUT)
            GPIO.output(self.led_pin, GPIO.HIGH)
            time.sleep(1)
            GPIO.output(self.led_pin, GPIO.LOW)
        except Exception as e:
            logger.error("Error controlling GPIO: %s", e)

    def check_sentiment_thresholds(self):
        if not self.sentiment_history:
            return
        avg_sentiment = sum(self.sentiment_history) / len(self.sentiment_history)
        if avg_sentiment > self.sentiment_thresholds.get("positive", 0.6):
            self.trigger_alert("Positive Sentiment Alert")
        elif avg_sentiment < self.sentiment_thresholds.get("negative", 0.4):
            self.trigger_alert("Negative Sentiment Alert")

    def send_cloud_alert(self, alert_type):
        if not self.cloud_alert_url or not self.cloud_alert_token:
            logger.warning("Cloud alert configuration missing. Skipping cloud alert.")
            return
        try:
            import requests
            url = self.cloud_alert_url + "?token=" + self.cloud_alert_token
            data = {"alert_type": alert_type}
            response = requests.post(url, json=data, timeout=5)
            response.raise_for_status()
            logger.info("Cloud alert sent successfully.")
        except requests.exceptions.RequestException as e:
            logger.error("Error sending cloud alert: %s", e)


async def heartbeat(config_manager):
    while True:
        logger.info("Heartbeat signal sent.")
        await asyncio.sleep(config_manager.get("heartbeat_interval", 60))


async def check_config_updates(config_manager):
    while True:
        config_manager.load_config()
        await asyncio.sleep(config_manager.get("config_update_interval", 300))


async def log_resource_usage(config_manager):
    while True:
        try:
            import os
            logger.info("Resource usage: CPU %s, Memory %s", os.cpu_percent(), os.memory_percent())
        except Exception as e:
            logger.error("Error logging resource usage: %s", e)
        await asyncio.sleep(config_manager.get("log_usage_interval", 60))


async def main():
    config_manager = ConfigManager()
    audio_processor = AudioProcessor(config_manager)

    tasks = [
        asyncio.create_task(heartbeat(config_manager)),
        asyncio.create_task(check_config_updates(config_manager)),
        asyncio.create_task(log_resource_usage(config_manager)),
        asyncio.create_task(audio_processor.process_audio()),
    ]

    await asyncio.gather(*tasks)


def signal_handler(sig, frame):
    logger.info("Shutting down gracefully...")
    sys.exit(0)


if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        asyncio.run(main())
    except KeyboardInterrupt:
        logger.info("Program interrupted by user.")
    except Exception as e:
        logger.error("Unhandled exception: %s", e)
    finally:
        logger.info("Program finished.")

