import time
import signal
import sys
import logging
from gpiozero import PWMLED
from adafruit_tsl2561 import TSL2561
import board
import busio

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# Constants
LED_PIN = 18
PWM_FREQUENCY = 1000
READ_INTERVAL = 1.0

# Global flag for graceful shutdown
_running = True

def signal_handler(sig, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global _running
    logger.info("Shutdown signal received. Exiting gracefully...")
    _running = False

def initialize_i2c():
    """Initialize the I2C bus using board.SCL and board.SDA."""
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        logger.info("I2C bus initialized successfully.")
        return i2c
    except Exception as e:
        logger.error(f"Failed to initialize I2C bus: {e}")
        return None

def initialize_light_sensor(i2c_bus):
    """Initialize the TSL2561 light sensor."""
    try:
        sensor = TSL2561(i2c_bus)
        logger.info("TSL2561 light sensor initialized successfully.")
        return sensor
    except Exception as e:
        logger.error(f"Failed to initialize TSL2561 sensor: {e}")
        return None

def initialize_led(pin, frequency):
    """Initialize the PWM LED."""
    try:
        led = PWMLED(pin, frequency=frequency)
        logger.info(f"PWM LED initialized on GPIO {pin} at {frequency} Hz.")
        return led
    except Exception as e:
        logger.error(f"Failed to initialize PWM LED on GPIO {pin}: {e}")
        return None

def read_light_level(sensor):
    """Read the light level from the sensor and return it in lux."""
    try:
        lux = sensor.lux
        if lux is None:
            logger.warning("Sensor returned None for lux value.")
            return None
        return lux
    except Exception as e:
        logger.error(f"Error reading light level: {e}")
        return None

def calculate_brightness(lux):
    """Map the light level to a brightness value (0.0 to 1.0)."""
    if lux is None:
        return None
    # Simple linear mapping: 0 lux -> 0%, 1000 lux -> 100%
    return min(max(lux / 1000.0, 0.0), 1.0)

def set_led_brightness(led, brightness):
    """Set the LED brightness using PWM."""
    if led is None or brightness is None:
        return
    try:
        led.value = brightness
    except Exception as e:
        logger.error(f"Error setting LED brightness: {e}")

def cleanup(led, sensor, i2c_bus):
    """Clean up resources on exit."""
