import time
import logging
import signal
import sys
from datetime import datetime
from typing import List, Optional

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
logger = logging.getLogger(__name__)


class PIRSensor:
    """Minimal abstract base class for a PIR motion sensor driver."""

    def __init__(self, pin: int):
        self.pin = pin

    def read(self) -> bool:
        """Return True when motion is currently detected (active-high)."""
        raise NotImplementedError

    def close(self):
        """Release any resources held by the sensor."""
        pass


class HCSR501(PIRSensor):
    """Driver for the HC-SR501 PIR motion sensor (active-high output)."""

    def __init__(self, pin: int):
        super().__init__(pin)
        self._gpio = None
        try:
            import RPi.GPIO as GPIO
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
            self._gpio = GPIO
        except Exception as exc:
            logger.error("Failed to initialize GPIO %d: %s", self.pin, exc)
            raise

    def read(self) -> bool:
        try:
            return bool(self._gpio.input(self.pin))
        except Exception as exc:
            logger.error("Error reading GPIO %d: %s", self.pin, exc)
            return False

    def close(self):
        if self._gpio is not None:
            try:
                self._gpio.cleanup(self.pin)
            except Exception:
                pass
            self._gpio = None


class OccupancyMonitor:
    """Occupancy monitoring engine using a PIR motion sensor."""

    def __init__(
        self,
        sensor: PIRSensor,
        sample_count: int = 10,
        debounce_interval: float = 2.0,
    ):
        self.sensor = sensor
        self.sample_count = sample_count
        self.debounce_interval = debounce_interval
        self.event_log: List[str] = []
        self._running = True

    def _handle_signal(self, signum, frame):
        logger.info("Received signal %s, shutting down...", signum)
        self._running = False

    def run(self) -> None:
        signal.signal(signal.SIGINT, self._handle_signal)
        signal.signal(signal.SIGTERM, self._handle_signal)

        try:
            for i in range(self.sample_count):
                if not self._running:
                    break
                try:
                    motion_detected = self.sensor.read()
                except Exception as exc:
                    logger.error("Sensor read error on sample %d: %s", i, exc)
                    motion_detected = False

                if motion_detected:
                    timestamp = datetime.now().isoformat(timespec="seconds")
                    self.event_log.append(timestamp)
                    logger.info("Motion detected at %s", timestamp)
                    time.sleep(self.debounce_interval)

                time.sleep(0.5)

            self._report()

        except Exception as exc:
            logger.error("Unexpected error during monitoring: %s", exc)
        finally:
            self.sensor.close()

    def _report(self) -> None:
        logger.info("Occupancy report: %d events recorded", len(self.event_log))
        if self.event_log:
            logger.info("First event: %s", self.event_log[0])
            logger.info("Last event: %s", self.event_log[-1])


def main() -> int:
    sensor: Optional[PIRSensor] = None
    try:
        sensor = HCSR501(pin=17)
    except Exception as exc:
        logger.error("Failed to initialize PIR sensor: %s", exc)
        return 1

    monitor = OccupancyMonitor(sensor, sample_count=10, debounce_interval=2.0)
    monitor.run()
    return 0


if __name__ == "__main__":
    sys.exit(main())

