import signal
import threading
from gpiozero import OutputDevice


class OutputPin:
    """Generic output pin with value validation and clean shutdown."""

    def __init__(self, pin_number, name, initial_value=0, allowed_values=(0, 1)):
        if not isinstance(pin_number, int) or pin_number < 0:
            raise ValueError("pin_number must be a non-negative integer")
        if initial_value not in allowed_values:
            raise ValueError(
                f"initial_value must be one of {allowed_values}, got {initial_value}"
            )
        self.pin_number = pin_number
        self.name = name
        self.allowed_values = allowed_values
        self._device = None
        self._lock = threading.Lock()
        self._shutdown = False
        self._initialize(initial_value)

    def _initialize(self, value):
        try:
            self._device = OutputDevice(self.pin_number, initial_value=value)
        except Exception as exc:
            raise RuntimeError(
                f"Failed to initialize GPIO {self.pin_number} ({self.name}): {exc}"
            ) from exc

    def set_value(self, value):
        if self._shutdown:
            return
        if value not in self.allowed_values:
            raise ValueError(
                f"Invalid value {value!r}; must be one of {self.allowed_values}"
            )
        with self._lock:
            if self._shutdown:
                return
            try:
                self._device.value = value
            except Exception as exc:
                raise RuntimeError(
                    f"Failed to write GPIO {self.pin_number} ({self.name}): {exc}"
                ) from exc

    def get_value(self):
        with self._lock:
            if self._shutdown:
                return None
            try:
                return int(self._device.value)
            except Exception as exc:
                raise RuntimeError(
                    f"Failed to read GPIO {self.pin_number} ({self.name}): {exc}"
                ) from exc

    def shutdown(self):
        with self._lock:
            if self._shutdown:
                return
            self._shutdown = True
            device = self._device
            self._device = None
        if device is not None:
            try:
                device.close()
            except Exception:
                pass


class TriggerPin(OutputPin):
    """Output pin that can produce a 100 µs high pulse."""

    def __init__(self, pin_number, name, initial_value=0, pulse_high=True):
        super().__init__(pin_number, name, initial_value, allowed_values=(0, 1))
        self.pulse_high = pulse_high
        self._initialize(initial_value)

    def trigger(self):
        if self._shutdown:
            return
        with self._lock:
            if self._shutdown:
                return
            try:
                if self.pulse_high:
                    self._device.on()
                    import time
                    time.sleep(100e-6)
                    self._device.off()
                else:
                    self._device.off()
                    import time
                    time.sleep(100e-6)
                    self._device.on()
            except Exception as exc:
                raise RuntimeError(
                    f"Failed to trigger GPIO {self.pin_number} ({self.name}): {exc}"
                ) from exc


# ---------------------------------------------------------------------------
# Example usage
# ---------------------------------------------------------------------------
_output_pin = None
_trigger_pin = None


def _cleanup(signum=None, frame=None):
    global _output_pin, _trigger_pin
    for pin in (_trigger_pin, _output_pin):
        if pin is not None:
            pin.shutdown()
    if signum is not None:
        import os
        os._exit(0)


if __name__ == "__main__":
    signal.signal(signal.SIGINT, _cleanup)
    signal.signal(signal.SIGTERM, _cleanup)

    _output_pin = OutputPin(21, "ExampleOutput", initial_value=0)
    _trigger_pin = TriggerPin(20, "ExampleTrigger", initial_value=0, pulse_high=True)

    try:
        _output_pin.set_value(1)
        _trigger_pin.trigger()
        print("Pin states: output=1, trigger=1 (pulsed high)")
    finally:
        _cleanup()

