import logging
import signal
import time
from typing import Callable, Dict, List, Optional

import zmq

try:
    import RPi.GPIO as GPIO
    _GPIO_AVAILABLE = True
except (ImportError, RuntimeError):
    _GPIO_AVAILABLE = False


class PIDHandler:
    """
    Manages PWM and digital error outputs via RPi.GPIO (BOARD numbering).

    Physical pin 12 (BCM GPIO 18) -> PWM error output at 1000 Hz.
    Physical pin 10 (BCM GPIO 15) -> digital error output.
    """

    def __init__(
        self,
        pwm_pin: int = 12,
        digital_pin: int = 10,
        pwm_frequency: int = 1000,
        watchdog_timeout: float = 20.0,
        subscriptions: Optional[Dict[str, List[Callable]]] = None,
    ):
        self.logger = logging.getLogger(self.__class__.__name__)
        self.pwm_pin = pwm_pin
        self.digital_pin = digital_pin
        self.pwm_frequency = pwm_frequency
        self.watchdog_timeout = watchdog_timeout
        self.subscriptions = subscriptions or {}
        self.last_msg = time.time()
        self.global_err_state = False
        self.pwm = None
        self.pwm_ch = None
        self.digital_ch = None
        self._initialized = False

        if not _GPIO_AVAILABLE:
            self.logger.warning(
                "RPi.GPIO not available; running in no-op mode for PIDHandler."
            )
            return

        try:
            GPIO.setmode(GPIO.BOARD)
            GPIO.setwarnings(False)

            GPIO.setup(self.pwm_pin, GPIO.OUT, initial=GPIO.LOW)
            GPIO.setup(self.digital_pin, GPIO.OUT, initial=GPIO.LOW)

            self.pwm = GPIO.PWM(self.pwm_pin, self.pwm_frequency)
            self.pwm.start(0.0)
            self.pwm_ch = self.pwm
            self.digital_ch = GPIO
            self._initialized = True
            self.logger.info(
                f"PIDHandler initialized (pwm_pin=BCM{self.pwm_pin}, "
