# Program: Fingerprint Authentication System for Raspberry Pi 5
# Board: Raspberry Pi 5
# Sensor: Adafruit Fingerprint sensor over I2C (SCL=GPIO3, SDA=GPIO2)

import time
import board
import busio
import adafruit_fingerprint

# Constants
RETRY_DELAY_SECONDS = 1
MAX_RETRIES = 3


def initialize_fingerprint_sensor():
    """Initialize the I2C bus and fingerprint sensor with error handling."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        fingerprint_sensor = adafruit_fingerprint.Adafruit_Fingerprint(i2c_bus)
        return fingerprint_sensor, i2c_bus
    except ValueError as e:
        print(f"Error: I2C bus is locked or unavailable: {e}")
        return None, None
    except RuntimeError as e:
        print(f"Error: Fingerprint sensor not found or unresponsive: {e}")
        return None, None
    except Exception as e:
        print(f"Error initializing fingerprint sensor: {e}")
        return None, None


def capture_fingerprint_image(fingerprint_sensor):
    """Capture a fingerprint image and return the template or None."""
    try:
        return fingerprint_sensor.image_2_tz(1)
    except RuntimeError as e:
        print(f"Error capturing image: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error capturing image: {e}")
        return None


def search_fingerprint_database(fingerprint_sensor, fingerprint_template):
    """Search the fingerprint database and return (id, confidence) or None."""
    try:
        return fingerprint_sensor.finger_search()
    except RuntimeError as e:
        print(f"Error searching fingerprint database: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error searching database: {e}")
        return None


def authenticate_user(fingerprint_sensor):
    """Authenticate a user by comparing a captured template to the database."""
    print("Waiting for fingerprint...")
    time.sleep(0.5)  # Brief delay to give user time to place finger

    for attempt in range(MAX_RETRIES):
        print(f"Attempt {attempt + 1}/{MAX_RETRIES}")

        fingerprint_template = capture_fingerprint_image(fingerprint_sensor)
        if fingerprint_template is None:
            print("No finger detected. Please try again.")
            time.sleep(RETRY_DELAY_SECONDS)
            continue

        print("Template captured.")

        result = search_fingerprint_database(fingerprint_sensor, fingerprint_template)
        if result is None:
            print("No fingerprint match found.")
            time.sleep(RETRY_DELAY_SECONDS)
            continue

        # result is a tuple: (id, confidence)
        id, confidence = result
        if id == -1:
            print("No fingerprint match found.")
            time.sleep(RETRY_DELAY_SECONDS)
            continue

        print(f"Access Granted - ID: {id}, Confidence: {confidence}")
        return True

    print("Authentication failed after multiple attempts.")
    return False


def main():
    """Main entry point for the fingerprint authentication system."""
    fingerprint_sensor = None
    i2c_bus = None

    try:
        fingerprint_sensor, i2c_bus = initialize_fingerprint_sensor()
        if fingerprint_sensor is None:
            print("Failed to initialize fingerprint sensor. Exiting.")
            return

        print("Fingerprint authentication system started. Press Ctrl+C to exit.")
        while True:
            try:
                authenticate_user(fingerprint_sensor)
            except KeyboardInterrupt:
                print("\nExiting program.")
                break

    except KeyboardInterrupt:
        print("\nExiting program.")

    finally:
        if i2c_bus is not None:
            try:
                i2c_bus.deinit()
                print("I2C bus deinitialized.")
            except Exception as e:
                print(f"Error deinitializing I2C bus: {e}")
        print("Program finished.")


if __name__ == "__main__":
    main()

