import logging
import signal
import threading
import time
from typing import Optional

import RPi.GPIO as GPIO

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

DATA_OUT = 5
TIMER_OUT = 6
DATA_IN = 20
TIMER_IN = 21

START_BYTE = b"@"
END_BYTE = b"^"

BIT_DELAY = 0.0001
RECEIVE_TIMEOUT = 5.0

_lock = threading.Lock()
_gpio_initialized = False
_shutdown = threading.Event()


def _signal_handler(signum, frame):
    logging.info(f"Signal {signum} received, shutting down.")
    _shutdown.set()


def _setup_gpio() -> bool:
    global _gpio_initialized
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        GPIO.setup(DATA_OUT, GPIO.OUT, initial=GPIO.LOW)
        GPIO.setup(TIMER_OUT, GPIO.OUT, initial=GPIO.LOW)
        GPIO.setup(DATA_IN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
        GPIO.setup(TIMER_IN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
        _gpio_initialized = True
        logging.info("GPIO setup complete.")
        return True
    except Exception as e:
        logging.error(f"GPIO setup failed: {e}")
        return False


def _cleanup_gpio() -> None:
    global _gpio_initialized
    if _gpio_initialized:
        try:
            GPIO.cleanup()
            _gpio_initialized = False
            logging.info("GPIO cleanup complete.")
        except Exception as e:
            logging.error(f"GPIO cleanup error: {e}")


def _api_call(data: str) -> Optional[str]:
    try:
        response = data.upper()
        logging.info(f"API call response: {response}")
        return response
    except Exception as e:
        logging.error(f"API call error: {e}")
        return None


def send_data(data: str) -> None:
    if not _gpio_initialized:
        logging.error("GPIO not initialized; cannot send data.")
        return
    try:
        with _lock:
            GPIO.output(TIMER_OUT, GPIO.LOW)
            for byte in (START_BYTE + data + END_BYTE).encode("utf-8"):
                for bit in format(byte, "08b"):
                    GPIO.output(DATA_OUT, int(bit))
                    GPIO.output(TIMER_OUT, GPIO.LOW)
                    time.sleep(BIT_DELAY)
                    GPIO.output(TIMER_OUT, GPIO.HIGH)
                    time.sleep(BIT_DELAY)
            GPIO.output(TIMER_OUT, GPIO.LOW)
        logging.info(f"Sent data: {data}")
    except Exception as e:
        logging.error(f"Send data error: {e}")


def _receive_data_callback(channel: int) -> None:
    if _shutdown.is_set():
        return
    try:
        with _lock:
            if GPIO.input(TIMER_IN) == GPIO.HIGH:
                bit = GPIO.input(DATA_IN)
                if _receive_data.payload_bits is None:
                    _receive_data.payload_bits = bit
                else:
                    _receive_data.payload_bits = (_receive_data.payload_bits << 1) | bit
                    if len(_receive_data.payload_bytes) == 0 and _receive_data.payload_bits == 0:
                        pass
                    elif len(_receive_data.payload_bytes) == 0 and _receive_data.payload_bits == 64:
                        _receive_data.started = True
                    elif _receive_data.started:
                        _receive_data.payload_bytes.append(_receive_data.payload_bits)
                        _receive_data.payload_bits = None
                    if _receive_data.payload_bytes and _receive_data.payload_bytes[-1] == 0:
                        pass
                    elif _receive_data.payload_bytes and _receive_data.payload_bytes[-1] == 128:
                        _receive_data.end_seen = True
                    elif _receive_data.end_seen and _receive_data.payload_bytes[-1] == 192:
                        _receive_data.complete = True
    except Exception as e:
        logging.error(f"Receive callback error: {e}")


def receive_data(timeout: float = RECEIVE_TIMEOUT) -> str:
    global _receive_data
    _receive_data = {"payload_bytes": [], "payload_bits": None, "started": False, "end_seen": False, "complete": False}
    if not _gpio_initialized:
        logging.error("GPIO not initialized; cannot receive data.")
        return ""
    try:
        with _lock:
            GPIO.add_event_detect(TIMER_IN, GPIO.RISING, callback=_receive_data_callback, bouncetime=1)
        logging.info(f"Listening for data (timeout={timeout}s)...")
        if not _shutdown.wait(timeout):
            logging.warning("Receive timeout.")
            return ""
        with _lock:
            GPIO.remove_event_detect(TIMER_IN)
        if _receive_data.complete and _receive_data.payload_bytes:
            payload = bytes(_receive_data.payload_bytes)
            logging.info(f"Received data: {payload.decode('utf-8', errors='replace')}")
            return payload.decode("utf-8", errors="replace")
        logging.warning("No valid data received.")
        return ""
    except Exception as e:
        logging.error(f"Receive data error: {e}")
        return ""
    finally:
        with _lock:
            GPIO.remove_event_detect(TIMER_IN)


def main() -> None:
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    if not _setup_gpio():
        return
    try:
        logging.info("Starting main program...")
        send_data("hello")
        response = _api_call("hello")
        if response:
            logging.info(f"API Response: {response}")
        received = receive_data(timeout=RECEIVE_TIMEOUT)
        if received:
            logging.info(f"Received: {received}")
    except Exception as e:
        logging.error(f"Main error: {e}")
    finally:
        _cleanup_gpio()


if __name__ == "__main__":
    _receive_data = None
    main()

