                    elif _receive_data.payload_bytes and _receive_data.payload_bytes[-1] == 128:
                        _receive_data.end_seen = True
                    elif _receive_data.end_seen and _receive_data.payload_bytes[-1] == 192:
                        _receive_data.complete = True
    except Exception as e:
        logging.error(f"Receive callback error: {e}")


def receive_data(timeout: float = RECEIVE_TIMEOUT) -> str:
    global _receive_data
    _receive_data = {"payload_bytes": [], "payload_bits": None, "started": False, "end_seen": False, "complete": False}
    if not _gpio_initialized:
        logging.error("GPIO not initialized; cannot receive data.")
        return ""
    try:
        with _lock:
            GPIO.add_event_detect(TIMER_IN, GPIO.RISING, callback=_receive_data_callback, bouncetime=1)
        logging.info(f"Listening for data (timeout={timeout}s)...")
        if not _shutdown.wait(timeout):
            logging.warning("Receive timeout.")
            return ""
        with _lock:
            GPIO.remove_event_detect(TIMER_IN)
        if _receive_data.complete and _receive_data.payload_bytes:
            payload = bytes(_receive_data.payload_bytes)
            logging.info(f"Received data: {payload.decode('utf-8', errors='replace')}")
            return payload.decode("utf-8", errors="replace")
        logging.warning("No valid data received.")
        return ""
    except Exception as e:
        logging.error(f"Receive data error: {e}")
        return ""
    finally:
        with _lock:
            GPIO.remove_event_detect(TIMER_IN)


def main() -> None:
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    if not _setup_gpio():
        return
    try:
        logging.info("Starting main program...")
        send_data("hello")
        response = _api_call("hello")
        if response:
            logging.info(f"API Response: {response}")
        received = receive_data(timeout=RECEIVE_TIMEOUT)
        if received:
            logging.info(f"Received: {received}")
    except Exception as e:
        logging.error(f"Main error: {e}")
    finally:
        _cleanup_gpio()


if __name__ == "__main__":
    _receive_data = None
    main()

