import signal
import sys

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("Error: RPi.GPIO requires root privileges or a Raspberry Pi environment.")
    sys.exit(1)

PWM_PIN = 12
PWM_FREQ = 25000

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def _cleanup():
    try:
        GPIO.cleanup()
    except Exception:
        pass

def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    GPIO.setwarnings(False)
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(PWM_PIN, GPIO.OUT, initial=GPIO.LOW)

    pwm = None
    try:
        pwm = GPIO.PWM(PWM_PIN, PWM_FREQ)
        pwm.start(0)
    except Exception as e:
        print(f"Warning: hardware PWM unavailable ({e}); falling back to software PWM.")
        try:
            GPIO.setup(PWM_PIN, GPIO.OUT, initial=GPIO.LOW)
        except Exception:
            pass
        pwm = None

    try:
        while _running:
            try:
                raw = input("Fan Speed (0-100, or 'q' to quit): ").strip()
            except EOFError:
                break

            if raw.lower() == 'q':
                break

            if not raw:
                continue

            try:
                speed = float(raw)
            except ValueError:
                print("Invalid input: please enter a number between 0 and 100.")
                continue

            if not (0 <= speed <= 100):
                print("Invalid input: please enter a value between 0 and 100.")
                continue

            if pwm is not None:
                try:
                    pwm.ChangeDutyCycle(speed)
                except Exception as e:
                    print(f"Warning: failed to update duty cycle ({e}); continuing.")
            else:
                try:
                    GPIO.output(PWM_PIN, GPIO.HIGH if speed > 0 else GPIO.LOW)
                except Exception as e:
                    print(f"Warning: failed to update GPIO output ({e}); continuing.")

    finally:
        if pwm is not None:
            try:
                pwm.stop()
            except Exception:
                pass
        _cleanup()

if __name__ == "__main__":
    main()

