import signal
import sys
from http.server import BaseHTTPRequestHandler, HTTPServer

try:
    from gpiozero import LED
    from gpiozero.exc import GPIOZeroError
except ImportError:
    print("Error: gpiozero is not installed. Install with: pip install gpiozero", file=sys.stderr)
    sys.exit(1)

LED_PIN = 18
HOST_NAME = '0.0.0.0'
PORT_NUMBER = 8080

led = None
httpd = None


def cleanup(signum=None, frame=None):
    global led, httpd
    if httpd is not None:
        try:
            httpd.shutdown()
        except Exception:
            pass
    if led is not None:
        try:
            led.close()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)


signal.signal(signal.SIGINT, cleanup)
signal.signal(signal.SIGTERM, cleanup)

try:
    led = LED(LED_PIN)
except GPIOZeroError as e:
    print(f"Error initializing LED on GPIO{LED_PIN}: {e}", file=sys.stderr)
    sys.exit(1)
except Exception as e:
    print(f"Unexpected error initializing LED: {e}", file=sys.stderr)
    sys.exit(1)


class LEDRequestHandler(BaseHTTPRequestHandler):
    def do_GET(self):
        if self.path == '/led/on':
            try:
                led.on()
            except GPIOZeroError as e:
                print(f"Error turning LED on: {e}", file=sys.stderr)
                self.send_response(500)
                self.end_headers()
                return
            self.send_response(200)
            self.end_headers()
            self.wfile.write(b'LED is ON')
        elif self.path == '/led/off':
            try:
                led.off()
            except GPIOZeroError as e:
                print(f"Error turning LED off: {e}", file=sys.stderr)
                self.send_response(500)
                self.end_headers()
                return
            self.send_response(200)
            self.end_headers()
            self.wfile.write(b'LED is OFF')
        else:
            self.send_response(404)
            self.end_headers()
            self.wfile.write(b'Not Found')

    def log_message(self, format, *args):
        pass


try:
    httpd = HTTPServer((HOST_NAME, PORT_NUMBER), LEDRequestHandler)
    print(f"Starting server on {HOST_NAME}:{PORT_NUMBER}")
    httpd.serve_forever()
except OSError as e:
    print(f"Error binding to {HOST_NAME}:{PORT_NUMBER}: {e}", file=sys.stderr)
except Exception as e:
    print(f"Unexpected error: {e}", file=sys.stderr)
finally:
    cleanup()

