import signal
import sys
import time

try:
    import smbus2 as smbus
except ImportError:
    import smbus

BH1750_ADDR = 0x23
CMD_POWER_ON = 0x01
CMD_RESET = 0x07
CMD_CONTINUOUS_HIGH_RES_MODE = 0x10

running = True


def handle_sigint(signum, frame):
    global running
    running = False


signal.signal(signal.SIGINT, handle_sigint)


def read_lux(bus, addr):
    """Trigger a one-shot high-res measurement and return lux, or None on error."""
    try:
        bus.write_byte(addr, CMD_CONTINUOUS_HIGH_RES_MODE)
        time.sleep(0.18)  # max conversion time for high-res mode
        data = bus.read_i2c_block_data(addr, 0x00, 2)
        raw = (data[0] << 8) | data[1]
        return raw / 1.2
    except OSError:
        return None


def main():
    global running
    bus = None
    try:
        bus = smbus.SMBus(1)
    except OSError as e:
        print(f"Error: cannot open I2C bus 1: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        try:
            bus.write_byte(BH1750_ADDR, CMD_POWER_ON)
            time.sleep(0.01)
        except OSError:
            print("Error: BH1750 not responding at address 0x23. "
                  "Check wiring and run 'i2cdetect -y 1'.", file=sys.stderr)
            sys.exit(1)

        while running:
            lux = read_lux(bus, BH1750_ADDR)
            if lux is not None:
                print(f"Luminance: {lux:.2f} lux")
            else:
                print("Error: failed to read luminance.", file=sys.stderr)
            time.sleep(1)
    finally:
        if bus is not None:
            try:
                bus.close()
            except OSError:
                pass
        print("Program terminated by user.")


if __name__ == "__main__":
    main()

