#!/usr/bin/env python3
"""
Rainbow HAT 3-bit binary counter.

Touchpads A (GPIO5), B (GPIO6), C (GPIO12) toggle the three MSB, LSB, middle
bits respectively.  On each toggle the discrete LEDs, 14-segment display,
APA102 strip, and buzzer are updated.

Degrades gracefully when peripherals are absent (e.g. no I2C display, no
APA102, etc.).  Clean shutdown on SIGINT / SIGTERM.
"""

import signal
import sys
import time

try:
    import smbus2 as smbus
except ImportError:
    smbus = None

try:
    from gpiozero import Button, LED
except ImportError:
    Button = None
    LED = None

try:
    from apa102 import APA102
except ImportError:
    APA102 = None

# ---------------------------------------------------------------------------
# Pin / bit definitions
# ---------------------------------------------------------------------------
TOUCH_PINS = {
    "A": 5,   # MSB (bit 4)
    "B": 6,   # middle bit (bit 2)
    "C": 12,  # LSB (bit 1)
}

DISPLAY_I2C_ADDR = 0x70

# Rainbow HAT discrete LEDs (GPIO7 = green, GPIO8 = blue)
DISP_GREEN_PIN = 7
DISP_BLUE_PIN = 8

# APA102 SPI: data on GPIO10, clock on GPIO11
APA102_DATA_PIN = 10
APA102_CLOCK_PIN = 11

# Buzzer on GPIO13
BUZZER_PIN = 13

# 14-segment display command bytes (common-cathode, K14-style)
DISPLAY_CMD_DIGIT0 = 0x01
DISPLAY_CMD_DIGIT1 = 0x02
DISPLAY_CMD_DIGIT2 = 0x03
DISPLAY_CMD_DIGIT3 = 0x04
DISPLAY_CMD_DECODE = 0x09
DISPLAY_CMD_NO_DECODE = 0x08
DISPLAY_CMD_DISPLAY_ON = 0x0F
DISPLAY_CMD_DISPLAY_OFF = 0x0C

# Segment patterns for digits 0-9 (common-cathode)
DIGIT_PATTERNS = {
    0: 0x3F, 1: 0x06, 2: 0x5B, 3: 0x4F,
    4: 0x66, 5: 0x6D, 6: 0x7D, 7: 0x07,
    8: 0x7F, 9: 0x6F,
}

# ---------------------------------------------------------------------------
# Globals (initialised in setup)
# ---------------------------------------------------------------------------
buttons = {}
leds = {}
display_bus = None
strip = None
buzzer = None

# Internal state
bit_states = {
    "A": False,
    "B": False,
    "C": False,
}
current_value = 0

# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------

def _write_display(value: int) -> None:
    """Write a two-digit decimal value to the 14-segment display (best-effort)."""
    if display_bus is None:
        return
    try:
        display_bus.write_byte(DISPLAY_I2C_ADDR, DISPLAY_CMD_NO_DECODE)
        display_bus.write_byte(DISPLAY_I2C_ADDR, DISPLAY_CMD_DISPLAY_ON)
        display_bus.write_byte(DISPLAY_I2C_ADDR, DISPLAY_CMD_DIGIT0)
        display_bus.write_byte(DISPLAY_I2C_ADDR, DIGIT_PATTERNS.get(value % 10, 0x00))
        display_bus.write_byte(DISPLAY_I2C_ADDR, DISPLAY_CMD_DIGIT1)
        display_bus.write_byte(DISPLAY_I2C_ADDR, DIGIT_PATTERNS.get((value // 10) % 10, 0x00))
        display_bus.write_byte(DISPLAY_I2C_ADDR, DISPLAY_CMD_DECODE)
    except OSError as exc:
        print(f"[display] I2C write failed: {exc}", file=sys.stderr)


def _update_discrete() -> None:
    """Push the three bit states to the Rainbow HAT discrete LEDs."""
    if not leds:
        return
    try:
        leds["A"].on() if bit_states["A"] else leds["A"].off()
        leds["B"].on() if bit_states["B"] else leds["B"].off()
        leds["C"].on() if bit_states["C"] else leds["C"].off()
    except Exception as exc:
        print(f"[discrete] update failed: {exc}", file=sys.stderr)


def _update_strip() -> None:
    """Drive the APA102 LED strip based on the current value."""
    if strip is None:
        return
    try:
        pixels = []
        if current_value == 0:
            pixels.append((0, 0, 0, 0))          # dim white at index 0
        elif current_value == 7:
            pixels.extend((0xFF, 0xFF, 0xFF, 0))  # all seven pixels white
        else:
            r = 0xFF if bit_states["A"] else 0
            g = 0xFF if bit_states["B"] else 0
            b = 0xFF if bit_states["C"] else 0
            pixels.append((r, g, b, 0))
        strip.update(pixels)
    except Exception as exc:
        print(f"[strip] update failed: {exc}", file=sys.stderr)


def _sound_buzzer() -> None:
    """Sound the buzzer for 0.5 s while turning on the green/blue LEDs."""
    if buzzer is None:
        return
    try:
        leds["green"].on()
        leds["blue"].on()
        buzzer.on()
        time.sleep(0.5)
        buzzer.off()
        leds["green"].off()
        leds["blue"].off()
    except Exception as exc:
        print(f"[buzzer] sound failed: {exc}", file=sys.stderr)


def _cleanup() -> None:
    """Turn off all outputs and release resources."""
    global display_bus, strip, buzzer
    try:
        if display_bus is not None:
            try:
                display_bus.write_byte(DISPLAY_I2C_ADDR, DISPLAY_CMD_DISPLAY_OFF)
            except OSError:
                pass
    except Exception as exc:
        print(f"[display] cleanup error: {exc}", file=sys.stderr)
    try:
        if strip is not None:
            strip.clear()
            strip.update()
    except Exception as exc:
        print(f"[strip] cleanup error: {exc}", file=sys.stderr)
    try:
        for led in leds.values():
            try:
                led.off()
            except Exception:
                pass
    except Exception as exc:
        print(f"[leds] cleanup error: {exc}", file=sys.stderr)


def _handle_touch(name: str) -> None:
    """Toggle a bit, update outputs, and sound the buzzer."""
    global current_value
    bit_states[name] = not bit_states[name]
    current_value = (bit_states["A"] << 2) | (bit_states["B"] << 1) | bit_states["C"]
    _update_discrete()
    _update_strip()
    _write_display(current_value)
    _sound_buzzer()


def _setup() -> None:
    """Initialise all peripherals (best-effort)."""
    global display_bus, strip, buzzer, leds

    # --- I2C display ---
    if smbus is not None:
        try:
            display_bus = smbus.SMBus(1)
            display_bus.write_byte(DISPLAY_I2C_ADDR, DISPLAY_CMD_NO_DECODE)
            display_bus.write_byte(DISPLAY_I2C_ADDR, DISPLAY_CMD_DISPLAY_ON)
            display_bus.write_byte(DISPLAY_I2C_ADDR, DISPLAY_CMD_DIGIT0)
            display_bus.write_byte(DISPLAY_I2C_ADDR, 0x00)
            display_bus.write_byte(DISPLAY_I2C_ADDR, DISPLAY_CMD_DIGIT1)
            display_bus.write_byte(DISPLAY_I2C_ADDR, 0x00)
            display_bus.write_byte(DISPLAY_I2C_ADDR, DISPLAY_CMD_DECODE)
        except OSError as exc:
            print(f"[display] I2C init failed: {exc}", file=sys.stderr)
            display_bus = None
    else:
        print("[display] smbus2 not installed; display disabled.", file=sys.stderr)

    # --- APA102 strip ---
    if APA102 is not None:
        try:
            strip = APA102(num_leds=8, global_brightness=0.5,
                           mosi=APA102_DATA_PIN, sclk=APA102_CLOCK_PIN)
            strip.clear()
            strip.update()
        except Exception as exc:
            print(f"[strip] init failed: {exc}", file=sys.stderr)
            strip = None
    else:
        print("[strip] apa102 library not installed; strip disabled.", file=sys.stderr)

    # --- Buzzer ---
    if buzzer is not None:
        try:
            buzzer = LED(BUZZER_PIN)
            buzzer.off()
        except Exception as exc:
            print(f"[buzzer] init failed: {exc}", file=sys.stderr)
            buzzer = None

    # --- Rainbow HAT discrete LEDs ---
    if LED is not None:
        try:
            leds = {
                "A": LED(5),
                "B": LED(6),
                "C": LED(12),
                "green": LED(DISP_GREEN_PIN),
                "blue": LED(DISP_BLUE_PIN),
            }
            for led in leds.values():
                led.off()
        except Exception as exc:
            print(f"[leds] init failed: {exc}", file=sys.stderr)
            leds = {}

    # --- Touchpads ---
    if Button is not None:
        for name, pin in TOUCH_PINS.items():
            try:
                btn = Button(pin, pull_up=True, bounce_time=0.05)
                btn.when_pressed = lambda n=name: _handle_touch(n)
                buttons[name] = btn
            except Exception as exc:
                print(f"[touch] {name} on GPIO{pin} init failed: {exc}", file=sys.stderr)
    else:
        print("[touch] gpiozero not installed; touch events disabled.", file=sys.stderr)


def _signal_handler(signum, frame) -> None:
    print(f"\nSignal {signum} received, shutting down...")
    _cleanup()
    sys.exit(0)


def main() -> None:
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    _setup()
    print("Binary counter ready. Press touchpads A/B/C to toggle bits.")
    print("Press Ctrl+C to exit.")
    try:
        signal.pause()
    except KeyboardInterrupt:
        pass
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

