import time
import signal
import sys
import smbus2
from gpiozero import PWMLED

# TSL2561 constants
TSL2561_ADDR = 0x29
TSL2561_COMMAND_BIT = 0xA0
TSL2561_REGISTER_ENABLE = 0x00
TSL2561_REGISTER_CONTROL = 0x01
TSL2561_REGISTER_CHAN0_LOW = 0x14
TSL2561_REGISTER_CHAN1_LOW = 0x16
TSL2561_REGISTER_CHAN0_HIGH = 0x15
TSL2561_REGISTER_CHAN1_HIGH = 0x17
TSL2561_REGISTER_DEVICE_ID = 0x12
TSL2561_REGISTER_DEVICE_ID_EXPECTED = 0x50

TSL2561_POWER_ON = 0x03
TSL2561_POWER_OFF = 0x00
TSL2561_INTEGRATIONTIME_101MS = 0x00
TSL2561_GAIN_16X = 0x10
TSL2561_CONTROL_POWERON = 0x03

PWM_FREQUENCY = 1000
LED_GPIO_PIN = 18

running = True


def signal_handler(signum, frame):
    global running
    running = False


def read_word(bus, reg):
    high = bus.read_byte_data(TSL2561_ADDR, reg)
    low = bus.read_byte_data(TSL2561_ADDR, reg + 1)
    return (high << 8) | low


def write_word(bus, reg, value):
    bus.write_byte_data(TSL2561_ADDR, reg, (value >> 8) & 0xFF)
    bus.write_byte_data(TSL2561_ADDR, reg + 1, value & 0xFF)


def initialize_sensor(bus):
    try:
        dev_id = bus.read_byte_data(TSL2561_ADDR, TSL2561_REGISTER_DEVICE_ID)
        if dev_id != TSL2561_REGISTER_DEVICE_ID_EXPECTED:
            print(f"Error: Unexpected device ID 0x{dev_id:02X} (expected 0x{TSL2561_REGISTER_DEVICE_ID_EXPECTED:02X})")
            return False
        bus.write_byte_data(TSL2561_ADDR, TSL2561_COMMAND_BIT | TSL2561_REGISTER_ENABLE, TSL2561_POWER_ON)
        write_word(bus, TSL2561_COMMAND_BIT | TSL2561_REGISTER_CONTROL, TSL2561_INTEGRATIONTIME_101MS | TSL2561_GAIN_16X)
        bus.write_byte_data(TSL2561_ADDR, TSL2561_COMMAND_BIT | TSL2561_REGISTER_ENABLE, TSL2561_CONTROL_POWERON)
        return True
    except OSError as e:
        print(f"Error initializing TSL2561 sensor: {e}")
        return False


def read_light_level(bus):
    try:
        ch0 = read_word(bus, TSL2561_COMMAND_BIT | TSL2561_REGISTER_CHAN0_LOW)
        ch1 = read_word(bus, TSL2561_COMMAND_BIT | TSL2561_REGISTER_CHAN1_LOW)
        if ch0 == 0 and ch1 == 0:
            return 0.0
        ratio = ch1 / ch0 if ch0 > 0 else 0.0
        if 0 < ratio <= 0.52:
            lux = (0.0315 * ch0) - (0.05934 * ch0 * (ratio ** 1.4))
        elif ratio <= 0.65:
            lux = (0.02291 * ch0) - (0.02916 * ch1)
        elif ratio <= 0.80:
            lux = (0.01579 * ch0) - (0.01804 * ch1)
        elif ratio <= 1.3:
            lux = (0.00338 * ch0) - (0.00260 * ch1)
        else:
            lux = 0.0
        return max(0.0, lux)
    except OSError as e:
        print(f"Error reading light level: {e}")
        return None


def calculate_brightness(lux):
    if lux <= 50.0:
        return 0.0
    elif lux <= 100.0:
        return (lux - 50.0) / 50.0
    elif lux <= 500.0:
        return 1.0
    elif lux <= 1000.0:
        return 1.0 - ((lux - 500.0) / 500.0)
    else:
        return 0.0


def set_led_brightness(led, brightness):
    try:
        led.value = brightness
    except Exception as e:
        print(f"Error setting LED brightness: {e}")


def cleanup(bus, led):
    try:
        if bus is not None:
            bus.write_byte_data(TSL2561_ADDR, TSL2561_COMMAND_BIT | TSL2561_REGISTER_ENABLE, TSL2561_POWER_OFF)
    except OSError:
        pass
    try:
        if led is not None:
            led.close()
    except Exception:
        pass


def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    bus = None
    led = None
    try:
        bus = smbus2.SMBus(1)
        led = PWMLED(LED_GPIO_PIN, frequency=PWM_FREQUENCY)
        if not initialize_sensor(bus):
            print("Failed to initialize TSL2561 sensor. Exiting.")
            return

        while running:
            lux = read_light_level(bus)
            if lux is not None:
                brightness = calculate_brightness(lux)
                set_led_brightness(led, brightness)
                print(f"Light Level: {lux:.2f} lux, LED Brightness: {brightness * 100:.2f}%")
            else:
                print("Failed to read light level. Retrying...")
            time.sleep(1)

    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        cleanup(bus, led)
        print("Program terminated.")


if __name__ == "__main__":
    main()

