    while True:
        led.on()
        print("LED is ON")
        time.sleep(1)

        led.off()
        print("LED is OFF")
        time.sleep(1)

except KeyboardInterrupt:
    print("Program stopped by user")
except GPIOZeroError as e:
    print(f"GPIO error: {e}")
except Exception as e:
    print(f"Unexpected error: {e}")
finally:
    try:
        led.off()
        led.close()
    except Exception:
        pass

