import time
import logging
import signal
import sys
from collections import deque

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants for GPIO and grid
STATUS_LED_PIN = 18
GRID_WIDTH = 5
GRID_HEIGHT = 5
SUCCESS_INDICATOR_DURATION = 2.0
FAILURE_INDICATOR_DURATION = 2.0
FAILURE_BLINK_INTERVAL = 0.5
BLINK_COUNT = 3

# Global flag for graceful shutdown
_running = True

def signal_handler(sig, frame):
    global _running
    _running = False
    logging.info("Shutdown signal received. Cleaning up...")

def setup_gpio():
    """Sets up the GPIO pin for the status LED."""
    try:
        import RPi.GPIO as GPIO
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(STATUS_LED_PIN, GPIO.OUT, initial=GPIO.LOW)
        logging.info("GPIO setup complete.")
    except ImportError:
        logging.warning("RPi.GPIO not available. LED functionality disabled.")
    except Exception as e:
        logging.error(f"GPIO setup failed: {e}")

def teardown_gpio():
    """Cleans up the GPIO settings."""
    try:
        import RPi.GPIO as GPIO
        GPIO.cleanup()
        logging.info("GPIO cleanup complete.")
    except ImportError:
        pass
    except Exception as e:
        logging.error(f"GPIO cleanup failed: {e}")

def validate_grid(grid):
    """Validates the grid dimensions."""
    if not isinstance(grid, list) or len(grid) == 0:
        raise ValueError("Grid must be a non-empty list.")
    for row in grid:
        if not isinstance(row, list) or len(row) != GRID_WIDTH:
            raise ValueError("Grid rows must have exactly 5 columns.")

def plan_path(grid, start_cell, goal_cell):
    """Plans a path from start_cell to goal_cell using BFS."""
    validate_grid(grid)

    if not (0 <= start_cell[0] < GRID_HEIGHT and 0 <= start_cell[1] < GRID_WIDTH):
        raise ValueError("Start cell is out of bounds.")
    if not (0 <= goal_cell[0] < GRID_HEIGHT and 0 <= goal_cell[1] < GRID_WIDTH):
        raise ValueError("Goal cell is out of bounds.")
    if grid[start_cell[0]][start_cell[1]] == 1:
        raise ValueError("Start cell is an obstacle.")
    if grid[goal_cell[0]][goal_cell[1]] == 1:
        raise ValueError("Goal cell is an obstacle.")

    frontier = deque([start_cell])
    came_from = {start_cell: None}

    while frontier:
        current_cell = frontier.popleft()
        if current_cell == goal_cell:
            break
        row, col = current_cell
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = row + dr, col + dc
            if 0 <= nr < GRID_HEIGHT and 0 <= nc < GRID_WIDTH:
                neighbor = (nr, nc)
                if grid[nr][nc] == 0 and neighbor not in came_from:
                    came_from[neighbor] = current_cell
                    frontier.append(neighbor)

    if goal_cell not in came_from:
        return None

    path = []
    cell = goal_cell
    while cell is not None:
        path.append(cell)
        cell = came_from[cell]
    path.reverse()
    return path

def indicate_success(duration):
    """Indicates success by turning on the LED for a specified duration."""
    try:
        import RPi.GPIO as GPIO
        GPIO.output(STATUS_LED_PIN, GPIO.HIGH)
        time.sleep(duration)
        GPIO.output(STATUS_LED_PIN, GPIO.LOW)
