import random
import json
import sys

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    GPIO = None


def transcribe_frame(energy_level):
    """Simulate transcribing a single audio frame into a keyword string."""
    keywords = ["water", "stop", "status"]
    return keywords[random.randint(0, 2)]


def map_keyword_to_action(keyword):
    """Map recognized keywords to farm control actions."""
    action_table = {
        "water": "open_valve",
        "stop": "close_valve",
        "status": "report",
    }
    return action_table.get(keyword, "unknown")


def main():
    """Simulate a voice recognition loop for smart agriculture."""
    actions_taken = []
    try:
        if GPIO is not None:
            GPIO.setmode(GPIO.BCM)
            GPIO.setwarnings(False)

        for frame_index in range(6):
            energy_level = random.randint(0, 9)
            keyword = transcribe_frame(energy_level)
            action = map_keyword_to_action(keyword)
            print(f"Frame {frame_index}: energy={energy_level} -> {keyword} -> {action}")
            actions_taken.append(action)

    except Exception as e:
        print(f"Error during voice recognition simulation: {e}", file=sys.stderr)
        sys.exit(1)

    finally:
        if GPIO is not None:
            GPIO.cleanup()

        try:
            with open("voice_actions.json", "w") as f:
                json.dump(actions_taken, f, indent=2)
            print("Actions written to voice_actions.json")
        except IOError as e:
            print(f"Error writing JSON file: {e}", file=sys.stderr)


