import RPi.GPIO as GPIO
import time
import logging
import signal
import sys

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)


class MotionCounter:
    """
    Monitors an HC-SR501 PIR motion sensor on a Raspberry Pi GPIO pin,
    debounces readings, and counts visitors per minute.
    """

    PIR_PIN = 23
    DEBOUNCE_MS = 200
    SENSOR_TIMEOUT_S = 30
    POLL_INTERVAL_S = 10
    RUN_DURATION_S = 60

    def __init__(self, pin=PIR_PIN):
        self.pin = pin
        self.visitor_total = 0
        self.last_trigger_time = 0.0
        self._running = True

        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
            logging.info("GPIO initialized: pin %d as input with pull-down", self.pin)
        except Exception as exc:
            logging.error("Failed to initialize GPIO: %s", exc)
            raise

    def _signal_handler(self, signum, frame):
        logging.info("Received signal %d, shutting down...", signum)
        self._running = False

    def register_signals(self):
        signal.signal(signal.SIGINT, self._signal_handler)
        signal.signal(signal.SIGTERM, self._signal_handler)

    def read_motion(self):
        """Return True if the PIR output is HIGH (motion detected)."""
        try:
            return GPIO.input(self.pin) == GPIO.HIGH
        except Exception as exc:
            logging.error("GPIO read error on pin %d: %s", self.pin, exc)
            return False

    def debounce(self, current_time):
        """Return True only if a debounced HIGH reading is registered."""
        if self.read_motion():
            if (current_time - self.last_trigger_time) * 1000 >= self.DEBOUNCE_MS:
                self.last_trigger_time = current_time
                return True
        return False

    def poll_once(self):
        """Process one poll cycle: debounce and update visitor tally."""
        if not self._running:
            return False
        current_time = time.time()
        if self.debounce(current_time):
            self.visitor_total += 1
            logging.info("Visitor #%d detected", self.visitor_total)
        return True

    def run(self):
        self.register_signals()
        self.last_trigger_time = time.time()
        start_time = self.last_trigger_time

        try:
            while self._running:
                if (self.last_trigger_time + self.SENSOR_TIMEOUT_S) < time.time():
                    logging.warning("Sensor timeout: no motion for %d s", self.SENSOR_TIMEOUT_S)
                    break
                if not self.poll_once():
                    time.sleep(0.1)
                    continue
                if (time.time() - start_time) >= self.RUN_DURATION_S:
                    break
                if (time.time() - self.last_trigger_time) >= self.POLL_INTERVAL_S:
                    logging.info("Visitors per minute: %d", self.visitor_total)
                    self.last_trigger_time = time.time()
                    self.visitor_total = 0
        except Exception as exc:
            logging.error("Unexpected error in run loop: %s", exc)
        finally:
            self.cleanup()

    def cleanup(self):
        try:
            GPIO.cleanup()
            logging.info("GPIO cleaned up")
        except Exception as exc:
            logging.error("Error during GPIO cleanup: %s", exc)


if __name__ == "__main__":
    counter = MotionCounter()
    counter.run()

