import time

import smbus2

# LSM303DLHC I2C addresses
LSM303_ACCEL_ADDR = 0x19
LSM303_MAG_ADDR = 0x1E

# Register addresses
LSM303_ACCEL_REG_CTRL_REG1_A = 0x20
LSM303_ACCEL_REG_OUT_X_L_A = 0x28

LSM303_MAG_REG_CTRL_REG1 = 0x20
LSM303_MAG_REG_CTRL_REG2 = 0x21
LSM303_MAG_REG_CTRL_REG3 = 0x22
LSM303_MAG_REG_CTRL_REG4 = 0x23
LSM303_MAG_REG_STATUS_REG = 0x27
LSM303_MAG_REG_OUT_X_L = 0x28

# Configuration values
ACCEL_CTRL_REG1_A_VAL = 0x77  # Enable all axes, 100 Hz ODR, normal mode
MAG_CTRL_REG1_VAL = 0x70      # Enable all axes, 100 Hz ODR, continuous-conversion mode
MAG_CTRL_REG4_VAL = 0x0C      # 16-bit resolution, 10 Hz ODR
MAG_CTRL_REG3_VAL = 0x00      # Continuous-conversion mode


class LSM303DLHC:
    def __init__(self, bus_num=1, accel_offsets=(0.0, 0.0, 0.0), mag_offsets=(0.0, 0.0, 0.0)):
        self.bus = None
        self.accel_offsets = accel_offsets
        self.mag_offsets = mag_offsets
        self.running = True

        try:
            self.bus = smbus2.SMBus(bus_num)
        except FileNotFoundError:
            print(f"Error: I2C bus {bus_num} not found. Enable I2C via raspi-config.", file=sys.stderr)
            sys.exit(1)
        except PermissionError:
            print(f"Error: Permission denied on I2C bus {bus_num}. Run as root or add user to i2c group.", file=sys.stderr)
            sys.exit(1)
        except Exception as e:
            print(f"Error initializing I2C bus {bus_num}: {e}", file=sys.stderr)
            sys.exit(1)

        self._init_accel()
        self._init_mag()

    def _write_mag_reg(self, reg, value):
        try:
            self.bus.write_byte_data(LSM303_MAG_ADDR, reg, value)
        except OSError as e:
            print(f"I2C write error to magnetometer reg 0x{reg:02X}: {e}", file=sys.stderr)
            raise

    def _read_mag_reg(self, reg):
        try:
            return self.bus.read_byte_data(LSM303_MAG_ADDR, reg)
        except OSError as e:
            print(f"I2C read error from magnetometer reg 0x{reg:02X}: {e}", file=sys.stderr)
            raise

    def _init_accel(self):
        try:
            self.bus.write_byte_data(LSM303_ACCEL_ADDR, LSM303_ACCEL_REG_CTRL_REG1_A, ACCEL_CTRL_REG1_A_VAL)
            time.sleep(0.01)
        except OSError as e:
