import time
import logging
from PIL import Image
import board
import busio
import adafruit_tcs34725

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
log = logging.getLogger("color_demo")

IMAGE_PATH = "image.jpg"
WIDTH = 100
HEIGHT = 100
I2C_SCL = board.SCL
I2C_SDA = board.SDA

_running = True

def _signal_handler(signum, frame):
    global _running
    log.info("Signal %s received, shutting down...", signum)
    _running = False

def read_color_data(sensor):
    try:
        r, g, b, c = sensor.color_rgb_bytes
        return r, g, b, c
    except Exception as exc:
        log.error("Sensor read failed: %s", exc)
        return 0, 0, 0, 0

def get_dominant_color(image_path):
    try:
        img = Image.open(image_path).convert("RGB")
        img = img.resize((WIDTH, HEIGHT))
        colors = img.getcolors(WIDTH * HEIGHT)
        if not colors:
            return 0, 0, 0
        counts = {}
        for count, (r, g, b) in colors:
            key = (r, g, b)
            counts[key] = counts.get(key, 0) + count
        dominant = max(counts, key=counts.get)
        return dominant
    except FileNotFoundError:
        log.error("Image file not found: %s", image_path)
        return 0, 0, 0
    except Exception as exc:
        log.error("Image processing failed: %s", exc)
        return 0, 0, 0

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    i2c = None
    sensor = None
    try:
        i2c = busio.I2C(I2C_SCL, I2C_SDA)
        log.info("I2C bus initialized (SCL=%s, SDA=%s).", I2C_SCL, I2C_SDA)
    except Exception as exc:
        log.error("I2C bus initialization failed: %s", exc)
        sys.exit(1)

    try:
        sensor = adafruit_tcs34725.TCS34725(i2c)
        sensor.integration_time = 0.05
        sensor.gain = 4
        log.info("TCS34725 initialized (integration=50ms, gain=4x).")
    except Exception as exc:
        log.error("TCS34725 not detected on the I2C bus: %s", exc)
        if i2c:
            i2c.deinit()
        sys.exit(1)

    try:
        while _running:
            r, g, b, c = read_color_data(sensor)
            log.info("Raw Sensor Data: R=%d, G=%d, B=%d, C=%d", r, g, b, c)

            dr, dg, db = get_dominant_color(IMAGE_PATH)
            log.info("Dominant Image Color: R=%d, G=%d, B=%d", dr, dg, db)

            for _ in range(10):
                if not _running:
                    break
                time.sleep(0.1)
    finally:
        if sensor:
            try:
                sensor.deinit()
            except Exception:
                pass
        if i2c:
            try:
                i2c.deinit()
            except Exception:
                pass
        log.info("Resources released. Exiting.")

if __name__ == "__main__":
    main()

