import signal
import sys
import time
from typing import Optional, Tuple

try:
    import serial
    from serial import SerialException
except ImportError:
    serial = None
    SerialException = Exception

# Constants
GPS_READ_TIMEOUT = 2  # seconds
TCP_PORT = 9099
GPS_READ_INTERVAL = 1  # seconds between simulated position updates

# Global state
gps_state = "stopped"
gps_position: Optional[Tuple[float, float]] = None
uart: Optional[serial.Serial] = None
server_socket: Optional[socket.socket] = None
running = True


def log_error(message: str) -> None:
    """Logs an error message to stderr."""
    print(f"ERROR: {message}", file=sys.stderr)


def initialize_gps() -> bool:
    """Initializes the GPS module via UART on /dev/serial0 (GPIO14/GPIO15)."""
    global uart
    if serial is None:
        log_error("pyserial library not available; using simulated GPS.")
        return False
    try:
        uart = serial.Serial(
            port="/dev/serial0",
            baudrate=9600,
            timeout=GPS_READ_TIMEOUT,
        )
        log_error("GPS module initialized on /dev/serial0.")
        return True
    except SerialException as e:
        log_error(f"Failed to initialize GPS module: {e}")
        uart = None
        return False
    except Exception as e:
        log_error(f"Unexpected error initializing GPS: {e}")
        uart = None
        return False


def read_gps_position() -> Optional[Tuple[float, float]]:
    """Reads GPS coordinates from the UART. Returns (lat, lon) or None on failure."""
    global gps_position
    if uart is None:
        return None

    try:
        # Read a line from the GPS module; returns b'' on timeout
        raw = uart.readline()
        if not raw:
            return None

        line = raw.decode("utf-8", errors="ignore").strip()
        if not line:
            return None

        # Example: $GPRMC,225446,A,4916.45,N,12311.12,W,0.2,318.52,010120,,,A*7B
        parts = line.split(",")
        if len(parts) < 7:
            return None

        status = parts[2]
        if status != "A":
            return None

        lat_raw = parts[3]
        lat_dir = parts[4]
        lon_raw = parts[5]
        lon_dir = parts[6]

        if not lat_raw or not lon_raw:
            return None

        lat = float(lat_raw)
        lon = float(lon_raw)

        if lat_dir == "S":
            lat = -lat
        if lon_dir == "W":
            lon = -lon

        gps_position = (lat, lon)
        return gps_position

    except SerialException as e:
        log_error(f"Serial communication error: {e}")
        return None
    except ValueError as e:
        log_error(f"Value error parsing GPS data: {e}")
        return None
    except Exception as e:
        log_error(f"Unexpected error reading GPS: {e}")
        return None


def handle_command(command: str) -> str:
    """Handles incoming commands and updates the GPS tracking state."""
    global gps_state
    if command == "start":
        gps_state = "running"
        log_error("GPS tracking started.")
        return json.dumps({"status": "running"})
    elif command == "stop":
        gps_state = "stopped"
        log_error("GPS tracking stopped.")
        return json.dumps({"status": "stopped"})
    elif command == "report":
        if gps_state == "running":
            pos = read_gps_position()
            if pos is not None:
                return json.dumps({"lat": pos[0], "lon": pos[1]})
            log_error("No GPS data available; using simulated coordinates.")
            return json.dumps({"lat": 37.7749, "lon": -122.4194})
        else:
            return json.dumps({"status": "stopped"})
    else:
        log_error(f"Invalid command: {command}")
        return json.dumps({"error": "Invalid command"})


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global running
    log_error(f"Received signal {signum}, shutting down...")
    running = False


def cleanup() -> None:
    """Release all resources."""
    global uart, server_socket
    if uart is not None:
        try:
            uart.close()
            log_error("GPS UART closed.")
        except Exception as e:
            log_error(f"Error closing UART: {e}")
        uart = None
    if server_socket is not None:
        try:
            server_socket.close()
            log_error("Server socket closed.")
        except Exception as e:
            log_error(f"Error closing server socket: {e}")
        server_socket = None


def main() -> None:
    """Main function to set up the server and handle client connections."""
    global server_socket, running

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    initialize_gps()

    try:
        server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        server_socket.bind(("127.0.0.1", TCP_PORT))
        server_socket.listen(1)
        server_socket.settimeout(1.0)  # Allow periodic check of `running` flag
        log_error(f"Server listening on 127.0.0.1:{TCP_PORT}")

        while running:
            try:
                conn, addr = server_socket.accept()
                log_error(f"Connection from {addr}")
                with conn:
                    try:
                        data = conn.recv(1024)
                        if not data:
                            continue
                        command = data.decode("utf-8", errors="ignore").strip()
                        response = handle_command(command)
                        conn.sendall(response.encode("utf-8"))
                    except socket.timeout:
                        continue
                    except socket.error as e:
                        log_error(f"Socket error: {e}")
                    except Exception as e:
                        log_error(f"Unexpected error handling client: {e}")
            except socket.timeout:
                continue
            except socket.error as e:
                if running:
                    log_error(f"Socket accept error: {e}")
            except Exception as e:
                if running:
                    log_error(f"Unexpected error in accept loop: {e}")

    except socket.error as e:
        log_error(f"Socket error: {e}")
    except Exception as e:
        log_error(f"Unexpected error: {e}")
    finally:
        cleanup()


