import random
import time
import signal
import sys

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("Error: RPi.GPIO requires root privileges or a Raspberry Pi environment.")
    sys.exit(1)

PUMP_PIN = 17
MOISTURE_THRESHOLD = 30
ITERATIONS = 5
DELAY_SECONDS = 2

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def read_moisture_level():
    return random.randint(0, 100)

def control_water_pump(moisture_level, pump_pin):
    if moisture_level < MOISTURE_THRESHOLD:
        GPIO.output(pump_pin, GPIO.HIGH)
        print(f"  -> Pump ON  (moisture {moisture_level} < {MOISTURE_THRESHOLD})")
    else:
        GPIO.output(pump_pin, GPIO.LOW)
        print(f"  -> Pump OFF (moisture {moisture_level} >= {MOISTURE_THRESHOLD})")

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    try:
        GPIO.setup(PUMP_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        print(f"Error setting up GPIO pin {PUMP_PIN}: {e}")
        GPIO.cleanup()
        sys.exit(1)

    try:
        for i in range(1, ITERATIONS + 1):
            if not _running:
                print("\nInterrupted by signal; exiting loop.")
                break

            moisture = read_moisture_level()
            print(f"[{i}/{ITERATIONS}] Soil Moisture: {moisture}%")
            control_water_pump(moisture, PUMP_PIN)

            if i < ITERATIONS and _running:
                time.sleep(DELAY_SECONDS)

    except Exception as e:
        print(f"Unexpected error during execution: {e}")
    finally:
        try:
            GPIO.output(PUMP_PIN, GPIO.LOW)
        except Exception:
            pass
        GPIO.cleanup()
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

