import smbus
import time
import sys
import signal

try:
    from gpiozero import LED, Buzzer
except Exception as exc:
    print(f"Failed to import gpiozero: {exc}", file=sys.stderr)
    sys.exit(1)

# Constants
I2C_BUS = 1
LIS3DH_ADDR = 0x19
WHO_AM_I_REG = 0x0F
WHO_AM__I_EXPECTED = 0x33
X_AXIS_REG = 0x29
LED_PIN = 21
BUZZER_PIN = 20
THRESHOLD_LOW = 0.3
THRESHOLD_HIGH = 0.7
SAMPLE_INTERVAL = 0.1
DISPLAY_INTERVAL = 1.0

# Global resources for cleanup
led = None
buzzer = None
bus = None
running = True


def cleanup():
    """Turn off outputs and release resources."""
    global led, buzzer, bus
    if led is not None:
        try:
            led.off()
            led.close()
        except Exception:
            pass
    if buzzer is not None:
        try:
            buzzer.off()
            buzzer.close()
        except Exception:
            pass
    if bus is not None:
        try:
            bus.close()
        except Exception:
            pass


def signal_handler(signum, frame):
    """Handle SIGTERM/SIGINT for clean shutdown."""
    global running
    running = False


def init_hardware():
    """Initialize GPIO and I2C bus with error checking."""
    global led, buzzer, bus
    try:
        led = LED(LED_PIN)
        buzzer = Buzzer(BUZZER_PIN)
    except Exception as exc:
        print(f"Failed to initialize GPIO outputs: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        bus = smbus.SMBus(I2C_BUS)
    except Exception as exc:
        print(f"Failed to open I2C bus {I2C_BUS}: {exc}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    # Verify LIS3DH identity
    try:
        who_am_i = bus.read_byte_data(LIS3DH_ADDR, WHO_AM_I_REG)
    except Exception as exc:
        print(f"I2C read error reading WHO_AM_I: {exc}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    if who_am_i != WHO_AM_I_EXPECTED:
        print(
            f"Unexpected WHO_AM_I value 0x{who_am_i:02X} "
            f"(expected 0x{WHO_AM_I_EXPECTED:02X})",
            file=sys.stderr,
        )
        cleanup()
        sys.exit(1)


def read_accel_x():
    """Read signed X-axis acceleration from LIS3DH."""
    try:
        data = bus.read_i2c_block_data(LIS3DH_ADDR, X_AXIS_REG, 2)
        raw = (data[1] << 8) | data[0]
        if raw >= 0x8000:
            raw -= 0x10000
        return raw
    except Exception as exc:
        print(f"Error reading accelerometer: {exc}", file=sys.stderr)
        return None


def main():
    global running
    signal.signal(signal.SIGTERM, signal_handler)

    init_hardware()

    try:
        while running:
            x = read_accel_x()
            if x is None:
                # Sensor read failed: turn off both outputs and continue
                try:
                    led.off()
                    buzzer.off()
                except Exception:
                    pass
                time.sleep(DISPLAY_INTERVAL)
                continue

            print(f"Acceleration: {x} g")

            if abs(x) > THRESHOLD_LOW:
                led.on()
            else:
                led.off()

            if abs(x) > THRESHOLD_HIGH:
                buzzer.on()
            else:
                buzzer.off()

            time.sleep(DISPLAY_INTERVAL)

    except KeyboardInterrupt:
        print("\nExiting program...")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

