#!/usr/bin/env python3
"""
Raspberry Pi Arduino Motor Shield controller.

Uses a 74HC595 shift register to drive an L293D motor driver.
Motor 1 PWM on BCM 13, Motor 2 PWM on BCM 12.
Shift-register pins: LATCH=BCM 11, CLOCK=BCM 9, DATA=BCM 10.
PWM frequency 100 Hz.
"""

import logging
import signal
import sys
import time

import RPi.GPIO as GPIO

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)


class Motor:
    """Single DC motor driven through the L293D via a shift register."""

    CLOCKWISE = 0b00000010
    COUNTER_CLOCKWISE = 0b00000001
    STOP = 0b00000000

    def __init__(self, motor_number, pwm_channel, direction_bits, shield):
        if not 0 <= motor_number <= 2:
            raise ValueError("motor_number must be 0, 1, or 2")
        if pwm_channel not in (13, 12):
            raise ValueError("pwm_channel must be 13 or 12")
        if shield is None:
            raise ValueError("shield must not be None")

        self.motor_number = motor_number
        self.pwm_channel = pwm_channel
        self.direction_bits = direction_bits
        self.shield = shield
        self.pwm = None
        self._running = False

    def start(self, duty_cycle=50, frequency=100):
        """Configure PWM and drive the motor at *duty_cycle* percent."""
        if self._running:
            logging.warning("Motor %d already running; changing duty cycle.", self.motor_number)
            self.change_duty_cycle(duty_cycle, frequency)
            return

        try:
            GPIO.setup(self.pwm_channel, GPIO.OUT)
            self.pwm = GPIO.PWM(self.pwm_channel, frequency)
            self.pwm.start(0)
        except Exception as exc:
            logging.error("Failed to start PWM on BCM %d: %s", self.pwm_channel, exc)
            raise

        self._running = True
        self.change_duty_cycle(duty_cycle, frequency)
        logging.info(
            "Motor %d started (PWM BCM %d, %d%% duty @ %d Hz).",
            self.motor_number, self.pwm_channel, duty_cycle, frequency,
        )

    def change_duty_cycle(self, duty_cycle, frequency=100):
        """Change the running duty cycle while keeping the same direction."""
        if not self._running:
            logging.warning("Motor %d not running; cannot change duty cycle.", self.motor_number)
            return
        try:
            self.pwm.ChangeDutyCycle(duty_cycle)
            self.pwm.ChangeFrequency(frequency)
            logging.info(
                "Motor %d duty cycle changed to %d%% @ %d Hz.",
                self.motor_number, duty_cycle, frequency,
            )
        except Exception as exc:
            logging.error("Failed to change duty cycle for Motor %d: %s", self.motor_number, exc)
            raise

    def stop(self):
        """Stop the motor and release PWM resources."""
        if not self._running:
            return
        try:
            if self.pwm is not None:
                self.pwm.stop()
        except Exception as exc:
            logging.error("Error stopping PWM for Motor %d: %s", self.motor_number, exc)
        finally:
            self._running = False
            self.pwm = None
        logging.info("Motor %d stopped.", self.motor_number)

    def set_direction(self, direction_bits):
        """Set the direction bits for this motor in the shift register."""
        if direction_bits not in (self.CLOCKWISE, self.COUNTER_CLOCKWISE, self.STOP):
            raise ValueError("Invalid direction bits")
        self.direction_bits = direction_bits
        self.shield._update_shift_register()
        logging.debug("Motor %d direction set to %s.", self.motor_number, direction_bits)

    def get_direction(self):
        return self.direction_bits

    def get_speed(self):
        if self._running:
            return self.pwm.duty_cycle
        return 0

    def get_max_duty_cycle(self):
