"""
Raspberry Pi Arduino Motor Shield controller.

Uses a 74HC595 shift register to drive an L293D motor driver.
Motor 1 PWM on BCM 13, Motor 2 PWM on BCM 12.
Shift-register pins: LATCH=BCM 11, CLOCK=BCM 9, DATA=BCM 10.
PWM frequency 100 Hz.
"""

import logging
