#!/usr/bin/env python3
"""
Soil Moisture Monitoring and Automated Watering System for Raspberry Pi Zero W.

This program monitors soil moisture using an Adafruit Seesaw soil moisture sensor
(I2C address 0x36) and controls a 12V water pump via a relay on GPIO17.
It includes robust error handling, signal handling, and guaranteed resource cleanup.
"""

import time
import signal
import sys
import board
import busio
import adafruit_seesaw.seesaw
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

# Constants
I2C_ADDRESS = 0x36
PUMP_GPIO_PIN = 17
MOISTURE_THRESHOLD = 500
MONITORING_INTERVAL = 10  # seconds

# Global resources for cleanup
i2c_bus = None
soil_sensor = None
pump = None
running = True


def signal_handler(signum, frame):
    """Handle SIGINT and SIGTERM for graceful shutdown."""
    global running
    print(f"\nReceived signal {signum}, shutting down...")
    running = False


def cleanup():
    """Release all resources safely."""
    global i2c_bus, soil_sensor, pump
    print("Cleaning up resources...")
    if pump is not None:
        try:
            pump.off()
            pump.close()
            print("Pump turned off and GPIO released.")
        except GPIOZeroError as e:
            print(f"Error turning off pump: {e}")
    if soil_sensor is not None:
        try:
            soil_sensor.deinit()
            print("Soil sensor deinitialized.")
        except Exception as e:
            print(f"Error deinitializing soil sensor: {e}")
    if i2c_bus is not None:
        try:
            i2c_bus.deinit()
            print("I2C bus deinitialized.")
        except Exception as e:
            print(f"Error deinitializing I2C bus: {e}")
    print("Cleanup complete.")


def initialize_i2c():
    """Initialize the I2C bus."""
    global i2c_bus
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        print("I2C bus initialized successfully.")
        return True
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return False


def initialize_soil_sensor():
    """Initialize the Adafruit Seesaw soil moisture sensor."""
    global soil_sensor
    try:
        soil_sensor = adafruit_seesaw.seesaw.Seesaw(i2c_bus, addr=I2C_ADDRESS)
        print("Soil moisture sensor initialized successfully.")
        return True
    except ValueError as e:
        print(f"Error: Soil moisture sensor not found at I2C address 0x{I2C_ADDRESS:02X}: {e}")
        return False
    except Exception as e:
        print(f"Error initializing soil moisture sensor: {e}")
        return False


def initialize_pump():
    """Initialize the pump GPIO pin."""
    global pump
    try:
        pump = OutputDevice(PUMP_GPIO_PIN, active_high=True, initial_value=False)
        print("Pump GPIO pin initialized successfully.")
        return True
    except GPIOZeroError as e:
        print(f"Error initializing pump GPIO pin: {e}")
        return False


def read_soil_moisture():
    """Read soil moisture level from the sensor."""
    try:
        moisture = soil_sensor.moisture_read()
        return moisture
    except OSError as e:
        print(f"I2C bus error reading soil moisture: {e}")
        return None
    except Exception as e:
        print(f"Error reading soil moisture: {e}")
        return None


def control_water_pump(moisture_level):
    """Control the water pump based on the moisture level."""
    if moisture_level is None:
        print("Skipping pump control due to sensor read error.")
        return

    if moisture_level < MOISTURE_THRESHOLD:
        try:
            pump.on()
            print("Water pump activated.")
        except GPIOZeroError as e:
            print(f"Error activating pump: {e}")
    else:
        try:
            pump.off()
            print("Water pump deactivated.")
        except GPIOZeroError as e:
            print(f"Error deactivating pump: {e}")


def main():
    """Main program loop."""
    global running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize hardware
    if not initialize_i2c():
        sys.exit(1)
    if not initialize_soil_sensor():
        cleanup()
        sys.exit(1)
    if not initialize_pump():
        cleanup()
        sys.exit(1)

    print("Starting soil moisture monitoring...")

    try:
        while running:
            moisture = read_soil_moisture()
            if moisture is not None:
                print(f"Soil Moisture: {moisture}")
                control_water_pump(moisture)
            else:
                print("Skipping pump control due to sensor read error.")

            # Sleep in small increments to allow signal handling to interrupt promptly
            for _ in range(MONITORING_INTERVAL):
                if not running:
                    break
                time.sleep(1)

    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

