            )
        except OSError as exc:
            logging.error("Serial port error during init: %s", exc)
            self._client = None
            raise
        except Exception as exc:
            logging.error("Unexpected error opening %s: %s", port, exc)
            self._client = None
            raise

    # ------------------------------------------------------------------
    # Resource management
    # ------------------------------------------------------------------
    def close(self) -> None:
        """Release the serial port cleanly."""
        if self._client is not None:
            try:
                if self._connected:
