    laser = Laser(17)
    aim = Aim(ld=0.5, sd=0.2)
    aim.laser = laser

    def cleanup(signum=None, frame=None):
        laser.close()
        if GPIO is not None:
            GPIO.cleanup()
        sys.exit(0)

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        targets = [1, 3, 5]
        aim.aim(targets)
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

