import signal
import sys
import json
from flask import Flask, request, jsonify

try:
    from gpiozero import OutputDevice
    from gpiozero.exc import GPIOZeroError
except ImportError:
    print("Error: gpiozero is not installed. Install with: pip install gpiozero", file=sys.stderr)
    sys.exit(1)

app = Flask(__name__)

RELAY_PIN = 23
relay = None


def cleanup(signum=None, frame=None):
    """Release GPIO resources cleanly on exit or signal."""
    global relay
    if relay is not None:
        try:
            relay.close()
        except Exception:
            pass
        relay = None
    if signum is not None:
        sys.exit(0)


@app.route('/relay', methods=['POST'])
def handle_relay():
    """Handle POST requests to /relay and control the relay."""
    try:
        data = request.get_json(silent=True)
        if data is None:
            return jsonify({'error': 'Invalid request: missing or invalid JSON body'}), 400

        if 'state' not in data:
            return jsonify({'error': 'Invalid request: "state" key is required'}), 400

        relay_state = data['state']
        if relay_state not in ('on', 'off'):
            return jsonify({'error': 'Invalid request: "state" must be "on" or "off"'}), 400

        if relay is None:
            return jsonify({'error': 'Relay GPIO not initialized'}), 500

        if relay_state == 'on':
            relay.on()
        else:
            relay.off()

        return jsonify({'status': 'Relay state changed'}), 200

    except GPIOZeroError as e:
        print(f"GPIO error: {e}", file=sys.stderr)
        return jsonify({'error': 'Internal GPIO error'}), 500
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
        return jsonify({'error': 'Internal server error'}), 500


if __name__ == '__main__':
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        relay = OutputDevice(RELAY_PIN)
    except GPIOZeroError as e:
        print(f"Failed to initialize GPIO {RELAY_PIN}: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected GPIO init error: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        app.run(host='0.0.0.0', port=5000)
    finally:
        cleanup()

