import serial
import time
import logging
import signal
import sys

logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1

_running = True


def _signal_handler(signum, frame):
    global _running
    logging.info(f"Received signal {signum}; initiating shutdown.")
    _running = False


def create_relay_port(port, baudrate, timeout):
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        ser.reset_input_buffer()
        logging.info(f"Serial port {port} opened at {baudrate} baud.")
        return ser
    except serial.SerialException as e:
        logging.error(f"Failed to open serial port {port}: {e}")
        return None
    except OSError as e:
        logging.error(f"OS error opening {port}: {e}")
        return None


def send_relay_command(serial_port, command):
    try:
        payload = command.encode('ascii')
        bytes_written = serial_port.write(payload)
        serial_port.flush()
        if bytes_written != len(payload):
            logging.warning(
                f"Short write: {bytes_written}/{len(payload)} bytes for '{command}'. "
                "Device may have buffered data."
            )
        else:
            logging.info(f"Sent command: {command}")
    except serial.SerialException as e:
        logging.error(f"Serial communication error: {e}")
    except OSError as e:
        logging.error(f"OS error during write: {e}")


def control_relay(serial_port):
    global _running
    while _running:
        send_relay_command(serial_port, 'RELAY1 ON')
        if not _running:
            break
        time.sleep(5)
        send_relay_command(serial_port, 'RELAY1 OFF')
        if _running:
            time.sleep(5)


def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    serial_connection = create_relay_port(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if serial_connection is None:
        logging.error("Could not establish serial connection. Exiting.")
        sys.exit(1)

    try:
        control_relay(serial_connection)
    except Exception as e:
        logging.error(f"Unexpected error in control loop: {e}")
    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            logging.info("Serial port closed.")


if __name__ == "__main__":
    main()

