import time
import signal
import sys

try:
    from adafruit_servokit import ServoKit
except ImportError:
    ServoKit = None

# Constants
I2C_BUS = 1
I2C_ADDRESS = 0x40
SERVO_CHANNEL = 0
GRAB_ANGLE = 90
RELEASE_ANGLE = 150
STEP_DEGREES = 5
STEP_DELAY = 0.04
MIN_ANGLE = 0
MAX_ANGLE = 180

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def initialize_kit():
    """Initialize the ServoKit on the specified I2C bus and address."""
    if ServoKit is None:
        raise RuntimeError("adafruit_servokit module not available")
    try:
        kit = ServoKit(channels=16, i2c=None, address=I2C_ADDRESS)
        return kit
    except OSError as e:
        raise RuntimeError(f"Failed to initialize ServoKit on I2C bus {I2C_BUS} at 0x{I2C_ADDRESS:02X}: {e}") from e
    except Exception as e:
        raise RuntimeError(f"Unexpected error initializing ServoKit: {e}") from e


def validate_channel(channel):
    """Validate that the provided channel is within the supported range (0-15)."""
    if not isinstance(channel, int) or not (0 <= channel <= 15):
        raise ValueError(f"Invalid servo channel: {channel}. Must be an integer between 0 and 15.")


def validate_angle(angle):
    """Validate that the provided angle is within the supported range (0-180 degrees)."""
    if not isinstance(angle, (int, float)) or not (MIN_ANGLE <= angle <= MAX_ANGLE):
        raise ValueError(f"Invalid angle: {angle}. Must be a number between {MIN_ANGLE} and {MAX_ANGLE}.")


def move_servo(kit, servo_channel, target_angle):
    """
    Move a servo to the specified target angle in 5-degree steps with a 0.04s delay.
    """
    validate_channel(servo_channel)
    validate_angle(target_angle)

    try:
        current_angle = kit.servo[servo_channel].angle
        if current_angle is None:
            current_angle = 0
        current_angle = int(current_angle)

        step = STEP_DEGREES if target_angle > current_angle else -STEP_DEGREES

        angle = current_angle
        while (step > 0 and angle < target_angle) or (step < 0 and angle > target_angle):
            angle += step
            kit.servo[servo_channel].angle = float(angle)
            time.sleep(STEP_DELAY)

        kit.servo[servo_channel].angle = float(target_angle)

    except OSError as e:
        raise RuntimeError(f"I2C communication error moving servo {servo_channel}: {e}") from e
    except ValueError as e:
        raise RuntimeError(f"Invalid servo angle specified: {e}") from e
    except Exception as e:
        raise RuntimeError(f"Unexpected error moving servo {servo_channel}: {e}") from e


def grab_object(kit, servo_channel=SERVO_CHANNEL):
    """Grab the object by moving the servo to the grab position (90 degrees)."""
    validate_channel(servo_channel)
    move_servo(kit, servo_channel, GRAB_ANGLE)


def release_object(kit, servo_channel=SERVO_CHANNEL):
    """Release the object by moving the servo to the release position (150 degrees)."""
    validate_channel(servo_channel)
    move_servo(kit, servo_channel, RELEASE_ANGLE)


def cleanup(kit=None):
    """Release all servo channels to a safe position (0 degrees)."""
    if kit is None:
        return
    try:
        for i in range(16):
            kit.servo[i].angle = 0
    except Exception:
        pass


def main():
    """Main function to demonstrate servo control."""
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    kit = None
    try:
        kit = initialize_kit()
        print("ServoKit initialized successfully.")

        grab_object(kit, SERVO_CHANNEL)
        time.sleep(1)

        if not _running:
            return

        release_object(kit, SERVO_CHANNEL)
        time.sleep(1)

    except RuntimeError as e:
        print(f"Error: {e}", file=sys.stderr)
    except Exception as e:
        print(f"An unexpected error occurred: {e}", file=sys.stderr)
    finally:
        cleanup(kit)
        print("Program finished.")


if __name__ == "__main__":
    main()

