import logging
from typing import Optional

try:
    from gpiozero import OutputDevice
except ImportError:
    logging.error("gpiozero is required. Install with: pip install gpiozero")
    sys.exit(1)

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

PUMP_PIN = 20
LIGHT_PIN = 21


def apply_intent(intent: str, pump: OutputDevice, light: OutputDevice) -> None:
    """Apply the named intent to the pump and light."""
    if intent == "pump_on":
        pump.on()
        logging.info("Pump turned ON")
    elif intent == "pump_off":
        pump.off()
        logging.info("Pump turned OFF")
    elif intent == "light_toggle":
        light.toggle()
        logging.info("Light toggled")
    else:
        logging.warning("Unknown intent: %s", intent)


def parse_phrase(phrase: str) -> Optional[str]:
    """Return the intent name for a phrase, or None if unrecognised."""
    mapping = {
        "turn the pump on": "pump_on",
        "switch the light": "light_toggle",
        "turn pump off": "pump_off",
    }
    for key, value in mapping.items():
        if key.lower() in phrase.lower():
            return value
    return None


def cleanup(pump: Optional[OutputDevice], light: Optional[OutputDevice]) -> None:
    """Turn off both actuators and release resources."""
    for dev, name in ((pump, "pump"), (light, "light")):
        if dev is not None:
            try:
                dev.off()
                dev.close()
                logging.info("%s turned OFF and closed", name)
            except Exception as exc:
                logging.error("Error closing %s: %s", name, exc)


def main() -> None:
    pump: Optional[OutputDevice] = None
    light: Optional[OutputDevice] = None

    try:
        pump = OutputDevice(PUMP_PIN)
        light = OutputDevice(LIGHT_PIN)
        logging.info("GPIO devices initialised (pump=BCM%d, light=BCM%d)", PUMP_PIN, LIGHT_PIN)

        test_phrases = [
            "turn the pump on",
            "switch the light",
            "turn pump off",
            "unknown command",
        ]
        for phrase in test_phrases:
            intent = parse_phrase(phrase)
            if intent is not None:
                apply_intent(intent, pump, light)
            else:
                logging.warning("No intent found for phrase: %s", phrase)

    except KeyboardInterrupt:
        logging.info("Interrupted by user")
    except Exception as exc:
        logging.error("Unexpected error: %s", exc)
    finally:
        cleanup(pump, light)


if __name__ == "__main__":
    main()

