import RPi.GPIO as GPIO
import time
import logging
import signal
import sys

logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

RELAY_PIN = 24
PULSE_DURATION = 0.4
PULSE_DELAY = 1.0
NUM_PULSES = 3


class SolenoidController:
    """
    Controls a solenoid via a relay module on a Raspberry Pi.
    """

    def __init__(self, relay_pin):
        self.relay_pin = relay_pin
        self._initialized = False

    def setup(self):
        """Sets up the GPIO pin for relay control."""
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.relay_pin, GPIO.OUT, initial=GPIO.LOW)
            self._initialized = True
            logging.info("GPIO setup complete on pin %d", self.relay_pin)
        except Exception as e:
            logging.error("GPIO setup failed: %s", e)
            raise

    def pulse(self, duration):
        """Activates the relay for a specified duration."""
        if not self._initialized:
            raise RuntimeError("GPIO not initialized. Call setup() first.")
        try:
            GPIO.output(self.relay_pin, GPIO.HIGH)
            time.sleep(duration)
            GPIO.output(self.relay_pin, GPIO.LOW)
        except Exception as e:
            logging.error("Relay pulse failed: %s", e)
            self.deenergize()
            raise

    def deenergize(self):
        """De-energizes the relay to ensure safety."""
        if self._initialized:
            try:
                GPIO.output(self.relay_pin, GPIO.LOW)
                logging.info("Relay de-energized.")
            except Exception as e:
                logging.error("Failed to de-energize relay: %s", e)

    def cleanup(self):
        """Cleans up GPIO resources."""
        if self._initialized:
            try:
                GPIO.cleanup()
                self._initialized = False
                logging.info("GPIO cleanup complete.")
            except Exception as e:
                logging.error("GPIO cleanup failed: %s", e)


def signal_handler(signum, frame):
    """Handles termination signals for graceful shutdown."""
    logging.info("Received signal %d, shutting down...", signum)
    sys.exit(0)


def main():
    """Main function to control the solenoid."""
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    solenoid = SolenoidController(RELAY_PIN)
    try:
        solenoid.setup()
        for i in range(NUM_PULSES):
            logging.info("Pulse %d/%d", i + 1, NUM_PULSES)
            solenoid.pulse(PULSE_DURATION)
            if i < NUM_PULSES - 1:
                time.sleep(PULSE_DELAY)
    except Exception as e:
        logging.error("An error occurred: %s", e)
    finally:
        solenoid.deenergize()
        solenoid.cleanup()


if __name__ == "__main__":
    main()

