import time
import csv
import signal
import sys
from datetime import datetime

try:
    import smbus2 as smbus
except ImportError:
    import smbus

# INA219 constants
INA219_ADDRESS = 0x40
INA219_REG_CONFIG = 0x00
INA219_REG_SHUNT_VOLTAGE = 0x01
INA219_REG_BUS_VOLTAGE = 0x02
INA219_REG_POWER = 0x03
INA219_REG_CURRENT = 0x04
INA219_REG_CALIBRATION = 0x05

# Configuration: ±3.2 A, 0.1 Ω shunt, 12-bit, continuous
INA219_CONFIG_VALUE = 0x218F

# Calibration: 0.1 Ω shunt, ±3.2 A range
SHUNT_VOLTAGE = 0.1
MAX_CURRENT = 3.2

CSV_FILE = "device_power.csv"
ALERT_THRESHOLD = 45.0
SAMPLE_COUNT = 60
SAMPLE_INTERVAL = 1.0

running = True


def signal_handler(signum, frame):
    global running
    running = False


def read_ina219_register(bus, register):
    try:
        return bus.read_word_data(INA219_ADDRESS, register)
    except OSError as e:
        print(f"I2C read error at register 0x{register:02X}: {e}", file=sys.stderr)
        return None


def write_ina219_register(bus, register, value):
    try:
        bus.write_word_data(INA219_ADDRESS, register, value)
        return True
    except OSError as e:
        print(f"I2C write error at register 0x{register:02X}: {e}", file=sys.stderr)
        return False


def configure_ina219(bus):
    if not write_ina219_register(bus, INA219_REG_CONFIG, INA219_CONFIG_VALUE):
        return False
    if not write_ina219_register(bus, INA219_REG_CALIBRATION, int(0.04096 / (SHUNT_VOLTAGE * 1000))):
        return False
    return True


def read_bus_voltage(bus):
    raw = read_ina219_register(bus, INA219_REG_BUS_VOLTAGE)
    if raw is None:
        return None
    return (raw >> 3) * 4.0


def read_shunt_voltage(bus):
    raw = read_ina219_register(bus, INA219_REG_SHUNT_VOLTAGE)
    if raw is None:
        return None
    return (raw >> 1) * 0.000005


def read_current(bus):
    raw = read_ina219_register(bus, INA219_REG_CURRENT)
    if raw is None:
        return None
    return (raw >> 1) * 0.1


def read_power(bus):
    raw = read_ina219_register(bus, INA219_REG_POWER)
    if raw is None:
        return None
    return (raw >> 1) * 2.0


def main():
    global running

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        bus = smbus.SMBus(1)
    except OSError as e:
        print(f"Failed to open I2C bus 1: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        if not configure_ina219(bus):
            print("INA219 configuration failed; check wiring and address.", file=sys.stderr)
            sys.exit(1)

        try:
            with open(CSV_FILE, "w", newline="") as csvfile:
                writer = csv.writer(csvfile)
                writer.writerow(["Timestamp", "Bus Voltage (V)", "Current (A)", "Power (W)"])

                sample_index = 0
                while running and sample_index < SAMPLE_COUNT:
                    bus_voltage = read_bus_voltage(bus)
                    shunt_voltage = read_shunt_voltage(bus)
                    current = read_current(bus)
                    power = read_power(bus)

                    if bus_voltage is None or shunt_voltage is None or current is None or power is None:
                        print("Sensor read error; skipping sample.", file=sys.stderr)
                        time.sleep(SAMPLE_INTERVAL)
                        sample_index += 1
                        continue

                    timestamp = datetime.now().isoformat(timespec="seconds")
                    writer.writerow([timestamp, f"{bus_voltage:.3f}", f"{current:.3f}", f"{power:.2f}"])
                    csvfile.flush()

                    if power > ALERT_THRESHOLD:
                        print(f"ALERT: Power {power:.2f} W exceeds threshold {ALERT_THRESHOLD} W")

                    sample_index += 1
                    if running and sample_index < SAMPLE_COUNT:
                        time.sleep(SAMPLE_INTERVAL)

        except OSError as e:
            print(f"File I/O error: {e}", file=sys.stderr)

    finally:
        try:
            bus.close()
        except Exception:
            pass


if __name__ == "__main__":
    main()

