import signal
import sys
from datetime import datetime
from smbus2 import SMBus, i2c_msg

# DS1338 I2C address (default when A0/A1/A2 pins are tied to GND)
DS1338_ADDR = 0x68

# Register addresses
REG_SECONDS = 0x00
REG_MINUTES = 0x01
REG_HOURS = 0x02
REG_DAY = 0x03
REG_DATE = 0x04
REG_MONTH = 0x05
REG_YEAR = 0x06
REG_CONTROL = 0x07

# Bit masks
CHR_BIT = 0x80
HOUR_12_BIT = 0x40
HOUR_12_MASK = 0x1F


class DS1338Error(Exception):
    """Custom exception for DS1338 RTC errors."""
    pass


class DS1338:
    """
    A class to represent the DS1338 Real-Time Clock (RTC) chip.
    Provides methods for reading and writing date/time and validating input.
    """

    def __init__(self, i2c_bus=1, address=DS1338_ADDR):
        """
        Initializes the DS1338 object and verifies the device presence.

        Args:
            i2c_bus (int): The I2C bus number (default: 1).
            address (int): The I2C address of the DS1338 (default: 0x68).

        Raises:
            DS1338Error: If the device is not found or communication fails.
        """
        self.address = address
        self._bus = None
        try:
            self._bus = SMBus(i2c_bus)
        except OSError as e:
            raise DS1338Error(f"Failed to open I2C bus {i2c_bus}: {e}") from e

        # Verify device presence
        try:
            self._bus.read_byte_data(self.address, REG_SECONDS)
        except OSError as e:
            self.close()
            raise DS1338Error(
                f"No DS1338 found at address 0x{self.address:02X} on bus {i2c_bus}: {e}"
            ) from e

    def close(self):
        """Releases the I2C bus handle."""
        if self._bus is not None:
            try:
                self._bus.close()
            except OSError:
                pass
            self._bus = None

    def _write_register(self, register, data):
        """Writes a byte of data to the specified register."""
        try:
            self._bus.write_byte_data(self.address, register, data)
        except OSError as e:
            raise DS1338Error(
                f"I2C write error to register 0x{register:02X}: {e}"
            ) from e

    def _read_register(self, register):
        """Reads a byte of data from the specified register."""
        try:
            return self._bus.read_byte_data(self.address, register)
        except OSError as e:
            raise DS1338Error(
                f"I2C read error from register 0x{register:02X}: {e}"
            ) from e

    @staticmethod
    def _bcd_to_int(bcd):
        """Converts a BCD byte to an integer."""
        return (bcd >> 4) * 10 + (bcd & 0x0F)

    @staticmethod
    def _int_to_bcd(integer):
        """Converts an integer (0-99) to BCD format."""
        if not 0 <= integer <= 99:
            raise ValueError(f"Integer must be between 0 and 99, got {integer}")
        return ((integer // 10) << 4) | (integer % 10)

    def read_all(self):
        """Reads all time and date registers and returns their integer values."""
        seconds = self._bcd_to_int(self._read_register(REG_SECONDS) & 0x7F)
        minutes = self._bcd_to_int(self._read_register(REG_MINUTES))
        hours_raw = self._read_register(REG_HOURS)
        hours = self._bcd_to_int(hours_raw & HOUR_12_MASK)
        day = self._bcd_to_int(self._read_register(REG_DAY))
        date = self._bcd_to_int(self._read_register(REG_DATE))
        month = self._bcd_to_int(self._read_register(REG_MONTH))
        year = self._bcd_to_int(self._read_register(REG_YEAR))

        if hours_raw & HOUR_12_BIT:
            hours += 12

        return {
            "seconds": seconds,
            "minutes": minutes,
            "hours": hours,
            "day": day,
            "date": date,
            "month": month,
            "year": year,
        }

    def read_datetime(self, century=21):
        """Reads the date and time and returns a datetime object."""
        time_data = self.read_all()
        year = (century - 1) * 100 + time_data["year"]
        return datetime(
            year,
            time_data["month"],
            time_data["date"],
            time_data["hours"],
            time_data["minutes"],
            time_data["seconds"],
        )

    def write_all(self, seconds=None, minutes=None, hours=None, day=None,
                  date=None, month=None, year=None):
        """Writes time and date data to the RTC."""
        current = self.read_all()

        if seconds is not None:
            if not 0 <= seconds <= 59:
                raise ValueError("Seconds must be between 0 and 59")
            current["seconds"] = seconds

        if minutes is not None:
            if not 0 <= minutes <= 59:
                raise ValueError("Minutes must be between 0 and 59")
            current["minutes"] = minutes

        if hours is not None:
            if not 0 <= hours <= 23:
                raise ValueError("Hours must be between 0 and 23")
            current["hours"] = hours

        if day is not None:
            if not 1 <= day <= 7:
                raise ValueError("Day must be between 1 and 7")
            current["day"] = day

        if date is not None:
            if not 1 <= date <= 31:
                raise ValueError("Date must be between 1 and 31")
            current["date"] = date

        if month is not None:
            if not 1 <= month <= 12:
                raise ValueError("Month must be between 1 and 12")
            current["month"] = month

        if year is not None:
            current["year"] = year

        self._write_register(REG_SECONDS, self._int_to_bcd(current["seconds"]))
        self._write_register(REG_MINUTES, self._int_to_bcd(current["minutes"]))
        hours_bcd = self._int_to_bcd(current["hours"])
        if current["hours"] >= 12:
            hours_bcd |= HOUR_12_BIT
        self._write_register(REG_HOURS, hours_bcd)
        self._write_register(REG_DAY, self._int_to_bcd(current["day"]))
        self._write_register(REG_DATE, self._int_to_bcd(current["date"]))
        self._write_register(REG_MONTH, self._int_to_bcd(current["month"]))
        self._write_register(REG_YEAR, self._int_to_bcd(current["year"] % 100))


def main():
    rtc = None
    try:
        rtc = DS1338(i2c_bus=1, address=DS1338_ADDR)
        print("DS1338 initialized successfully.")

        now = datetime.now()
        print(f"Current system time: {now}")

        rtc.write_all(
            seconds=now.second,
            minutes=now.minute,
            hours=now.hour,
            day=now.isoweekday(),
            date=now.day,
            month=now.month,
            year=now.year % 100,
        )
        print("Time written to DS1338.")

        rtc_time = rtc.read_datetime()
        print(f"Time read from DS1338: {rtc_time}")

    except DS1338Error as e:
        print(f"Error: {e}", file=sys.stderr)
    except ValueError as e:
        print(f"Value error: {e}", file=sys.stderr)
    finally:
        if rtc is not None:
            rtc.close()


def _signal_handler(signum, frame):
    print(f"\nReceived signal {signum}, exiting.", file=sys.stderr)
    sys.exit(0)


if __name__ == "__main__":
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    main()

