import signal
import threading
import time

import board
import busio
import digitalio


class EEPROM:
    """Thread-safe SPI EEPROM reader/writer for a 25LC040 (or compatible) 4 Kb chip."""

    def __init__(self, spi, cs_pin):
        self.spi = spi
        self.cs = digitalio.DigitalInOut(cs_pin)
        self.cs.direction = digitalio.Direction.OUTPUT
        self.cs.value = True  # idle high
        self.lock = threading.Lock()

    def write(self, address, data):
        """Write *data* (bytes) to *address* (24-bit)."""
        with self.lock:
            self.cs.value = False
            try:
                self.spi.writeto(bytes([address >> 16, (address >> 8) & 0xFF, address & 0xFF]), data)
            finally:
                self.cs.value = True

    def read(self, address, length):
        """Read *length* bytes from *address* (24-bit)."""
        with self.lock:
            self.cs.value = False
            try:
                self.spi.writeto(bytes([address >> 16, (address >> 8) & 0xFF, address & 0xFF]),
                                 bytes([0x00] * length))
                return bytes(self.spi.read(length))
            finally:
                self.cs.value = True

    def close(self):
        """Release SPI and CS resources."""
        try:
            self.cs.deinit()
        except Exception:
            pass
        try:
            self.spi.deinit()
        except Exception:
            pass


def write_thread(eeprom, address, data):
    eeprom.write(address, data)


def read_thread(eeprom, address, length):
    return eeprom.read(address, length)


def main():
    spi = None
    eeprom = None
    shutdown = threading.Event()

    def _signal_handler(signum, frame):
        shutdown.set()

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        spi = busio.SPI(board.SCK, MOSI=board.MOSI, MISO=board.MISO)
        while not spi.try_lock():
            if shutdown.is_set():
                return
            time.sleep(0.01)
        spi.configure(baudrate=1_000_000, phase=0, polarity=0)
        spi.unlock()

        eeprom = EEPROM(spi, board.D5)

        data = b'1234567890ABCDEF'
        w = threading.Thread(target=write_thread, args=(eeprom, 0, data), daemon=True)
        r = threading.Thread(target=read_thread, args=(eeprom, 0, len(data)), daemon=True)

        w.start()
        w.join()
        if w.exception:
            print(f"Write error: {w.exception}")
            return

        r.start()
        r.join()
        if r.exception:
            print(f"Read error: {r.exception}")
            return

        read_back = r.result()
        print(f"Wrote: {data!r}")
        print(f"Read:  {read_back!r}")

    except Exception as exc:
        print(f"Error: {exc}")
    finally:
        if eeprom is not None:
            eeprom.close()
        if spi is not None:
            try:
                spi.deinit()
            except Exception:
                pass


if __name__ == "__main__":
    main()

