import serial
import time
import signal
import sys

ESP_OK = b"OK"
ESP_ERROR = b"ERROR"
ESP_FAIL = b"FAIL"
ESP_READY = b"ready"
ESP_WIFI_CONNECTED = b"WIFI CONNECTED"
ESP_WIFI_GOT_IP = b"WIFI GOT IP"
ESP_WIFI_DISCONNECT = b"WIFI DISCONNECT"
ESP_CLOSED = b"CLOSED"
ESP_IPD = b"+IPD,"


class ESP8266:
    def __init__(self, port="/dev/serial0", baud_rate=115200, timeout=1.0):
        self.port = port
        self.baud_rate = baud_rate
        self.timeout = timeout
        self.uart = None
        try:
            self.uart = serial.Serial(
                port=port,
                baudrate=baud_rate,
                timeout=timeout,
                write_timeout=timeout,
            )
        except serial.SerialException as e:
            print(f"Error opening UART port {port}: {e}")
            raise

    def _send_command(self, command, timeout=None, terminators=(ESP_OK, ESP_ERROR, ESP_FAIL)):
        if not self.uart or not self.uart.is_open:
            print("UART port is not open.")
            return None
        try:
            self.uart.reset_input_buffer()
            self.uart.write(command)
            self.uart.flush()
            if timeout is None:
                timeout = self.timeout
            response = b""
            deadline = time.monotonic() + timeout
            while time.monotonic() < deadline:
                if self.uart.in_waiting > 0:
                    chunk = self.uart.read(self.uart.in_waiting)
                    if chunk:
                        response += chunk
                        for term in terminators:
                            if term in response:
                                return response
                else:
                    time.sleep(0.01)
            return response if response else None
        except serial.SerialException as e:
            print(f"Serial communication error: {e}")
            return None

    def test_connection(self):
        response = self._send_command(b"AT\r\n")
        return response is not None and ESP_OK in response

    def restart(self):
        response = self._send_command(b"AT+RST\r\n")
        if response and ESP_OK in response:
            time.sleep(2)
            return self.test_connection()
        return False

    def connect_wifi(self, ssid, password):
        command = f'AT+CWJAP="{ssid}","{password}"\r\n'.encode()
        response = self._send_command(command, timeout=10)
        return response is not None and ESP_WIFI_CONNECTED in response

    def disconnect_wifi(self):
        response = self._send_command(b"AT+CWQAP\r\n")
        return response is not None and ESP_OK in response

    def get_ip(self):
