import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
ALERT_PIN = 18
THRESHOLD = 50.0
READ_INTERVAL = 1

running = True

def signal_handler(signum, frame):
    global running
    running = False

def cleanup(ser, gpio):
    if ser is not None and ser.is_open:
        try:
            ser.close()
        except Exception:
            pass
    try:
        gpio.cleanup()
    except Exception:
        pass

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    ser = None
    gpio = None
    try:
        import RPi.GPIO as GPIO
        gpio = GPIO
        gpio.setmode(gpio.BCM)
        gpio.setup(ALERT_PIN, gpio.OUT, initial=gpio.LOW)

        try:
            ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
        except serial.SerialException as e:
            print(f"Error opening serial port {SERIAL_PORT}: {e}", file=sys.stderr)
            sys.exit(1)

        while running:
            try:
                raw = ser.readline()
                if not raw:
                    time.sleep(READ_INTERVAL)
                    continue

                line = raw.decode('ascii', errors='replace').strip()
                if not line:
                    time.sleep(READ_INTERVAL)
                    continue

                try:
                    radiation = float(line)
                except ValueError:
                    print(f"Invalid data received (not a float): {line!r}", file=sys.stderr)
                    time.sleep(READ_INTERVAL)
                    continue

                if radiation > THRESHOLD:
                    gpio.output(ALERT_PIN, gpio.HIGH)
                else:
                    gpio.output(ALERT_PIN, gpio.LOW)

                print(f"Radiation Level: {radiation:.2f} uSv/h")
                time.sleep(READ_INTERVAL)

            except serial.SerialException as e:
                print(f"Serial communication error: {e}", file=sys.stderr)
                time.sleep(READ_INTERVAL)

    except ImportError:
        print("RPi.GPIO not available. Install with: pip install RPi.GPIO", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        cleanup(ser, gpio)

if __name__ == "__main__":
    main()

