import sys

# Configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
FLOW_THRESHOLD = 10.0
ALARM_PIN = 17

# Global resources for cleanup
serial_connection = None
running = True


def cleanup():
    """Release serial and GPIO resources."""
    global serial_connection
    if serial_connection is not None:
        try:
            if serial_connection.is_open:
                serial_connection.close()
                print("Serial port closed.")
        except Exception as e:
            print(f"Error closing serial port: {e}")
        finally:
            serial_connection = None


def signal_handler(sig, frame):
    """Handle SIGINT (Ctrl+C) for graceful shutdown."""
    global running
    print("\nProgram terminated by user.")
    running = False


def main():
    global serial_connection, running

    # Register signal handler for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)

    # Initialize serial communication
    try:
        serial_connection = serial.Serial(
            SERIAL_PORT,
            BAUD_RATE,
            timeout=TIMEOUT
        )
        print(f"Serial port {SERIAL_PORT} opened at {BAUD_RATE} baud.")
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error opening serial port: {e}")
        sys.exit(1)

    # Initialize GPIO for flow alarm
    try:
        import RPi.GPIO as GPIO
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(ALARM_PIN, GPIO.OUT, initial=GPIO.LOW)
        print(f"GPIO {ALARM_PIN} configured as output (LOW).")
    except ImportError:
        print("RPi.GPIO not available. Running in simulation mode.")
    except Exception as e:
        print(f"Error initializing GPIO: {e}")
        cleanup()
        sys.exit(1)

    # Main loop
    try:
        while running:
            try:
                # Read a line from the serial port
                raw_data = serial_connection.readline()

                # Decode the data, ignoring empty lines
                if raw_data:
                    data = raw_data.decode('ascii', errors='replace').strip()

                    # Process valid data
                    if data:
                        try:
                            flow_rate = float(data)
                            print(f"Flow Rate: {flow_rate:.2f} L/min")

                            # Control flow alarm
                            if flow_rate > FLOW_THRESHOLD:
                                if 'RPi.GPIO' in sys.modules:
                                    GPIO.output(ALARM_PIN, GPIO.HIGH)
                                print("Flow alarm triggered!")
                            else:
                                if 'RPi.GPIO' in sys.modules:
                                    GPIO.output(ALARM_PIN, GPIO.LOW)

                        except ValueError:
                            print(f"Invalid data received (not a number): {data}")

            except serial.SerialException as e:
                print(f"Serial communication error: {e}")
                # Brief pause before retrying to avoid tight error loop
                time.sleep(1)
            except OSError as e:
                print(f"I/O error: {e}")
                time.sleep(1)

            # Wait for 1 second
            time.sleep(1)

    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        cleanup()
        if 'RPi.GPIO' in sys.modules:
            try:
                import RPi.GPIO as GPIO
                GPIO.cleanup()
                print("GPIO cleaned up.")
            except Exception as e:
                print(f"Error cleaning up GPIO: {e}")


if __name__ == "__main__":
    main()

