import serial
import time
import signal
import sys

SERIAL_PORT = "/dev/serial0"
BAUD_RATE = 9600
TIMEOUT = 1

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def nmea_to_decimal(raw: str, direction: str) -> float:
    """Convert NMEA ddmm.mmmm to decimal degrees."""
    if not raw or not direction:
        raise ValueError("Empty coordinate or direction")
    if not raw.isdigit():
        raise ValueError(f"Non-numeric coordinate: {raw}")
    if len(raw) < 3:
        raise ValueError(f"Coordinate too short: {raw}")
    degrees = int(raw[:-2])
    minutes = float(raw[-2:])
    decimal = degrees + minutes / 60.0
    if direction in ("S", "W"):
        decimal = -decimal
    return round(decimal, 6)

def parse_gprmc(data: str):
    """Parse a $GPRMC sentence and return (lat, lon) or None."""
    if not data.startswith("$GPRMC"):
        return None
    fields = data.split(",")
    if len(fields) < 8:
        return None
    status = fields[2]
    if status != "A":
        return None
    lat_raw = fields[3]
    lat_dir = fields[4]
    lon_raw = fields[5]
    lon_dir = fields[6]
    if not lat_raw or not lat_dir or not lon_raw or not lon_dir:
        return None
    try:
        lat = nmea_to_decimal(lat_raw, lat_dir)
        lon = nmea_to_decimal(lon_raw, lon_dir)
        return lat, lon
    except ValueError as e:
        print(f"[warn] Coordinate parse error: {e}")
        return None

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    ser = None
    try:
        ser = serial.Serial(SERIAL_PORT, baudrate=BAUD_RATE, timeout=TIMEOUT)
        print(f"Opened {SERIAL_PORT} @ {BAUD_RATE} baud")

        while _running:
            try:
                raw = ser.readline()
            except serial.SerialException as e:
                print(f"[error] Serial read failed: {e}")
                break

            if not raw:
                continue

            try:
                line = raw.decode("ascii", errors="replace").strip()
            except Exception as e:
                print(f"[warn] Decode error: {e}")
                continue

            result = parse_gprmc(line)
            if result is not None:
                lat, lon = result
                print(f"Latitude: {lat:.6f}, Longitude: {lon:.6f}")

            time.sleep(1)

    except serial.SerialException as e:
        print(f"[error] Could not open serial port {SERIAL_PORT}: {e}")
    except Exception as e:
        print(f"[error] Unexpected error: {e}")
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print("Serial port closed.")
        print("Exiting.")

if __name__ == "__main__":
    main()

