import signal
import sys
from datetime import datetime

# Configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'gps_coordinates_log.txt'

# Global flag for graceful shutdown
_running = True

def signal_handler(sig, frame):
    """Handle SIGINT (Ctrl+C) for graceful shutdown."""
    global _running
    _running = False

def initialize_serial(port, baudrate, timeout):
    """Initializes the serial port with error handling."""
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        print(f"Serial port {port} opened successfully at {baudrate} baud.")
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port {port}: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error opening serial port: {e}")
        return None

def read_gps_data(serial_port):
    """Reads a line from the serial port and returns it as a string."""
    try:
        raw_line = serial_port.readline()
        if not raw_line:
            return None
        return raw_line.decode('ascii', errors='replace').strip()
    except serial.SerialException as e:
        print(f"Serial read error: {e}")
        return None
    except Exception as e:
        print(f"Unexpected read error: {e}")
        return None

def parse_gps_data(data):
    """Parses a GPGGA sentence and extracts latitude, longitude, and altitude."""
    if not data.startswith('$GPGGA'):
        return None, None, None

    parts = data.split(',')
    if len(parts) < 15:
        return None, None, None

    # Check fix quality: 0 = no fix, 1 = GPS fix, 2 = DGPS fix
    fix_quality = parts[6]
    if fix_quality != '1':
        return None, None, None

    # Extract latitude and longitude
    latitude = decode_coordinate(parts[2], parts[3])
    longitude = decode_coordinate(parts[4], parts[5])

    # Extract altitude (in meters)
    altitude = parts[9] if parts[9] else None

    return latitude, longitude, altitude

def decode_coordinate(coordinate, direction):
    """Decodes a coordinate and direction into a formatted string."""
    if not coordinate or not direction:
        return None
    try:
        degrees = int(coordinate[:2])
        minutes = float(coordinate[2:])
        decimal_degrees = degrees + (minutes / 60.0)
        if direction in ('S', 'W'):
            decimal_degrees = -decimal_degrees
        return f"{decimal_degrees:.6f}"
    except (ValueError, IndexError):
        return None

def log_coordinates(log_file, latitude, longitude, altitude):
    """Logs the coordinates to a file with error handling."""
    timestamp = datetime.now().isoformat()
    log_entry = f"{timestamp} - Latitude: {latitude}, Longitude: {longitude}, Altitude: {altitude} m\n"
    try:
        with open(log_file, 'a') as file:
            file.write(log_entry)
        print(f"Logged: {log_entry.strip()}")
    except IOError as e:
        print(f"Error writing to log file {log_file}: {e}")
    except Exception as e:
        print(f"Unexpected error logging data: {e}")

def main():
    """Main function to read and process GPS data."""
    signal.signal(signal.SIGINT, signal_handler)

    serial_port = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if serial_port is None:
        print("Failed to initialize serial port. Exiting.")
        sys.exit(1)

    try:
        while _running:
            gps_data = read_gps_data(serial_port)
            if gps_data:
                latitude, longitude, altitude = parse_gps_data(gps_data)
                if latitude and longitude:
                    print(f"Latitude: {latitude}, Longitude: {longitude}, Altitude: {altitude} m")
