import serial
import serial.tools.list_ports
import time
import threading
import signal
import sys
import os
from datetime import datetime

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'water_flow_log.txt'
READ_INTERVAL = 1

stop_event = threading.Event()


def log_flow_rate(flow_rate):
    timestamp = datetime.now().isoformat(timespec='seconds')
    log_entry = f"{timestamp} - Flow Rate: {flow_rate} L/min\n"
    try:
        with open(LOG_FILE, 'a', encoding='ascii') as logfile:
            logfile.write(log_entry)
    except OSError as e:
        print(f"Error writing to log file: {e}", file=sys.stderr)


def read_flow_data():
    ser = None
    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
        print(f"Opened {SERIAL_PORT} at {BAUD_RATE} baud.")
        while not stop_event.is_set():
            try:
                raw_line = ser.readline()
                if not raw_line:
                    continue
                line = raw_line.decode('ascii', errors='replace').strip()
                if not line:
                    continue
                flow_rate = float(line)
                print(f"Flow Rate: {flow_rate} L/min")
                log_flow_rate(flow_rate)
            except ValueError:
                print(f"Invalid data received (not a float): {line!r}", file=sys.stderr)
            except serial.SerialException as e:
                print(f"Serial communication error: {e}", file=sys.stderr)
                break
            except OSError as e:
                print(f"I/O error: {e}", file=sys.stderr)
                break
            stop_event.wait(READ_INTERVAL)
    except serial.SerialException as e:
        print(f"Failed to open serial port {SERIAL_PORT}: {e}", file=sys.stderr)
    except OSError as e:
        print(f"OS error opening {SERIAL_PORT}: {e}", file=sys.stderr)
    finally:
        if ser is not None and ser.is_open:
            try:
                ser.close()
                print("Serial port closed.")
            except OSError as e:
                print(f"Error closing serial port: {e}", file=sys.stderr)


def signal_handler(signum, frame):
    print(f"\nSignal {signum} received, stopping...")
    stop_event.set()


def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    reader_thread = threading.Thread(target=read_flow_data, name='FlowReader', daemon=True)
    reader_thread.start()
    try:
        while not stop_event.is_set():
            time.sleep(0.5)
    except KeyboardInterrupt:
        stop_event.set()
    finally:
        stop_event.set()
        reader_thread.join(timeout=5)
        if reader_thread.is_alive():
            print("Reader thread did not stop within timeout.", file=sys.stderr)
        print("Program terminated.")


if __name__ == '__main__':
    main()

