import signal
import sys
import time
import logging
from dataclasses import dataclass
from typing import Optional

import serial

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)


@dataclass
class GPS_readings:
    """Stores GPS readings: latitude, longitude, altitude, and satellite count."""
    latitude: Optional[float] = None
    longitude: Optional[float] = None
    altitude: Optional[float] = None
    num_satellites: Optional[int] = None


class GPSReader:
    """Reads and parses GPS data from a UART device."""

    def __init__(self, port: str = "/dev/serial0", baudrate: int = 9600):
        self.port = port
        self.baudrate = baudrate
        self.serial_port: Optional[serial.Serial] = None
        self._connected = False

    def connect(self) -> bool:
        """Open the UART port. Returns True on success, False on failure."""
        if self._connected:
            logging.warning("Already connected to GPS module.")
            return True
        try:
            self.serial_port = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=1.0,
            )
            self._connected = True
            logging.info(
                "Connected to GPS module on %s at %d baud.", self.port, self.baudrate
            )
            return True
        except serial.SerialException as e:
            logging.error("Failed to connect to GPS module: %s", e)
            self.serial_port = None
            self._connected = False
            return False
        except OSError as e:
            logging.error("OS error opening %s: %s", self.port, e)
            self.serial_port = None
            self._connected = False
            return False

    def disconnect(self) -> None:
        """Close the UART port if open. Guaranteed to never raise."""
        if self.serial_port is not None:
            try:
                if self.serial_port.is_open:
                    self.serial_port.close()
                    logging.info("Disconnected from GPS module.")
            except Exception as e:
                logging.error("Error while disconnecting: %s", e)
            finally:
                self.serial_port = None
                self._connected = False

    def _nmea_to_decimal(self, value: str, direction: str) -> Optional[float]:
        """Convert NMEA ddmm.mmmm to signed decimal degrees."""
        if not value or not direction:
            return None
        try:
            dot = value.index(".")
            deg_len = dot - 2
            degrees = float(value[:deg_len])
            minutes = float(value[deg_len:])
            decimal = degrees + minutes / 60.0
            if direction in ("S", "W"):
                decimal = -decimal
            return decimal
        except (ValueError, IndexError) as e:
            logging.error("NMEA conversion error for %s: %s", value, e)
            return None

    def _validate_checksum(self, sentence: str) -> bool:
        """Validate NMEA checksum (XOR of chars between '$' and '*')."""
        if "*" not in sentence:
            return False
        body, _, csum = sentence.partition("*")
        if not body.startswith("$"):
            return False
        expected = body[1:]
        calculated = 0
        for ch in expected:
            calculated ^= ord(ch)
        try:
            return calculated == int(csum[:2], 16)
        except ValueError:
            return False

    def read_gps_data(self) -> Optional[GPS_readings]:
        """Read one GPGGA sentence and parse it. Returns None on timeout or error."""
        if not self._connected or self.serial_port is None:
            logging.warning("Not connected to GPS module.")
            return None

        try:
            raw = self.serial_port.readline()
        except serial.SerialException as e:
            logging.error("Serial read error: %s", e)
            return None
        except OSError as e:
            logging.error("OS read error: %s", e)
            return None

        if not raw:
            logging.warning("Read timeout: no data received.")
            return None

        try:
            sentence = raw.decode("ascii", errors="replace").strip()
        except Exception as e:
            logging.error("Decode error: %s", e)
            return None

        if not sentence.startswith("$GPGGA"):
            return None

        if not self._validate_checksum(sentence):
            logging.warning("Checksum mismatch or invalid sentence: %s", sentence)
            return None

        fields = sentence.split(",")
        if len(fields) < 15:
            logging.warning("Incomplete GPGGA sentence: %s", sentence)
            return None

        try:
            fix_quality = int(fields[6])
        except ValueError:
            logging.warning("Invalid fix quality: %s", fields[6])
            return None

        if fix_quality == 0:
            logging.debug("No GPS fix (fix_quality=0).")
            return None

        try:
            num_satellites = int(fields[7])
        except ValueError:
            logging.warning("Invalid satellite count: %s", fields[7])
            return None

        latitude = self._nmea_to_decimal(fields[2], fields[3])
        longitude = self._nmea_to_decimal(fields[4], fields[5])

        try:
            altitude = float(fields[9]) if fields[9] else None
        except ValueError:
            logging.warning("Invalid altitude: %s", fields[9])
            altitude = None

        if latitude is None or longitude is None:
            logging.warning("Invalid latitude or longitude.")
            return None

        return GPS_readings(
            latitude=latitude,
            longitude=longitude,
            altitude=altitude,
            num_satellites=num_satellites,
        )


def main() -> None:
    gps = GPSReader()

    def _signal_handler(signum, frame):
        logging.info("Signal %d received, shutting down.", signum)
        gps.disconnect()
        sys.exit(0)

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    if not gps.connect():
        logging.error("Failed to connect to GPS module. Exiting.")
        sys.exit(1)

    try:
        while True:
            gps_data = gps.read_gps_data()
            if gps_data is not None:
                logging.info(
                    "GPS: lat=%.6f, lon=%.6f, alt=%.2f, sats=%s",
                    gps_data.latitude,
                    gps_data.longitude,
                    gps_data.altitude if gps_data.altitude is not None else 0.0,
                    gps_data.num_satellites,
                )
            time.sleep(0.5)
    except Exception as e:
        logging.error("Unexpected error in main loop: %s", e)
    finally:
        gps.disconnect()


if __name__ == "__main__":
    main()

