import serial
import time
import sys

SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'power_consumption.log'


def open_serial_port() -> serial.Serial:
    """Open the UART serial port with error handling."""
    try:
        return serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=TIMEOUT,
        )
    except serial.SerialException as exc:
        print(f"Error opening serial port {SERIAL_PORT}: {exc}", file=sys.stderr)
        raise


def read_power_data(ser: serial.Serial) -> float | None:
    """Read one line from the serial port and parse it as a float power value.

    Returns None if the line is empty or non-numeric.
    Raises ValueError on non-numeric data.
    """
    try:
        raw = ser.readline()
    except serial.SerialException as exc:
        print(f"Error reading from serial port: {exc}", file=sys.stderr)
        return None

    if not raw:
        return None

    line = raw.decode('ascii', errors='replace').strip()
    if not line:
        return None

    try:
        return float(line)
    except ValueError:
        print(f"Warning: non-numeric data received: {line!r}", file=sys.stderr)
        return None


def log_power_data(power: float) -> None:
    """Append a timestamped power-consumption entry to the log file."""
    timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
    entry = f'{timestamp} – Power: {power} W\n'
    try:
        with open(LOG_FILE, 'a', encoding='utf-8') as logfile:
            logfile.write(entry)
    except OSError as exc:
        print(f"Error writing to log file {LOG_FILE}: {exc}", file=sys.stderr)


def main() -> None:
    """Continuously read and log power data from the smart energy meter."""
    ser = open_serial_port()
    try:
        print(f"Listening on {SERIAL_PORT} @ {BAUD_RATE} baud. Press Ctrl+C to stop.")
        while True:
            power = read_power_data(ser)
            if power is not None:
                log_power_data(power)
    except KeyboardInterrupt:
        print("\nProgram stopped by user.")
    finally:
        if ser.is_open:
            ser.close()
            print("Serial port closed.")


if __name__ == '__main__':
    main()

