import time
import signal
import sys

try:
    from bluetooth import BluetoothSocket, BTCONTROL
except ImportError:
    print("Error: bluetooth library not available. Install with: sudo apt install python3-bluetooth")
    sys.exit(1)

BLUETOOTH_DEVICE = "/dev/rfcomm4"
BLUETOOTH_BAUDRATE = 38400
COMMAND_PREFIX = "X"
TRANSMIT_DELAY = 0.1

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def send_command(bt_socket, command):
    full_command = f"{COMMAND_PREFIX}{command}\n"
    bt_socket.send(full_command.encode("utf-8"))

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    bt_socket = None
    try:
        bt_socket = BluetoothSocket(BTCONTROL)
        bt_socket.connect(BLUETOOTH_DEVICE)
        print(f"Connected to {BLUETOOTH_DEVICE} at {BLUETOOTH_BAUDRATE} baud.")

        while _running:
            try:
                user_command = input("Enter command (or 'exit' to quit): ")
            except EOFError:
                print("\nEOF received, exiting.")
                break

            if user_command.lower() == "exit":
                break

            try:
                send_command(bt_socket, user_command)
            except OSError as e:
                raise RuntimeError(f"Failed to send command '{user_command}': {e}") from e

            time.sleep(TRANSMIT_DELAY)

    except RuntimeError:
        raise
    except OSError as e:
        raise RuntimeError(f"Failed to connect to {BLUETOOTH_DEVICE}: {e}") from e
    except KeyboardInterrupt:
        print("\nKeyboardInterrupt received, exiting.")
    finally:
        if bt_socket is not None:
            try:
                bt_socket.close()
                print("Bluetooth connection closed.")
            except OSError as e:
                print(f"Warning: error closing socket: {e}")

if __name__ == "__main__":
    try:
        main()
    except RuntimeError as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

